const GAMES = [
{
  id: "sakura",
  title: "桜色シグナル",
  heroine: "さくら（21歳）",
  desc: "桜舞う駅前で、幼なじみと5年ぶりに再会する。写真展デートの先にあるのは、友達のままの春か、それとも――。",
  cover: "assets/sakura_cover.webp",
  r18: true,
  images: { park: "assets/sakura_park.svg", station: "assets/sakura_station.svg", room: "assets/sakura_room.svg", char: "assets/sakura_char.webp" },
  scenes: [
    { id: "a01", bg: "station", name: "", text: "桜の花びらが、駅前のロータリーに雪みたいに舞っていた。\n――5年ぶりの地元。俺はキャリーバッグを引きながら、待ち合わせの時計台を見上げた。" },
    { id: "a02", name: "", text: "「……悠太？」\n後ろから、懐かしい声がした。" },
    { id: "a03", face: "smile", char: true, name: "さくら", text: "やっぱり悠太だ！　わたし、さくら。覚えてる？　高校のとき、隣の席だった――" },
    { id: "a04", name: "悠太", text: "忘れるわけないだろ。さくら、お前……すげえ綺麗になったな。" },
    { id: "a05", face: "smile", name: "さくら", text: "ふふ、ありがとう。わたし今、近くの写真館で働いてるの。悠太は？　東京の大学、卒業したんだよね。" },
    { id: "a06", name: "", text: "就職で地元に戻ってきたこと、来週から新社会人になることを話すと、さくらは目を輝かせた。" },
    { id: "a07", char: true, name: "さくら", text: "じゃあさ、今度の日曜、空いてる？　わたしの初めての写真展があるの。……来てほしいな、悠太に。" },
    { id: "a08", choice: [
      { text: "「もちろん行くよ」と即答する", jump: "a09", set: { love: 1, promise: 1 } },
      { text: "「予定見てからでいい？」と濁す", jump: "a10", set: { love: 0, promise: 0 } }
    ] },
    { id: "a09", face: "surprise", name: "さくら", text: "ほんと！？　……よかった。じゃあ約束ね、指切り！\n（小指を差し出す手が、少しだけ震えていた）", jump: "a11" },
    { id: "a10", face: "sad", name: "さくら", text: "そ、そっか。うん、無理しないで。……招待券、渡しとくね。\n（笑顔のまま、少しだけ目を伏せた）", jump: "a11" },
    { id: "a11", bg: "park", name: "", text: "――日曜日。写真展の会場は、桜並木の続く公園の小さなギャラリーだった。", jump: "a42" },
    { id: "a12", face: "love", char: true, name: "さくら", text: "来てくれたんだ……！　これ、わたしが一番見てほしかった写真。高校の文化祭のとき、悠太が撮ってくれた桜の写真を、わたしなりに撮り直したの。" },
    { id: "a13", name: "", text: "写真の中の桜は、あの日の放課後とそっくりで。5年間、この人はずっと、あの春を大事に持っていたのだと分かった。" },
    { id: "a14", name: "悠太", text: "さくら。……この写真、すごくいい。お前の気持ちが、まっすぐ伝わってくる。" },
    { id: "a15", face: "shy", name: "さくら", text: "……悠太にそう言ってもらえたら、もう十分。あのね、わたし、ずっと言えなかったことがあって――" },
    { id: "a16", choice: [
      { text: "「俺も同じだ」と気持ちを伝える", jump: "a17", set: { love: 2 } },
      { text: "「今日はありがとう」と話を締める", jump: "a20", set: { love: 0 } }
    ] },
    { id: "a17", name: "悠太", text: "高校のときから、俺もずっとお前が好きだった。社会人になって戻ってきた理由の半分は、正直、お前に会いたかったからだ。" },
    { id: "a18", face: "cry", name: "さくら", text: "……っ！　悠太……わたしも。わたしもずっと、悠太だけだったの。\n（目に涙を浮かべながら、桜色に頬を染めて笑った）" },
    { id: "a19", branch: { flag: "promise", min: 1, then: "a263", else: "a21" } },
    { id: "a20", bgm: "calm", face: "smile", bg: "station", char: true, name: "さくら", text: "今日は来てくれてありがとう。……また、友達として遊ぼうね。\n【NORMAL END ― 友達のままの春】", end: true },
    { id: "a21", bg: "room", name: "", text: "閉館後、二人で並んで歩いた桜並木。どちらからともなく手が触れ、指が絡んだ。\n――その夜、さくらは俺の部屋に寄っていった。" },
    { id: "a22", face: "shy", r18: true, name: "さくら", text: "……悠太、今日は帰りたくない。5年分、ずっと我慢してきたの。わたしを、彼女にして？　……全部、初めてをあげる。" },
    { id: "a23", r18: true, name: "", text: "頷くと、さくらは自分から唇を重ねてきた。最初は触れるだけだったキスが、やがて舌を絡め合う深いものに変わる。桜の香りのする髪が頬をくすぐり、震える指がシャツのボタンをひとつずつ外していく。" },
    { id: "a24", face: "pleasure", r18: true, name: "さくら", text: "んっ、んんっ……悠太の心臓、すごく早い。わたしもだよ……ほら、触ってみて。ずっと悠太のものだった体、確かめて。" },
    { id: "a25", r18: true, name: "", text: "ブラウスのボタンを外し、ブラのホックを解くと、形のいい大きな乳房がふるりと露わになった。先端は既に固く尖っている。手のひらで包んで揉みほぐすと、さくらは甘い声を漏らした。" },
    { id: "a26", face: "pleasure", r18: true, name: "さくら", text: "あっ……あんっ、悠太、そこ弱いの……。高校のときから、悠太にだけ見せるって決めてたんだよ……もっと触って。" },
    { id: "a27", r18: true, name: "", text: "乳首を指で転がし、舌で舐め上げ、吸い付く。さくらは俺の頭を抱き寄せ、背中を弓なりに反らせた。下着越しでも分かるほど、彼女の秘部は既に濡れそぼっていた。" },
    { id: "a28x", face: "pleasure", r18: true, name: "さくら", text: "はぁ、はぁ……悠太、わたしも、触っていい？　……わぁ、こんなに大きくなってる。わたしのせいだよね……嬉しい。" },
    { id: "a29", r18: true, name: "", text: "さくらの細い指が、ズボン越しに俺のものを撫でる。やがて二人とも一糸纏わぬ姿になり、ベッドに倒れ込んだ。さくらは恥ずかしそうに太ももを擦り合わせながら、潤んだ瞳で見上げてくる。" },
    { id: "a30", face: "shy", r18: true, name: "さくら", text: "悠太……わたし、初めてだけど、怖くない。だって相手が悠太だもん。……お願い、わたしの中に、来て。ゆっくりでいいから……全部、入れて。" },
    { id: "a31", r18: true, name: "", text: "指で十分に解してから、震える彼女の脚の間に体を割り入れさせる。入り口は固く狭かったが、愛液で滑る感触と共に、少しずつ、深く、俺を受け入れていった。" },
    { id: "a32", r18: true, name: "さくら", text: "うっ……あ、あぁっ……入って、る……悠太のが、わたしの一番奥まで……。すごい、体の中が全部、悠太でいっぱいだよ……" },
    { id: "a33", r18: true, name: "", text: "最初は痛みに眉を寄せていたさくらも、ゆっくりとした抽送に次第に甘い声を上げ始める。膣壁が絡みつくように締まり、二人の接合部からは濡れた音が響いた。" },
    { id: "a34", face: "pleasure", r18: true, name: "さくら", text: "あんっ、あんっ、あぁ……！　悠太、気持ちいい、気持ちいいよぉ……！　もっと、もっと奥まで突いて……わたし、もう悠太なしじゃダメになっちゃう……" },
    { id: "a35", r18: true, name: "", text: "ペースを上げ、大きな乳房を揉みながら腰を打ち付ける。さくらはシーツを掴み、涙目で喘ぎながら何度も俺の名を呼んだ。やがて彼女の体が大きく跳ね、内壁が強く痙攣する。" },
    { id: "a36", face: "ecstasy", r18: true, name: "さくら", text: "いっ……イク、イッちゃう……！　悠太、悠太ぁ……あああっ……！！　好き、大好き……愛してるぅ……" },
    { id: "a37", r18: true, name: "", text: "絶頂の余韻に震えるさくらを抱きしめながら、俺も限界を迎える。最後の瞬間、彼女は脚を俺の腰に絡め、離さないとばかりにしがみついてきた。" },
    { id: "a38", r18: true, name: "さくら", text: "出して……中に出して、悠太……！　わたしのお腹、悠太の赤ちゃんが欲しいの……。初めても、一番奥も、全部悠太のものにして……" },
    { id: "a39", r18: true, name: "", text: "最奥深く腰を押し付け、熱い迸りを彼女の中へ解き放つ。さくらは歓喜に目を潤ませ、注がれる感触に小さく体を震わせながら、子宮で受け止めるように腰を寄せた。" },
    { id: "a40", r18: true, name: "さくら", text: "あぁ……熱い……悠太のが、いっぱい中に入ってきてる……。わたし、悠太の彼女になれたんだね。……ねえ、もう一回。まだ離れたくないの。", jump: "a53" },
    { id: "a41", r18: true, name: "", text: "その夜、二人は何度も愛し合った。抱き合って眠りに落ちるまで、さくらはずっと俺の胸に頬を寄せていた。窓の外では、桜の花びらが静かに舞い続けていた。", jump: "a28" },
    { id: "a28", face: "love", bg: "room", name: "さくら", text: "……おはよう、悠太。ふふ、恋人の朝って、こんなに幸せなんだね。これからはずっと一緒だよ。", jump: "a67" },
    { id: "a42", bg: "park", name: "", text: "ギャラリーの入り口で、さくらが小さく手を振っていた。白いワンピースに、桜色のカーディガン。待ち合わせらしい待ち合わせに、胸が高鳴る。", jump: "a225" },
    { id: "a43", char: true, name: "さくら", text: "お待たせ、悠太。……ねえ、展示を見る前に、少しだけ並木道を歩かない？　今日の桜、すごく綺麗なの。一緒に見たいな。" },
    { id: "a44", name: "悠太", text: "いいよ。……さくらと歩く桜並木、高校の帰り道みたいだな。" },
    { id: "a45", face: "smile", name: "さくら", text: "覚えてる？　悠太、写真部の部室でいつも居眠りしてて、わたしが起こしに行くのが日課だった。……あの頃のわたし、悠太の隣にいる理由がほしくて、わざわざ遠回りしてたんだよ。" },
    { id: "a46", name: "", text: "花びらの舞う並木道。二人の影が寄り添うように伸びていく。さくらは懐かしそうに目を細め、時折、俺の顔を盗み見ては微笑んだ。", jump: "a149" },
    { id: "a47", face: "serious", name: "さくら", text: "高校の卒業式の日、本当は告白するつもりだったの。でも悠太が東京に行くって聞いて……邪魔しちゃいけないって、引っ込めちゃった。ずっと後悔してたんだ。" },
    { id: "a48", name: "悠太", text: "……俺もだよ。行く前に言えなかったこと、ずっと引っかかってた。だから就職先、地元で探したんだ。" },
    { id: "a49", face: "smile", name: "さくら", text: "ほんとに……？　……ふふ、じゃあ今日は、5年越しのやり直しの日だね。さ、展示を見に行こう。わたしの5年間、全部そこにあるから。" },
    { id: "a50", name: "", text: "手を引かれてギャラリーへ。さくらの手は少し汗ばんで、温かかった。", jump: "a187" },
    { id: "a53", r18: true, name: "", text: "一度休んで、シャワーを浴びた後。それでもさくらは離れようとせず、濡れた髪のまま俺の胸に頬を寄せてきた。下半身は既に、再び熱を持ち始めている。" },
    { id: "a54", r18: true, name: "さくら", text: "ねえ悠太……わたし、もう我慢できない。さっきの余韻で、体が疼いてるの。……今度はわたしが、悠太を気持ちよくしてあげる。" },
    { id: "a55", r18: true, name: "", text: "さくらはベッドに俺を押し倒すと、胸に舌を這わせながら下へと降りていく。初めてのはずの口づけは熱心で、舌を絡め、吸い付くたびに喉を鳴らした。" },
    { id: "a56", face: "pleasure", r18: true, name: "さくら", text: "んっ、んんっ……悠太の、熱い……。わたしの口、気持ちいい？　……もっと奥まで。悠太のもの、わたしの喉で味わいたいの。" },
    { id: "a57", r18: true, name: "", text: "奉仕に限界まで膨らんだところで、さくらは自ら跨ってきた。濡れそぼった秘部が、先端を飲み込んでいく。初めての体位に、彼女は眉を寄せながらも腰を沈めていった。" },
    { id: "a58", face: "surprise", r18: true, name: "さくら", text: "あぁっ……入ってく……わたし、自分から悠太の中に……えっちだね、わたし。でも止まらない……悠太が見てる前で、腰、動いちゃう……" },
    { id: "a59", r18: true, name: "", text: "大きな乳房を揺らしながら、さくらは夢中で腰を振る。膣壁がうねるように絡みつき、結合部からは愛液が溢れて太ももを伝った。さくらの喘ぎは、もう隠す気配もない。" },
    { id: "a60", face: "pleasure", r18: true, name: "さくら", text: "あんっ、あんっ、あぁっ……！　悠太、すごい、奥が擦れて……！　わたし、悠太の上でこんなに乱れてる……見て、もっと見てぇ……" },
    { id: "a61", r18: true, name: "", text: "腰を掴んで下から突き上げると、さくらは大きく絶頂した。そのまま体位を変え、後ろから深く貫くと、彼女はシーツに顔を埋めて嬌声を上げ続けた。" },
    { id: "a62", face: "ecstasy", r18: true, name: "さくら", text: "イグ、またイッちゃう……！　悠太、悠太ぁ……！　好き、大好き……もう、わたしの体は悠太専用なの……！" },
    { id: "a63", r18: true, name: "", text: "高まる限界。さくらは後ろからでも分かるほど子宮を寄せ、二度目の種付けを求めるように腰を落としてきた。" },
    { id: "a64", r18: true, name: "さくら", text: "また中にちょうだい……！　わたしのお腹、悠太の赤ちゃんでいっぱいにして……初めての夜に、二回も……幸せすぎて壊れちゃう……" },
    { id: "a65", r18: true, name: "", text: "最奥で二度目の射精。さくらは歓喜に震え、注がれる熱を子宮で受け止めながら、小さく何度も絶頂を繰り返した。溢れた白濁がシーツに広がっていく。" },
    { id: "a66", face: "love", r18: true, name: "さくら", text: "あぁ……いっぱい……わたしのお腹、ぽかぽかしてる……。悠太、愛してる。ずっとずっと、わたしだけの彼氏でいてね……", jump: "a41" },
    { id: "a67", bg: "park", name: "", text: "――数週間後。恋人になった二人は、週末のたびにデートを重ねていた。今日は河川敷でピクニック。さくらの手作り弁当が、レジャーシートの真ん中に広がる。" },
    { id: "a68", face: "smile", char: true, name: "さくら", text: "はい、卵焼き。悠太の好物だよね。……ふふ、付き合う前から、悠太の好みは全部覚えてたの。高校のとき、お弁当を交換した日から、ずっと。" },
    { id: "a69", name: "悠太", text: "……うまい。本当にうまい。さくら、将来いい奥さんになるよ。" },
    { id: "a70", name: "さくら", text: "お、奥さん……！　……じゃあ、練習させて？　これからも毎週作るから。悠太のためだけに、ね。" },
    { id: "a71", name: "", text: "他愛ない会話と、穏やかな午後。桜は散っても、二人の季節は始まったばかりだった。夕方、帰り道でさくらが俺の袖を引く。", jump: "a111" },
    { id: "a72", name: "さくら", text: "ねえ悠太。今日……わたしの部屋に寄っていかない？　写真の現像、一緒にやりたいし……それと、ね。今夜は、わたしから誘ってもいい？" },
    { id: "a73", bg: "room", name: "", text: "さくらの部屋。写真で埋め尽くされた壁と、桜色のカーテン。現像を終えた頃には外は暗く、二人の距離は自然とゼロになっていた。" },
    { id: "a74", face: "wink", r18: true, name: "さくら", text: "悠太……わたし、最近ずっと考えてたの。初めての夜のこと。……体が覚えちゃって、夜になると疼くの。だから今夜は、全部わたしに任せて。" },
    { id: "a75", r18: true, name: "", text: "さくらは俺をベッドに座らせ、自ら脚の間に跪いた。下着越しに膨らんだものを撫で、舌でなぞるように刺激してくる。初めての時とは違う、大胆な彼女がいた。" },
    { id: "a76", face: "pleasure", r18: true, name: "さくら", text: "んっ……悠太の、もうこんなに硬い。わたしのせいだね。……責任取って、わたしの中でいっぱい気持ちよくしてあげる。" },
    { id: "a77", r18: true, name: "", text: "口での奉仕の後、さくらは服を脱ぎ、大きな乳房と濡れた秘部を晒した。自ら指で割り開き、待ちきれないように腰を揺らす。" },
    { id: "a78", r18: true, name: "さくら", text: "見て、悠太……わたし、もうとろとろ。早く入れて。今日は危険な日なの……でも、悠太のなら、中でいいよ。だって私たち、将来結婚するんだもん。" },
    { id: "a79", r18: true, name: "", text: "求められるまま一気に貫く。慣れた膣は熱く絡みつき、さくらは大きく目を見開いて喘いだ。三度目の夜は、互いの体を知り尽くした者同士の、深く激しいものになった。" },
    { id: "a80", r18: true, name: "さくら", text: "あぁん、あぁっ……！　悠太、すごい、奥が痺れる……！　もっと、もっと突いて……わたし、悠太の子供が本当に欲しいの……！" },
    { id: "a81", r18: true, name: "", text: "体位を変え、抱き合い、脚を絡め、何度も絶頂を繰り返す。さくらは涙目で微笑みながら、射精の瞬間を自ら最奥で迎えに来た。" },
    { id: "a82", face: "ecstasy", r18: true, name: "さくら", text: "出して、悠太……！　中に出して、私を孕ませて……！　あぁっ、イグ、イッちゃう……悠太と一緒に……！！" },
    { id: "a83", r18: true, name: "", text: "最奥深くで射精。さくらは絶頂と共に子宮で受け止め、注がれる熱に幸福そうに震えた。溢れる白濁が、二人の結合部からシーツへと広がる。" },
    { id: "a84", face: "love", r18: true, name: "さくら", text: "あぁ……いっぱい……今日は絶対、できちゃったかも……。ふふ、それでもいいの。悠太の赤ちゃんなら、わたし、幸せに産むから。……愛してる、一生愛してる。", jump: "a93" },
    { id: "a85", bgm: "love", bg: "park", name: "", text: "――翌年の春。駅前の桜並木の下で、さくらは三脚を立て、タイマーをセットして駆け寄ってきた。腕の中の小さな命が、舞い落ちる花びらに手を伸ばしている。\n「はい、笑って。わたしと、悠太と、この子で――撮るよ！」\nシャッターの音が、5年前の春と同じ並木道に響いた。この一枚は、初めての写真展の日に彼女が宣言した「次はもっと大きな展示」の、真ん中に飾られる一枚になる。桜色のシグナルは、今も二人の頭上で青く灯り続けている。\n【GOOD END ― 桜色シグナル】", end: true },
    { id: "a86", bg: "park", name: "", text: "――回想：写真展の前日。搬入作業を手伝うことになり、二人で額縁を運んだ。さくらの手は、緊張で少し震えていた。" },
    { id: "a87", face: "sad", char: true, name: "さくら", text: "明日、誰も来なかったらどうしよう。わたしの写真、みんなに笑われたら……。悠太、わたし、怖いよ。" },
    { id: "a88", name: "悠太", text: "大丈夫。俺が保証する。さくらの写真には人を惹きつける力がある。……ほら、深呼吸して。" },
    { id: "a89", face: "smile", name: "さくら", text: "……うん。ありがとう。悠太がそう言ってくれるなら、頑張れる。あのね、明日の展示、一枚だけ秘密の写真があるの。最後の部屋に掛けるやつ。" },
    { id: "a90", name: "悠太", text: "秘密の写真？　何を撮ったんだよ。" },
    { id: "a91", face: "love", name: "さくら", text: "それは明日のお楽しみ。……ヒントはね、『わたしが一番、大好きなもの』。悠太なら、見たらすぐ分かるよ。" },
    { id: "a92", name: "", text: "作業を終え、夕日の並木道を並んで帰る。さくらは額縁の重さより、明日の期待で胸がいっぱいな様子だった。", jump: "a47" },
    { id: "a93", bg: "room", r18: true, name: "", text: "――数日後の土曜日。さくらから届いたメッセージは、短くて、でも熱かった。『今夜、うちに来て。検査薬、買ってきたの。……使う前に、もう一度だけ確かめたいことがあるの』" },
    { id: "a94", r18: true, name: "さくら", text: "悠太、来てくれた……。ねえ、見て。検査薬、ここにあるよ。でもね、使うのは、まだ後。……今夜はまず、わたしを抱いて？" },
    { id: "a95", r18: true, name: "", text: "玄関で靴も脱ぎきらないうちに、さくらは俺にしがみついてきた。数日ぶりの体温。彼女の唇は、桜の香りと少しの緊張で震えている。" },
    { id: "a96", r18: true, name: "悠太", text: "……分かった。検査の結果なんて、どっちでもいい。俺はさくらと、ずっと一緒にいたい。それだけだよ。" },
    { id: "a97", face: "pleasure", r18: true, name: "さくら", text: "んっ……悠太……ありがとう。わたし、あなたのそういうところが好き。……ねえ、ベッドに行こう？　今夜は、わたしから全部してあげる。" },
    { id: "a98", r18: true, name: "", text: "ベッドに押し倒され、さくらは自ら俺の服を脱がせていく。初めての夜とは違う、慣れた手つき。でも頬は真っ赤で、耳まで染まっている。" },
    { id: "a99", face: "smile", r18: true, name: "さくら", text: "ふふ、悠太の体、覚えちゃった。……ここ、弱いんでしょ？　ほら、こうすると、すぐ大きくなる。わたしのせいだよ、責任取ってね？" },
    { id: "a100", r18: true, name: "", text: "俺のものを口に含み、さくらは熱心に舌を絡ませる。大きな乳房が胸板に押し付けられ、吐息が熱い。限界が近づくと、彼女は嬉しそうに微笑んだ。" },
    { id: "a101", r18: true, name: "さくら", text: "もう、こんなに……。ねえ悠太、入れて。わたしの中、もうとろとろなの。……今度は、わたしが上で動くから。見てて？" },
    { id: "a102", r18: true, name: "", text: "さくらが自ら跨り、濡れそぼった秘部で先端を捉える。ゆっくりと腰を沈め、根元まで飲み込むと、彼女は歓喜の声を上げた。大きな乳房が目の前で揺れる。" },
    { id: "a103", face: "pleasure", r18: true, name: "さくら", text: "あぁっ……入ってる……悠太のが、わたしの一番奥まで……。すごい、気持ちいい……！　わたし、悠太の上でこんなに乱れてる……見て、もっと見てぇ……" },
    { id: "a104", r18: true, name: "", text: "夢中で腰を振るさくら。膣壁がうねるように絡みつき、結合部からは愛液が溢れて太ももを伝う。俺は乳房を揉みながら、下から突き上げた。" },
    { id: "a105", face: "ecstasy", r18: true, name: "さくら", text: "あんっ、あんっ、あぁっ……！　悠太、すごい、奥が痺れる……！　わたし、もうイッちゃう……イグ、イッちゃうぅ……！！" },
    { id: "a106", r18: true, name: "", text: "さくらが大きく絶頂する。体位を変え、後ろから深く貫くと、彼女はシーツに顔を埋めて嬌声を上げ続けた。俺の限界も、もう近い。" },
    { id: "a107", r18: true, name: "さくら", text: "中に出して、悠太……！　今夜も、わたしのお腹にちょうだい……！　検査薬が陽性でも、陰性でも……わたしは、悠太の子が欲しいの……！" },
    { id: "a108", r18: true, name: "", text: "最奥深くで射精。さくらは子宮で受け止めるように腰を寄せ、注がれる熱に幸福そうに震えた。溢れた白濁が、シーツに広がっていく。" },
    { id: "a109", face: "love", r18: true, name: "さくら", text: "あぁ……いっぱい……。ねえ悠太、検査薬、明日一緒に見ようね。……どっちの結果でも、わたし、あなたのそばにいるから。愛してる。" },
    { id: "a110", r18: true, name: "", text: "抱き合ったまま眠りに落ちる。さくらの寝息と、窓の外の桜の香り。――数週間後、あの検査薬の結果が、二人の未来を決めることになる。", jump: "a131" },
    { id: "a111", bg: "station", name: "", text: "袖を引いたさくらが、照れながら言った。「ねえ悠太。……寄り道、していかない？　駅前の商店街、夕方だと屋台が出るの。」" },
    { id: "a112", char: true, name: "さくら", text: "たこ焼きの屋台、高校のときからあるの。……あの頃は、買うお金がなくて匂いだけ嗅いでた。今日は、奢って？" },
    { id: "a113", name: "悠太", text: "もちろんだよ。……って、お前、財布持ってきてないだろ。俺が奢るから、好きなだけ食え。" },
    { id: "a114", face: "smile", name: "さくら", text: "やったぁ！　ふふ、悠太って、昔からこういうとこ変わらないね。困ってる人を、放っておけないところ。" },
    { id: "a115", name: "", text: "屋台の前で、さくらは焼きたてのたこ焼きを頬張った。ソースの匂いと、夕方の人混み。高校の帰り道と、少しだけ違う景色。" },
    { id: "a116", name: "さくら", text: "んっ、あちっ！　はふはふ、熱い、でも美味しい！　ねえ悠太、あーんしてあげる。ほら、口開けて？" },
    { id: "a117", name: "悠太", text: "お、おう。あちっ！　熱い！　……でも、うまいな。さくらがくれると、なんだか三倍うまい気がする。" },
    { id: "a118", face: "smile", name: "さくら", text: "もう、悠太ってば。ふふ、じゃあ今度はわたしが奢る番。あ、あそこのクレープ屋、行こう？" },
    { id: "a119", name: "", text: "クレープ屋の行列に並びながら、さくらは写真の話を始めた。次の写真展のテーマは、『夕方の街の匂い』だという。" },
    { id: "a120", char: true, name: "さくら", text: "ねえ、見て。夕日がビルの間に沈む瞬間。この光、写真にしたいな。悠太、ちょっと待ってて。カメラ、取り出すから。" },
    { id: "a121", name: "", text: "シャッターの音が、商店街のざわめきに混ざる。さくらがファインダーを覗く横顔は、仕事のときの真剣な顔だった。" },
    { id: "a122", face: "smile", name: "さくら", text: "撮れた。ふふ、いい写真。ねえ悠太、この写真、わたしの宝物にする。だって、悠太と歩いた夕方だもん。" },
    { id: "a123", name: "悠太", text: "さくら。お前、ほんとに写真が好きだな。そんなお前を、俺はずっと見ていたい。" },
    { id: "a124", face: "smile", name: "さくら", text: "悠太……。ふふ、ありがとう。ねえ、クレープ、半分こしよう？　わたし、生クリーム苦手なの、忘れてた。" },
    { id: "a125", name: "", text: "半分このクレープを分け合い、商店街を抜ける。空はすっかり茜色で、街灯がひとつ、またひとつと灯り始めた。" },
    { id: "a126", name: "さくら", text: "ねえ悠太。今日、すごく楽しかった。ピクニックも、商店街も、全部。ねえ、明日も、明後日も、こうして歩きたいな。" },
    { id: "a127", name: "悠太", text: "ああ。さくらとなら、どこを歩いても楽しいよ。来週の週末も、空けとく。どこ行く？　海でも、山でも。" },
    { id: "a128", face: "smile", name: "さくら", text: "ふふ、じゃあ決まり。ねえ、もうすぐ、わたしの部屋。今日は長い一日だったね。……でも、まだ終わりにしたくないな。" },
    { id: "a129", name: "", text: "商店街を抜け、マンションの前に着く。さくらの部屋の窓に、桜色のカーテンが見えた。夕日の光が、ガラスに柔らかく映る。" },
    { id: "a130", name: "悠太", text: "さくら。今日は、ほんとに楽しかった。なあ、もう少しだけ、一緒にいたい。", jump: "a72" },
    { id: "a131", bg: "room", r18: true, name: "", text: "――検査薬を見た、あの日の夜。陽性の二本線を、二人で何度も見つめた。窓の外では、桜の花びらが静かに舞っている。" },
    { id: "a132", face: "love", r18: true, name: "さくら", text: "ねえ悠太……わたし、ほんとに……お母さんになるんだね。……ふふ、なんだか、まだ信じられないよ。" },
    { id: "a133", r18: true, name: "悠太", text: "ああ。……さくら、ありがとう。……俺、父親になるんだな。……さくらと、この子を、絶対に守るよ。" },
    { id: "a134", r18: true, name: "", text: "さくらは検査薬をそっと箱にしまい、俺の胸に頬を寄せた。鼓動が、少しだけ早い。" },
    { id: "a135", r18: true, name: "さくら", text: "ねえ、今日は……特別な夜にしよう？　……わたしの体、もう一度、よく覚えて？　……お母さんになる前の、わたしを。" },
    { id: "a136", r18: true, name: "", text: "頷くと、さくらは俺の首に腕を回し、そっと唇を重ねてきた。桜の香りと、少しの緊張。" },
    { id: "a137", face: "pleasure", r18: true, name: "さくら", text: "んっ……悠太……優しい……ねえ、もっと……わたしを、抱きしめて？" },
    { id: "a138", r18: true, name: "", text: "ベッドに横たわり、さくらは自ら俺の服を脱がせていく。大きな乳房が、月明かりに白く浮かぶ。" },
    { id: "a139", r18: true, name: "さくら", text: "ねえ、見て……わたしの胸、もう張ってるの。……赤ちゃんのためだね、きっと。……ねえ悠太、触って……確かめて？" },
    { id: "a140", r18: true, name: "", text: "乳房を包むように揉むと、さくらは甘い声を漏らした。先端はすっかり硬くなり、彼女の吐息が熱い。" },
    { id: "a141", face: "pleasure", r18: true, name: "さくら", text: "あぁっ……悠太……気持ちいい……ねえ、もう……入れて……わたしの中、もうとろとろなの……" },
    { id: "a142", r18: true, name: "", text: "濡れそぼった秘部に、ゆっくりと腰を沈める。さくらは俺の背中にしがみつき、歓喜の声を上げた。" },
    { id: "a143", face: "ecstasy", r18: true, name: "さくら", text: "あんっ……奥まで……悠太のが、わたしの一番奥まで……すごい、気持ちいい……！　わたし、もう……イッちゃう……" },
    { id: "a144", r18: true, name: "", text: "夢中で腰を振るさくら。膣壁がうねるように絡みつき、結合部からは愛液が溢れて太ももを伝う。俺は乳房を揉みながら、下から突き上げた。" },
    { id: "a145", r18: true, name: "さくら", text: "中に出して、悠太……！　今夜も、わたしのお腹にちょうだい……！　わたしは、悠太の子が欲しいの……！" },
    { id: "a146", r18: true, name: "", text: "最奥深くで射精。さくらは子宮で受け止めるように腰を寄せ、注がれる熱に幸福そうに震えた。" },
    { id: "a147", r18: true, name: "さくら", text: "あぁ……いっぱい……ねえ悠太、わたしね、もう決めたの。……この子に、桜の名前をつけるの。……悠太と、わたしの桜。" },
    { id: "a148", r18: true, name: "", text: "抱き合ったまま眠りに落ちる。さくらの寝息と、窓の外の桜の香り。――新しい命と共に、二人の物語は続いていく。", jump: "a169" },
    { id: "a149", bg: "park", name: "", text: "――写真展へ向かう途中、さくらがふと足を止めた。並木道の脇に、小さな古い写真館がある。看板の文字は、少しだけ色褪せていた。" },
    { id: "a150", name: "さくら", text: "ねえ悠太、ここ、覚えてる？　高校のとき、写真部の帰りにいつも前を通った写真館。……まだ、やってるんだね。" },
    { id: "a151", name: "悠太", text: "ああ、覚えてる。……店主のおじさん、フィルム現像がめちゃくちゃ上手くて、部室でよく話題になってたよな。" },
    { id: "a152", name: "", text: "さくらはガラス越しに店内を覗き込んだ。壁には、モノクロの風景写真が何枚も飾られている。どれも、どこか懐かしい匂いがした。" },
    { id: "a153", name: "さくら", text: "ねえ、入ってみない？　……ちょっとだけ。わたしの写真展、今日なんだよ。……なんだか、ご挨拶したい気分なの。" },
    { id: "a154", name: "", text: "店のドアを開けると、現像液の匂いと、古い木の香りがした。奥から、白髪の店主がゆっくりと顔を出した。" },
    { id: "a155", name: "店主", text: "おや、さくらちゃんじゃないか。……大きくなったねえ。高校のとき、よくフィルムを持って来てた子だろ。" },
    { id: "a156", name: "", text: "さくらは少し照れながら、今日の写真展の話をした。店主は目を細め、奥の棚から一枚の写真を取り出してきた。" },
    { id: "a157", name: "店主", text: "これ、覚えてるかい。……あんたが高校生のとき、初めて自分で現像した桜の写真。……わし、ずっと取っておいたんだよ。" },
    { id: "a158", name: "", text: "写真の中の桜は、5年前の春のものだった。さくらは両手でそれを受け取り、しばらく黙って見つめていた。目元が、少しだけ潤んでいる。" },
    { id: "a159", face: "smile", name: "さくら", text: "……ありがとうございます。……わたし、今日、写真展をやるんです。……この写真みたいに、誰かの心に残る写真を撮りたくて。" },
    { id: "a160", name: "", text: "店主は大きく頷き、さくらの頭をぽんと叩いた。「頑張りな。高校の頃、初めて自分で現像した桜の一枚から、ずっと見てきたけどな。あんたの写真は、人の心に残る写真になったよ」" },
    { id: "a161", name: "", text: "店を出ると、さくらは写真を胸に抱き、桜の並木道を見上げた。花びらが、ひらひらと舞い落ちてくる。" },
    { id: "a162", name: "さくら", text: "ねえ悠太。……わたし、決めた。……今日の写真展が終わったら、次はもっと大きな展示をやるの。……悠太と一緒に、ね。" },
    { id: "a163", name: "悠太", text: "ああ。……じゃあ、決まりだな。次はもっと大きな会場で、二人でやろう。搬入も受付も、俺が引き受けるから。" },
    { id: "a164", name: "", text: "さくらは嬉しそうに笑い、俺の腕にそっと寄り添った。桜色のカーディガンが、春の風に揺れている。" },
    { id: "a165", face: "smile", name: "さくら", text: "ふふ、悠太といると、なんだか怖くない。今日の展示、きっとうまくいく。ねえ、行こう？　あの頃のわたしに負けない、今のわたしを見てほしいの。" },
    { id: "a166", name: "", text: "並木道を、もう一度歩き出す。二人の影が寄り添うように伸びていく。さくらは時折、俺の顔を盗み見ては微笑んだ。" },
    { id: "a167", name: "さくら", text: "ねえ、展示が終わったらさ。……今日の写真、店主さんに見せに行こう？　……わたしの成長、報告したいの。" },
    { id: "a168", name: "悠太", text: "ああ、いいね。……さくらの写真展、今日は特別な日になるよ。……ほら、ギャラリーはもうすぐそこだ。", jump: "a86" },
    { id: "a169", bg: "room", r18: true, name: "", text: "――胎動を初めて感じた夜。さくらは俺の手をそっとお腹に当て、目を閉じた。窓の外では、桜の花びらが静かに舞っている。" },
    { id: "a170", r18: true, name: "さくら", text: "ねえ悠太……今、動いたの。……ほら、もう一回……わたしの、わたしたちの子が、生きてるの。" },
    { id: "a171", r18: true, name: "悠太", text: "ああ……ほんとだ。……小さな命が、さくらの中で……俺の手のひらに、確かに伝わってくる。" },
    { id: "a172", r18: true, name: "", text: "さくらは俺の胸に頬を寄せ、幸せそうに目を閉じた。お腹の内側で、小さな命がもう一度跳ねた。" },
    { id: "a173", r18: true, name: "さくら", text: "ねえ、今日は……特別な夜にしよう？　……この子に、パパとママの声を聞かせてあげたいの。……ねえ、抱いて？" },
    { id: "a174", r18: true, name: "", text: "唇を重ねたまま、さくらのお腹が俺の体にそっと触れた。その内側で、小さく何かが跳ねる。――また、胎動だ。" },
    { id: "a175", face: "pleasure", r18: true, name: "さくら", text: "んっ……悠太……今、また動いた……ねえ、この子も聞こえてるのかな。パパとママの、声……。" },
    { id: "a176", r18: true, name: "", text: "俺はさくらを抱き寄せ、背中をゆっくり撫でた。今夜は、この子と三人でいる静かな夜だ。" },
    { id: "a177", r18: true, name: "さくら", text: "ねえ……わたしの体、変わっていくね。お腹も、胸も、この子を育てる体に……。悠太、こんなわたしでも、いい？" },
    { id: "a178", r18: true, name: "", text: "いいに決まっている。俺は決めていた――来月から勤務は地元に固定してもらい、育休も取る。この子の最初の一歩は、二人で見る。" },
    { id: "a179", face: "pleasure", r18: true, name: "さくら", text: "あっ……今、強く蹴った……ふふ、この子、パパの声が分かるのかな。……ねえ悠太、今夜は静かに抱いて？" },
    { id: "a180", r18: true, name: "", text: "さくらを横たえ、お腹を庇うようにそっと体を重ねる。ゆっくりと、確かめるように一つになった。" },
    { id: "a181", face: "ecstasy", r18: true, name: "さくら", text: "あん……悠太……温かい……ねえ、感じる？　わたしのお腹の中で、この子が……三人で、一緒にいるの……" },
    { id: "a182", r18: true, name: "", text: "激しくはない。ただ深く、静かに。さくらの腕の中で、俺は初めて「父親」という言葉の重さと温かさを、体で知った。" },
    { id: "a183", r18: true, name: "さくら", text: "ねえ悠太……今夜も、いっぱいちょうだい……この子と一緒に、パパの温かさに包まれて、眠りたいの……" },
    { id: "a184", r18: true, name: "", text: "静かな高まりの果てに、深く注ぐ。さくらは、お腹に当てた俺の手を、上からそっと押さえた。" },
    { id: "a185", r18: true, name: "さくら", text: "あぁ……いっぱい……ねえ悠太、この子、きっと元気に生まれてくるね。……だって、こんなに愛されてるんだもの。" },
    { id: "a186", r18: true, name: "", text: "抱き合ったまま眠りに落ちる。さくらのお腹に手を当てたまま、俺は小さな命の鼓動を感じていた。――桜の季節に、新しい命が芽吹く。", jump: "a207" },
    { id: "a187", bg: "park", name: "", text: "――ギャラリーへ向かう途中。さくらがふと足を止め、並木道の脇にある小さな喫茶店を指さした。" },
    { id: "a188", name: "さくら", text: "ねえ悠太、ここ。……わたしのお気に入りの店なの。写真展の前に、ちょっとだけ寄っていかない？" },
    { id: "a189", name: "悠太", text: "いいよ。……さくらがそんな顔で誘うなら、断る理由がないな。" },
    { id: "a190", name: "", text: "店内は木の温もりに満ちていた。窓際の席に座ると、さくらはメニューを開いて嬉しそうに笑った。" },
    { id: "a191", name: "さくら", text: "ここのモーニング、すごく美味しいの。……高校のとき、よく一人で来てたんだ。悠太のことを考えながらね。" },
    { id: "a192", name: "悠太", text: "へえ、そんな前から？　……さくら、意外とずっと俺のこと見てたんだな。" },
    { id: "a193", name: "さくら", text: "見てたよ。写真部の部室の窓から、グラウンドで走る悠太を。……シャッター、こっそり何回も切ってた。" },
    { id: "a194", name: "", text: "運ばれてきたトーストとコーヒー。さくらはコーヒーにミルクをたっぷり入れて、そっと一口。" },
    { id: "a195", name: "さくら", text: "ねえ悠太、今日の写真展、わたし、すごく大事にしてるの。卒業してから撮りためた写真、全部出すんだから。……見終わったら、感想、ちゃんと聞かせてね。" },
    { id: "a196", name: "悠太", text: "もちろん。……感想なら、もう山ほど用意してあるよ。でも、それは見終わってからのお楽しみだ。" },
    { id: "a197", face: "smile", name: "さくら", text: "……うん。ありがとう。悠太がそう言ってくれると、ほんとに頑張れる。……あ、ほら、口の端にジャムついてる。" },
    { id: "a198", name: "", text: "さくらは身を乗り出して、俺の口元を指で拭った。指先が触れた瞬間、二人して少しだけ照れた。" },
    { id: "a199", face: "smile", name: "さくら", text: "ふふ、ごちそうさま。……さ、行こう。わたしの写真、悠太に見てもらうんだから。" },
    { id: "a200", name: "", text: "勘定を済ませ、店を出る。桜の花びらが舞う並木道を、さくらはスキップするように歩き出した。" },
    { id: "a201", face: "wink", name: "さくら", text: "ねえ悠太、今日はね、展示の最後に秘密の写真があるの。……見たら、きっと分かるよ。わたしの一番好きなもの。" },
    { id: "a202", name: "悠太", text: "秘密の写真か。……さくららしいな。楽しみにしてるよ。" },
    { id: "a203", name: "さくら", text: "うん！　……あ、ギャラリー、もう見えてきた。ほら、あそこ。" },
    { id: "a204", name: "", text: "小さなギャラリーの入り口。さくらは一度深呼吸して、俺の手をぎゅっと握った。" },
    { id: "a205", name: "さくら", text: "行こう、悠太。……秘密の写真、早く見せたいな。" },
    { id: "a206", name: "", text: "手を引かれ、ギャラリーの扉が開く。桜色の光が、二人をそっと迎えた。", jump: "a12" },
    { id: "a207", bg: "room", r18: true, name: "", text: "――ベビーベッドを組み立てた夜。さくらは小さなベッドの柵を撫で、俺の部屋で嬉しそうに笑った。窓の外では、桜の花びらが静かに舞っている。" },
    { id: "a208", face: "smile", r18: true, name: "さくら", text: "ねえ悠太……できたよ。……この子が生まれたら、ここで眠るの。……ほら、見て……桜のモビールも、つけたの。" },
    { id: "a209", r18: true, name: "悠太", text: "ああ……ほんとに、立派なベッドだな。……さくら、よく頑張ったね。……この子、きっと気に入るよ。" },
    { id: "a210", r18: true, name: "", text: "さくらはベッドにそっと手を置き、俺の胸に頬を寄せた。その指先が、ほんの少しだけ震えていた。" },
    { id: "a211", r18: true, name: "さくら", text: "ねえ、今日は……特別な夜にしよう？　……この子の部屋が、できた記念だから。……ねえ、抱いて？" },
    { id: "a212", r18: true, name: "", text: "頷きかけて、気づく。さくらの笑顔が、いつもと少しだけ違うことに。ベッドの柵を握る手が、力を込めすぎている。" },
    { id: "a213", face: "sad", r18: true, name: "さくら", text: "ねえ悠太……わたし、さっきからずっと考えてたの。……この子を、ちゃんと守れるのかな、わたしに。" },
    { id: "a214", r18: true, name: "", text: "いつも明るいさくらの、初めて見る弱さだった。俺は揺れる桜のモビールを見上げ、彼女の次の言葉を待った。" },
    { id: "a215", r18: true, name: "さくら", text: "写真も、続けられるのかなって。生まれたら、きっと余裕なんてなくて……わたしの夢、置いていくのかな。" },
    { id: "a216", r18: true, name: "", text: "「一人で背負うな」。俺は遮るように言った。守るのは俺も一緒だ。写真は続ければいい。お前の夢は、俺の夢でもある。" },
    { id: "a217", face: "love", r18: true, name: "さくら", text: "……っ、悠太はそういうことをさらっと言うよね。ありがとう。……今夜は楽しみな気持ちで眠りたい。……ねえ、抱いて？" },
    { id: "a218", r18: true, name: "", text: "頷いて、さくらをそっと抱き寄せる。小さな寝床に見守られるように、二人は静かに重なった。" },
    { id: "a219", face: "ecstasy", r18: true, name: "さくら", text: "あん……悠太……温かい……ねえ、もう一回言って……？　わたしは、一人じゃないんだよね……？" },
    { id: "a220", r18: true, name: "", text: "あやすように、急がず、深く。さくらの震えが少しずつ安らぎに変わっていくのを、腕の中で感じた。" },
    { id: "a221", r18: true, name: "さくら", text: "悠太……中に……今夜は安心でいっぱいにして……わたし、もう怖くない。パパとママで、頑張れるから……" },
    { id: "a222", r18: true, name: "", text: "最奥で静かに注ぐ。さくらは俺の背を抱きしめ、小さく「ありがとう」と繰り返した。" },
    { id: "a223", face: "sleepy", r18: true, name: "さくら", text: "あぁ……いっぱい……ねえ悠太、この子が生まれたら、ベビーベッドで眠るの。……わたしと、悠太と、この子で。" },
    { id: "a224", r18: true, name: "", text: "抱き合ったまま眠りに落ちる。さくらのお腹に手を当てたまま、俺は小さな命の鼓動を感じていた。――桜色のベビーベッドに、やがて小さな寝息が響く。", jump: "a245" },
    { id: "a225", bg: "park", name: "", text: "――写真展の当日。ギャラリーの入り口でさくらが手を振っていた。白いワンピースに、桜色のカーディガン。待ち合わせに、胸が高鳴る。" },
    { id: "a226", name: "さくら", text: "お待たせ、悠太。ねえ、展示を見る前に、ちょっと手伝ってくれない？　額縁のひとつ、ガラスにヒビが入っちゃったの。" },
    { id: "a227", name: "悠太", text: "えっ、ヒビ？　大丈夫か？　ああ、ほんとだ。隅のほうに、細い線が入ってるな。" },
    { id: "a228", name: "", text: "さくらは少しだけ俯いた。せっかくの写真展の朝に、思わぬハプニング。指先が、不安そうに額縁をなぞる。" },
    { id: "a229", face: "sad", name: "さくら", text: "ごめんね。昨日の搬入のとき、運ぶ途中でぶつけちゃったみたいで。わたしの、大事な写真なのに。" },
    { id: "a230", name: "悠太", text: "謝ることないよ。ほら、ヒビは隅だけで、写真そのものは無事だろ？　展示の仕方を工夫すれば、目立たなくなるよ。" },
    { id: "a231", name: "", text: "さくらは顔を上げ、俺の言葉に小さく頷いた。桜色のカーディガンが、朝の光に揺れる。" },
    { id: "a232", name: "さくら", text: "うん。ねえ悠太、じゃあさ、額縁を少しだけ角度を変えて飾ろう？　光の当たり方で、ヒビが見えにくくなるかも。" },
    { id: "a233", name: "悠太", text: "いいね、それ。……じゃあ俺が額縁を持ち上げるから、さくらは後ろから見て、角度を教えてくれ。" },
    { id: "a234", name: "", text: "二人で額縁をそっと動かす。角度を変えるたび、ガラスのヒビの見え方が変わっていく。さくらの声が、少しずつ明るくなる。" },
    { id: "a235", face: "smile", name: "さくら", text: "もう少し右。うん、そこ！　ねえ、見て。ヒビ、ほとんど分からなくなったよ。悠太、ありがとう。" },
    { id: "a236", name: "悠太", text: "ほんとだ。角度を変えたら、ヒビは全然目立たないな。よし、このまま開場できるよ。" },
    { id: "a237", name: "", text: "さくらは嬉しそうに笑い、展示の写真を一枚ずつ見直した。桜の花びらが、ギャラリーの窓の外で舞っている。" },
    { id: "a238", face: "sad", name: "さくら", text: "ねえ悠太。実はね、昨日の夜、ずっと不安だったの。誰も来なかったらどうしようって。でも、悠太がいてくれてよかった。" },
    { id: "a239", name: "悠太", text: "俺がいるよ。今日はさくらの晴れ舞台だ。さくらの写真を、みんなに見てもらおう。" },
    { id: "a240", name: "", text: "さくらは深呼吸をして、俺の手をぎゅっと握った。手のひらは少し汗ばんで、温かい。" },
    { id: "a241", name: "さくら", text: "うん。ねえ、展示が終わったらさ、二人で桜並木を歩こう？　今日の桜、きっと綺麗だよ。" },
    { id: "a242", name: "悠太", text: "約束だ。さ、開場の時間だ。行こう、さくら。" },
    { id: "a243", name: "", text: "さくらは頷き、ギャラリーのドアを開けた。朝の光が差し込み、展示された写真たちが、静かに輝いていた。" },
    { id: "a244", name: "", text: "――写真展の朝は、こうして始まった。額縁のヒビは、今日の二人の小さな秘密になった。", jump: "a43" },
    { id: "a245", bg: "room", r18: true, name: "", text: "――出産予定日まで、あと十日。窓の外はすっかり冬の色で、再会した春の駅前とは別の季節になっていた。さくらは入院バッグにタオルや着替えを詰め、最後に母子手帳をそっと重ねた。" },
    { id: "a246", r18: true, name: "さくら", text: "ねえ悠太……見て。……入院バッグ、できたよ。……この子の初めての服も、入れたの。……ほら、桜色の肌着。" },
    { id: "a247", r18: true, name: "悠太", text: "ああ……ほんとに、小さいな。……さくら、よく準備したね。……この子、生まれるのが楽しみだよ。" },
    { id: "a248", r18: true, name: "", text: "さくらはバッグにそっと手を置き、俺の胸に頬を寄せた。窓の外では、白い雪が降り始めていた。" },
    { id: "a249", r18: true, name: "さくら", text: "ねえ、今日は……特別な夜にしよう？　……この子の入院バッグが、できた記念だから。……ねえ、抱いて？" },
    { id: "a250", r18: true, name: "", text: "頷くと、さくらは俺に体を預けてきた。冬の冷気に冷えた指先が、俺の胸で少しずつ温かくなっていく。" },
    { id: "a251", face: "pleasure", r18: true, name: "さくら", text: "んっ……悠太、温かい……ねえ、今日ね、持ってきたの。この子の、名前の候補。……ねえ、一緒に決めよ？" },
    { id: "a252", r18: true, name: "", text: "さくらが枕元のノートを開く。几帳面な字で候補がいくつも並び、消しては書き、丸をつけては迷った跡があった。" },
    { id: "a253", r18: true, name: "さくら", text: "「桜乃」「小桜」「咲良」……いっぱい考えたの。でもね、迷ってるのもあるの。……ねえ、悠太はどれがいい？" },
    { id: "a254", r18: true, name: "", text: "俺は一つの名前を指さした。生まれるのは春じゃない。それでも、この子は俺たちにとっての「桜」そのものだ。" },
    { id: "a255", face: "pleasure", r18: true, name: "さくら", text: "……「桜乃（さくの）」。……ふふ、うん。わたしも、それが一番しっくりくるの。……決まったね、わたしたちの子の名前。" },
    { id: "a256", r18: true, name: "", text: "さくらはお腹に両手を当て、決まったばかりの名前を何度も呼んだ。その声の温かさに、俺は胸がいっぱいになった。" },
    { id: "a257", face: "ecstasy", r18: true, name: "さくら", text: "あん……悠太……ねえ、今の、桜乃も聞いてたかな。パパとママに名前を呼んでもらった夜……幸せだね……" },
    { id: "a258", r18: true, name: "", text: "名前をもらった子を宿す体を、壊さないよう深く抱く。さくらの喜びの声が、冬の静かな部屋に溶けていった。" },
    { id: "a259", r18: true, name: "さくら", text: "中に出して、悠太……桜乃の隣に、パパの温かさも残して……あと十日で会えるね。わたしたちの、桜乃に……！" },
    { id: "a260", r18: true, name: "", text: "最奥で静かに注ぐ。さくらはお腹を撫で、決まった名前を小さく囁いて、幸せそうに目を細めた。" },
    { id: "a261", r18: true, name: "さくら", text: "あぁ……いっぱい……ねえ悠太、この子が生まれたら、桜の木の下で写真を撮るの。……わたしと、悠太と、この子で。" },
    { id: "a262", r18: true, name: "", text: "抱き合ったまま眠りに落ちる。さくらのお腹に手を当てたまま、俺は小さな命の鼓動を感じていた。――桜色の入院バッグが、月明かりにそっと白く浮かんでいた。", jump: "a85" },
    { id: "a263", face: "smile", name: "さくら", text: "ねえ、覚えてる？　写真展に誘ったとき、悠太、即答してくれたよね。……あの即答がなかったら、わたし、今日だって言えなかったと思う。……ありがとう。", jump: "a21" }
  ]
},
{
  id: "misaki",
  title: "真夜中のコンビニ",
  heroine: "美咲（22歳）",
  desc: "深夜バイトの先輩・美咲と過ごす静かな夜勤。雨の夜、閉店後の店内で二人の距離が縮まっていく。",
  cover: "assets/misaki_cover.webp",
  r18: true,
  images: { store: "assets/misaki_store.svg", street: "assets/misaki_street.svg", room: "assets/misaki_room.svg", char: "assets/misaki_char.webp" },
  scenes: [
    { id: "b01", bg: "store", name: "", text: "深夜1時のコンビニ。客足の途絶えた店内に、蛍光灯の低い唸りだけが響く。\n俺の夜勤バイトも、今日で3か月目になった。" },
    { id: "b02", face: "smile", char: true, name: "美咲", text: "悠太くん、おつかれさま。はい、あったかいコーヒー。……ねえ、今日の夜勤、わたしと二人だけだって。知ってた？" },
    { id: "b03", name: "悠太", text: "美咲さんのおかげで、仕事だいぶ覚えました。……二人だけって、ちょっと緊張しますね。" },
    { id: "b04", face: "smile", name: "美咲", text: "あら、緊張？　ふふ、可愛い。……あ、雨、強くなってきたね。天気予報じゃ、朝まで止まないって。" },
    { id: "b05", name: "", text: "窓の外は本格的な雨。閉店作業を終える頃には、傘があってもずぶ濡れになるような土砂降りだった。", jump: "b38" },
    { id: "b06", face: "shy", char: true, name: "美咲", text: "……ねえ悠太くん。わたしの家、このすぐ近くなの。雨が止むまで、うちで休んでいかない？　夜食も作るし。" },
    { id: "b07", choice: [
      { text: "「お邪魔します」と素直に甘える", jump: "b08", set: { love: 1 } },
      { text: "「店で朝まで待ちます」と遠慮する", jump: "b09", set: { love: 0 } }
    ] },
    { id: "b08", face: "shy", name: "美咲", text: "うん、決まり。じゃあシャッター閉めたら一緒に出よう。……ふふ、なんだかドキドキするね、わたしも。", jump: "b10" },
    { id: "b09", name: "美咲", text: "もう、遠慮しなくていいのに。……でも、悠太くんがそう言うなら。ホットコーヒー、もう一杯入れるね。", jump: "b14" },
    { id: "b10", bg: "room", name: "", text: "美咲さんの家は、店から歩いて3分のワンルームだった。雨に濡れた制服を脱ぎ、借りた部屋着に着替える。" },
    { id: "b11", face: "smile", char: true, name: "美咲", text: "はい、オムライス。バイト先じゃ分からないでしょ、わたし料理得意なんだよ。……どう？　美味しい？" },
    { id: "b12", name: "悠太", text: "……めちゃくちゃ美味いです。美咲さん、仕事もできて料理も上手くて、完璧ですね。" },
    { id: "b13", face: "sad", name: "美咲", text: "完璧なんかじゃないよ。……一人暮らしの夜は、結構寂しいんだから。悠太くんと夜勤の日だけ、ちょっと楽しみだったの。" },
    { id: "b14", branch: { flag: "love", min: 1, then: "b15", else: "b19" } },
    { id: "b15", name: "", text: "食器を片付けた後も、話は尽きなかった。雨音だけが遠くで響く部屋。気づけば、二人の距離は手の届くところまで縮んでいた。" },
    { id: "b16", face: "serious", name: "美咲", text: "ねえ悠太くん。……わたしのこと、どう思ってる？　先輩として、じゃなくて。一人の女の子として。" },
    { id: "b17", choice: [
      { text: "「好きです。ずっと前から」と答える", jump: "b18", set: { love: 2 } },
      { text: "「尊敬してます」と無難に返す", jump: "b19", set: { love: 0 } }
    ] },
    { id: "b18", face: "smile", name: "美咲", text: "……！　本当に？　……やった。わたしもだよ、悠太くん。初めてシフトが被った日から、ずっと気になってた。", jump: "b20" },
    { id: "b19", bgm: "calm", face: "smile", bg: "street", char: true, name: "", text: "――雨は、いつの間にか上がっていた。朝の光が、店のガラスを白く光らせている。一睡もしないまま迎えた朝は、少しだけ眩しかった。\n「雨、上がったみたい。……今日はありがとう、悠太くん。また夜勤でね」\n【NORMAL END ― 雨上がりの帰り道】", end: true },
    { id: "b20", face: "love", r18: true, name: "美咲", text: "じゃあ……今夜は帰さない。わたしの気持ち、体ごと受け止めて？　悠太くん。" },
    { id: "b21", r18: true, name: "", text: "美咲さんは自分から腕を回し、唇を重ねてきた。コーヒーと雨の匂いのするキス。舌を絡め合ううちに、いつもの頼れる先輩の顔は消え、甘えたような女の表情だけが残った。" },
    { id: "b22", face: "pleasure", r18: true, name: "美咲", text: "んんっ……悠太くん、思ったより大胆……。いいよ、もっと。わたし、全部悠太くんに見せてあげる。……ほら、脱がせて？" },
    { id: "b23", r18: true, name: "", text: "部屋着のボタンを外すと、下着に包まれた豊かな乳房が露わになる。ブラを外し、掌で揉みしだくと、美咲さんはくすぐったそうに身を捩りながら甘い吐息を零した。" },
    { id: "b24", r18: true, name: "美咲", text: "あぁん……っ、悠太くんの手、熱い……。わたしもう、ずっとこうされたかったの。先輩のくせに、年下に夢中だなんて……ね？" },
    { id: "b25x", r18: true, name: "", text: "乳首を摘まみ、舌で転がすたび、美咲さんの声は高くなる。下着の中に手を滑らせると、秘部はとろとろに濡れていた。指で陰唇を割り開き、クリトリスを撫でると、彼女の腰が跳ねた。" },
    { id: "b26x", face: "pleasure", r18: true, name: "美咲", text: "あっ、あぁっ……！　そこ、だめ……感じすぎちゃう……。悠太くん、意地悪……でも、止めないで。もっと、わたしをめちゃくちゃにして……" },
    { id: "b27x", r18: true, name: "", text: "指を膣内へ沈めると、熱い内壁が吸い付くように絡んでくる。抽送に合わせて美咲さんは乱れ、やがて俺のものを求めるように手を伸ばしてきた。" },
    { id: "b28x", r18: true, name: "美咲", text: "わたしも触る。……すごい、こんなに硬くて熱い。悠太くん、早く……早くわたしの中に入れて。もう我慢できないの……" },
    { id: "b29x", r18: true, name: "", text: "ベッドに押し倒し、脚を広げさせて一気に貫く。美咲さんは大きく目を見開き、背を反らせて嬌声を上げた。熟れた膣は俺の形に合わせて締め付け、抽送のたびに淫らな水音を立てる。" },
    { id: "b30x", face: "pleasure", r18: true, name: "美咲", text: "あぁん、あぁっ……！　悠太くん、深い、奥まで届いてる……！　気持ちいい、すごく気持ちいい……もっと激しくして、先輩を堕として……" },
    { id: "b31x", r18: true, name: "", text: "豊満な乳房を掴み、乳首を弄びながら腰を打ち付ける。美咲さんは俺の背に爪を立て、何度も絶頂を迎えながら乱れ続けた。体位を変え、後ろから突き上げると、声が一層高くなる。" },
    { id: "b32x", face: "ecstasy", r18: true, name: "美咲", text: "イグ、またイッちゃう……！　悠太くん、好き、好きぃ……！　あぁっ、もう、わたし、悠太くんの彼女で幸せ……！" },
    { id: "b33x", r18: true, name: "", text: "限界を迎えた俺が中を告げると、美咲さんは脚を絡めて逃がさないとばかりに抱きついてきた。" },
    { id: "b34x", r18: true, name: "美咲", text: "中がいいの……中にちょうだい、悠太くん……！　わたしのお腹、悠太くんの子でいっぱいにして……責任取って、彼女なんだから……！" },
    { id: "b35x", r18: true, name: "", text: "最奥に押し込み、熱い精液を注ぎ込む。美咲さんは歓喜に震え、注がれるたび小さく喘ぎながら、全てを受け止めるように腰を密着させた。" },
    { id: "b36x", face: "smile", r18: true, name: "美咲", text: "あぁ……いっぱい出たね……わたしの中、悠太くんのでいっぱい……。ふふ、幸せ。……ねえ、今夜はまだ長いよ？　もう一回戦、しよっか。", jump: "b49" },
    { id: "b37x", r18: true, name: "", text: "二人は夜明け前まで何度も求め合った。雨上がりの空が白み始める頃、美咲さんは腕の中で穏やかな寝息を立てていた。" },
    { id: "b26", face: "smile", bg: "room", name: "美咲", text: "おはよう、悠太くん。……ふふ、これからはプライベートでも『先輩』じゃなくていいよ。わたしは悠太くんの、彼女だから。", jump: "b181" },
    { id: "b38", bg: "store", name: "", text: "閉店作業の合間、バックヤードで二人だけの休憩。美咲さんは缶コーヒーを差し出し、隣に腰を下ろした。制服の袖が、わずかに触れ合う距離。", jump: "b219" },
    { id: "b39", face: "smile", char: true, name: "美咲", text: "悠太くんって、彼女いるの？　……いない？　ふふ、じゃあ聞くけど、好きなタイプは？　年上は、どう？" },
    { id: "b40", name: "悠太", text: "年上、いいと思います。美咲さんみたいに、頼れて、でもたまに甘い人が……って、すみません、言いすぎました。" },
    { id: "b41", face: "smile", name: "美咲", text: "……あら。ふふ、悠太くん、顔真っ赤だよ？　……ねえ、連絡先、交換しよ。バイトの連絡だけじゃなくて、普通に話したいな、わたし。" },
    { id: "b42", name: "", text: "スマホを交換し、連絡先を登録する。美咲さんのアイコンは、私服姿の笑顔だった。心臓の音が、自分でも分かるくらい大きい。", jump: "b143" },
    { id: "b43", face: "smile", name: "美咲", text: "今度、バイトじゃない日にどこか行こうよ。……約束ね。さ、雨の様子、見てくる。", jump: "b06" },
    { id: "b49", r18: true, name: "", text: "二回戦の誘いに頷くと、美咲さんは嬉しそうに微笑み、シャワーで汗を流した俺をキッチンへ連れていった。濡れた髪、バスローブ一枚の姿が目に毒だ。" },
    { id: "b50", face: "wink", r18: true, name: "美咲", text: "今度はわたしがリードする番。悠太くんは座ってて。……先輩の本気、見せてあげる。" },
    { id: "b51", r18: true, name: "", text: "美咲さんは跪き、俺のものを口に含んだ。舌を絡め、深く咥え込み、頬を凹ませて吸い上げる。年上の余裕のある奉仕に、腰が震える。" },
    { id: "b52", face: "pleasure", r18: true, name: "美咲", text: "んんっ……どう？　先輩、上手でしょ。……悠太くんの顔、とろけてる。可愛い。でも、まだ出しちゃだめだよ。次は、中でね。" },
    { id: "b53", r18: true, name: "", text: "バスローブを脱ぎ捨て、美咲さんはキッチンのカウンターに手をついた。豊かな尻を突き出し、濡れた秘部を見せつけるように腰を揺らす。" },
    { id: "b54", r18: true, name: "美咲", text: "後ろから、来て……悠太くんの好きなように、激しく突いて。わたし、もうとろとろなの……早く、壊れるくらいにして……" },
    { id: "b55", r18: true, name: "", text: "腰を掴み、一気に貫く。美咲さんはカウンターに身を伏せ、大きな乳房を揺らしながら喘いだ。後背位の深さに、膣壁が締め付けを強めていく。" },
    { id: "b56", r18: true, name: "美咲", text: "あぁん、あぁっ……！　深い、奥に当たってる……！　悠太くん、すごい、わたし、立ってられない……もっと、もっとぉ……！" },
    { id: "b57", r18: true, name: "", text: "髪を軽く掴み、乳房を後ろから揉みながら突き上げると、美咲さんは何度も絶頂を繰り返した。ベッドへ移動し、今度は彼女が上に跨る。" },
    { id: "b58", face: "pleasure", r18: true, name: "美咲", text: "今度はわたしが動く番。……見てて、悠太くん。彼女のえっちな姿、全部あなたのものだよ……あんっ、あぁっ……！" },
    { id: "b59", r18: true, name: "", text: "騎乗位で腰を振る美咲さんは、蕩けた顔で自ら深く沈み込ませる。限界が近づくと、彼女は膣を強く締め、逃がさないとばかりに腰を落とし切った。" },
    { id: "b60", r18: true, name: "美咲", text: "中、また中でちょうだい……！　二回目も、わたしのお腹いっぱいにして……悠太くんの彼女を、孕ませて……！" },
    { id: "b61", r18: true, name: "", text: "最奥で射精。美咲さんは歓喜に身を震わせ、注がれる感触を味わうようにゆっくり腰を揺すった。白濁が腿を伝い、カウンターの下に雫となって落ちる。" },
    { id: "b62", r18: true, name: "美咲", text: "あぁ……二回も中に出してくれた……。わたし、幸せすぎてどうにかなりそう。……悠太くん、これからも夜勤の日は、わたしの家に直行だよ？", jump: "b37x" },
    { id: "b63", bg: "store", name: "", text: "――数週間後。交際が始まってから、夜勤のシフトは二人で合わせるのが暗黙の了解になった。今夜も静かな店内。美咲さんが、店長に掛け合ってくれたらしい。", jump: "b105" },
    { id: "b64", face: "sad", char: true, name: "美咲", text: "ねえ悠太くん。来月から、あなた昼のシフトに移るんでしょ？　……わたしも一緒に移ることにしたの。だって、離れるの寂しいもん。" },
    { id: "b65", name: "悠太", text: "美咲さん……そこまでしてくれるんですか。嬉しいけど、夜勤の方が時給は……" },
    { id: "b66", face: "smile", name: "美咲", text: "お金より大事なものがあるの。……ふふ、それにね、最近わたし、体調にちょっとした変化があって。もしかしたら、なんだけど。" },
    { id: "b67", name: "", text: "意味深に微笑む美咲さん。その言葉の意味を理解する前に、閉店の時間になった。今夜も、雨は降っていないのに彼女の家へ向かう。" },
    { id: "b68", face: "wink", bg: "room", name: "美咲", text: "今日はね、先に言っておく。……わたし、検査薬、試してみたの。結果は内緒。だから今夜は、答え合わせの前に、思い切り愛し合おう？" },
    { id: "b69", face: "love", r18: true, name: "美咲", text: "悠太くん、今夜は特別。わたしの全部で、あなたを愛してあげる。……ほら、キスして。先輩彼女の特権、たっぷり味わって。" },
    { id: "b70", r18: true, name: "", text: "深いキスから始まり、美咲さんは自ら服を脱いでいく。豊かな乳房を押し付けるように抱きつき、耳元で甘く囁いた。" },
    { id: "b71", face: "pleasure", r18: true, name: "美咲", text: "わたしの胸、悠太くん専用だよ。揉んで、吸って、好きにしていい。……あんっ、そう、そこ……年下彼氏に責められるの、背徳感あって好き……" },
    { id: "b72", r18: true, name: "", text: "乳首を弄び、秘部を指で解す。美咲さんは既にとろとろに濡れ、指を三本飲み込んでも苦にしない。やがて俺のものを導き、自ら腰を落としてきた。" },
    { id: "b73", r18: true, name: "美咲", text: "あぁん……入ってきたぁ……悠太くんの、熱い……。今日はね、特別な日だから、中でいっぱい出してほしいの。……理由は、後で教えてあげる。" },
    { id: "b74", r18: true, name: "", text: "騎乗位で激しく腰を振る美咲さん。大きな乳房が目の前で跳ね、膣壁は強く締め付けてくる。抱き合う体位に変え、深く密着しながら求め合った。" },
    { id: "b75", face: "pleasure", r18: true, name: "美咲", text: "あんっ、あんっ、あぁっ……！　悠太くん、好き、好きぃ……！　わたし、もう悠太くんの彼女で本当によかった……もっと、中まで来てぇ……！" },
    { id: "b76", r18: true, name: "", text: "限界が近づく。美咲さんは脚を絡め、子宮を最奥に寄せるように腰を落とし切った。耳元で、震える声が囁く。" },
    { id: "b77", r18: true, name: "美咲", text: "出して……中に出して、悠太くん……！　実はね、わたしのお腹、もう……あなたの赤ちゃんがいるかもしれないの。だから、もっと愛を注いで……！" },
    { id: "b78", r18: true, name: "", text: "最奥深くで射精。美咲さんは歓喜に目を潤ませ、注がれる熱を全て受け止めた。二人は額を寄せ合い、笑い合う。" },
    { id: "b79", face: "love", r18: true, name: "美咲", text: "あぁ……いっぱい……。ねえ、答え合わせしよっか。……うん、陽性だったの。わたし、悠太くんの赤ちゃんを妊娠したみたい。……責任、取ってくれる？", jump: "b87" },
    { id: "b80", bgm: "love", bg: "store", name: "", text: "――開店初日の朝。シャッターの前で、美咲は深呼吸をしていた。手書きの看板には、少しだけ震えた字で「朝ごはんの店」。その隣で、大きなお腹が朝日を受けて丸く光っている。\n「……緊張する。でもね、悠太くん。一番最初のお客さんは、ずっと前から決まってるの。……はい、卵焼きの大盛り。常連第一号さん、特別盛りだよ」\n卵焼きの甘い匂いが、小さな店に満ちていく。真夜中のコンビニから始まった恋は、朝の光の店と、もうすぐ生まれる小さな命の待つ場所へ――静かに、確かにたどり着いていた。\n【GOOD END ― 真夜中のコンビニ】", end: true },
    { id: "b81", bg: "street", name: "", text: "――回想：ある夜勤明け。店を出た美咲さんが、珍しく遠回りの散歩に誘ってきた。夜明け前の公園で、二人並んでベンチに座る。" },
    { id: "b82", face: "smile", char: true, name: "美咲", text: "ねえ悠太くん。わたし、前の職場は普通のOLだったんだよ。でも合わなくて辞めて、今のバイトに。……笑う？　22歳、フリーターだよ、わたし。" },
    { id: "b83", name: "悠太", text: "笑いません。美咲さんは仕事に誇りを持ってる。誰が見ても一流の店員です。" },
    { id: "b84", face: "smile", name: "美咲", text: "……ふふ、ありがとう。そう言ってくれたの、初めて。……わたしの夢ね、いつか自分の小さな食堂を開くこと。だから今は、お金を貯めてる途中なの。" },
    { id: "b85", name: "悠太", text: "美咲さんなら絶対できます。開いたら、常連第一号は俺でお願いします。" },
    { id: "b86", face: "smile", name: "美咲", text: "約束だよ。……ねえ、星が見える。夜勤族だけの特権だね。……さ、帰ろう。雨の様子も、見なきゃだし。", jump: "b43" },
    { id: "b87", bg: "room", r18: true, name: "", text: "「もちろん」――そう答えると、美咲さんは声を上げて俺に抱きついてきた。涙と笑顔が、同時に浮かんだ顔。" },
    { id: "b88", face: "cry", r18: true, name: "美咲", text: "……！　悠太くん……ありがとう。ふふ、わたし、嬉しすぎて泣いちゃいそう。……ねえ、今夜は記念日。朝まで、わたしを愛して？" },
    { id: "b89", r18: true, name: "", text: "美咲さんは涙を拭うと、俺の手を引いてベッドへ向かった。雨上がりの夜、窓の外は静かで、部屋には二人の鼓動だけが響いている。" },
    { id: "b90", r18: true, name: "美咲", text: "ねえ悠太くん。わたし、ずっと言いたかったの。……あなたが来てから、夜勤が楽しみで仕方なかった。コンビニの片隅で、恋をしてたの。" },
    { id: "b91", r18: true, name: "", text: "美咲さんは自ら服を脱ぎ、豊かな乳房と濡れた秘部を晒す。妊娠した体は、少しだけ丸みを帯び始めている気がした。……愛おしい、と思う。" },
    { id: "b92", face: "smile", r18: true, name: "美咲", text: "見て、悠太くん。わたしのお腹、ここにあなたの赤ちゃんがいるの。……ねえ、触って。……ふふ、温かいでしょう？　あなたの愛の証だよ。" },
    { id: "b93", r18: true, name: "", text: "そっと腹に手を当てると、美咲さんは嬉しそうに目を細めた。やがて彼女は俺を押し倒し、大きな乳房を押し付けながら唇を重ねてきた。" },
    { id: "b94", face: "pleasure", r18: true, name: "美咲", text: "んっ、んんっ……悠太くん、今夜はわたしがリードする番。……先輩彼女の特権、最後まで味わって。ほら、わたしの胸、好きにしていいよ。" },
    { id: "b95", r18: true, name: "", text: "乳房を揉み、乳首を舌で転がすと、美咲さんは甘い声を上げた。やがて彼女は俺のものを口に含み、熱心に奉仕する。年上の余裕と、甘えが同居する姿。" },
    { id: "b96", face: "pleasure", r18: true, name: "美咲", text: "んっ……悠太くんの、もうこんなに硬い。……ふふ、わたしのせいだね。……ねえ、もう我慢しなくていいよ。わたしの中に、来て。" },
    { id: "b97", r18: true, name: "", text: "美咲さんが自ら跨り、濡れた秘部で先端を捉える。ゆっくりと腰を沈め、根元まで飲み込むと、彼女は歓喜の声を上げた。熟れた膣は熱く絡みつく。" },
    { id: "b98", face: "pleasure", r18: true, name: "美咲", text: "あぁん、あぁっ……！　悠太くん、深い、すごい……！　わたしの中、全部あなたでいっぱい……気持ちいい、気持ちよすぎるぅ……" },
    { id: "b99", r18: true, name: "", text: "騎乗位で腰を振る美咲さん。大きな乳房が目の前で跳ね、膣壁は強く締め付けてくる。体位を変え、後ろから深く突き上げると、声が一層高くなる。" },
    { id: "b100", face: "pleasure", r18: true, name: "美咲", text: "あんっ、あんっ、あぁ……！　悠太くん、もっと、もっとぉ……！　わたし、あなたの彼女で、あなたのお子のお母さん……幸せすぎて、壊れちゃう……！" },
    { id: "b101", r18: true, name: "", text: "限界が近づく。美咲さんは脚を絡め、子宮を最奥に寄せるように腰を落とし切った。耳元で、震える声が囁く。" },
    { id: "b102", face: "ecstasy", r18: true, name: "美咲", text: "中に出して、悠太くん……！　二回目も、三回目も、わたしのお腹いっぱいにして……！　あぁっ、イク、わたしもイッちゃう……一緒に……！！" },
    { id: "b103", r18: true, name: "", text: "最奥深くで射精。美咲さんは歓喜に目を潤ませ、注がれる熱を全て受け止めた。溢れた白濁が、シーツに広がっていく。" },
    { id: "b104", r18: true, name: "", text: "抱き合ったまま、美咲さんは俺の胸で穏やかな寝息を立て始めた。――真夜中のコンビニから始まった恋は、もうすぐ三人の家族になる。", jump: "b125" },
    { id: "b105", bg: "street", name: "", text: "――その週末。夜勤明けの二人は、初めて昼間のデートに出かけた。待ち合わせは、昼下がりの駅前。美咲さんは私服で、少しだけ緊張していた。" },
    { id: "b106", face: "shy", char: true, name: "美咲", text: "悠太くん……どう？　私服のわたし、変じゃない？　……いつも制服ばかりだから、なんだか落ち着かなくて。" },
    { id: "b107", name: "悠太", text: "……全然、変じゃないです。……すごく、可愛いです。……美咲さん、普段と違う服だと、なんだか新鮮で。" },
    { id: "b108", face: "smile", name: "美咲", text: "……っ！　もう、悠太くんってば。……ふふ、ありがとう。……じゃあ今日は、先輩じゃなくて、彼女の美咲でいくからね。" },
    { id: "b109", name: "", text: "まず向かったのは、駅ビルの雑貨屋。美咲さんはキッチン用品の前で、目を輝かせていた。" },
    { id: "b110", name: "美咲", text: "ねえ悠太くん、見て。このマグカップ、可愛くない？　……うちに来たとき、これでコーヒー出してあげる。……ねえ、どっちがいい？" },
    { id: "b111", name: "悠太", text: "……こっちの青いのがいいな。……美咲さんの部屋に合うと思う。……って、俺が選んでいいんですか？" },
    { id: "b112", face: "smile", name: "美咲", text: "もちろん。……ふふ、彼氏の選んだマグで飲むコーヒー、絶対美味しい。……ねえ、これ、買っちゃお。……二つ、ね。" },
    { id: "b113", name: "", text: "マグカップを二つ買って、次は映画館。昼間の映画は空いていて、二人だけの貸切みたいだった。" },
    { id: "b114", face: "shy", name: "美咲", text: "……ねえ悠太くん。……暗いと、なんだかドキドキするね。……手、繋いでもいい？　……ふふ、もう繋いでる。" },
    { id: "b115", name: "", text: "映画の間、美咲さんは俺の肩に頭を預けてきた。ポップコーンを分け合い、笑い合う。夜勤のときとは違う、昼の顔。" },
    { id: "b116", face: "smile", name: "美咲", text: "……ふふ、面白かった。……ねえ悠太くん、映画のあとはカフェに行こう？　……わたし、ここのケーキが好きなの。" },
    { id: "b117", name: "", text: "カフェの窓際で、美咲さんはケーキを頬張った。生クリームを唇につけて、少しだけ笑う。" },
    { id: "b118", name: "悠太", text: "……美咲さん、唇にクリームついてますよ。……ほら、ここ。……ふふ、拭いてあげますね。" },
    { id: "b119", face: "smile", name: "美咲", text: "……っ！　悠太くん……。……ありがとう。……ねえ、わたしって、悠太くんの前だと、すごく甘えん坊になるね。" },
    { id: "b120", name: "悠太", text: "……いいですよ。……美咲さんが甘えてくれるの、俺、嬉しいです。……先輩の顔も好きだけど、彼女の顔はもっと好きです。" },
    { id: "b121", face: "love", name: "美咲", text: "……っ！　もう、悠太くんって、時々すごくずるい。……ふふ、じゃあ、わたしも言うね。……悠太くん、好き。大好き。" },
    { id: "b122", name: "", text: "夕方、駅前の噴水の前で、二人は並んで座った。昼間のデートは、夜勤とは違う温かさがあった。" },
    { id: "b123", name: "美咲", text: "……ねえ悠太くん。……今日、すごく楽しかった。……今度は、昼のシフトの話、ちゃんとしようね。……わたし、悠太くんと同じ時間が欲しいの。" },
    { id: "b124", name: "悠太", text: "……はい。……美咲さん、今日はありがとうございました。……さ、そろそろ帰りましょうか。……今夜も、夜勤がありますしね。", jump: "b64" },
    { id: "b125", bg: "room", r18: true, name: "", text: "――記念日の夜。ケーキを食べ終え、美咲さんは俺の膝の上に座った。窓の外では、真夜中のコンビニの灯りが静かに瞬いている。" },
    { id: "b126", r18: true, name: "美咲", text: "悠太くん……今日は、ほんとに幸せだった。……ねえ、もう少しだけ、こうしていていい？" },
    { id: "b127", r18: true, name: "悠太", text: "もちろんです。……美咲さん、今日はありがとうございました。……俺も、幸せです。" },
    { id: "b128", r18: true, name: "", text: "美咲さんは俺の首に腕を回し、そっと唇を重ねてきた。ケーキの甘い香りと、少しの緊張。" },
    { id: "b129", face: "love", r18: true, name: "美咲", text: "ねえ、悠太くん。……わたしね、今日、決めたの。……今夜は、わたしから誘うの。……記念日だから。" },
    { id: "b130", r18: true, name: "", text: "頷くと、美咲さんはベッドに横たわり、自ら俺の服を脱がせていく。大きな乳房が、月明かりに白く浮かぶ。" },
    { id: "b131", face: "pleasure", r18: true, name: "美咲", text: "んっ……悠太くんの唇、甘い……ケーキの味がする。……ねえ、もっと……わたしを、抱きしめて？" },
    { id: "b132", r18: true, name: "", text: "乳房を包むように揉むと、美咲さんは甘い声を漏らした。先端はすっかり硬くなり、彼女の吐息が熱い。" },
    { id: "b133", face: "love", r18: true, name: "美咲", text: "ねえ、見て……わたしのお腹。……ここに、悠太くんの赤ちゃんがいるの。……不思議だね。……ねえ、触って……確かめて？" },
    { id: "b134", r18: true, name: "", text: "お腹にそっと手を当てると、美咲さんは嬉しそうに微笑んだ。温かい体温が、手のひらに伝わる。" },
    { id: "b135", face: "pleasure", r18: true, name: "美咲", text: "あぁっ……悠太くん……奥、気持ちいい……ねえ、もう……入れて……わたしの中、もうとろとろなの……" },
    { id: "b136", r18: true, name: "", text: "濡れそぼった秘部に、ゆっくりと腰を沈める。美咲さんは俺の背中にしがみつき、歓喜の声を上げた。" },
    { id: "b137", face: "love", r18: true, name: "美咲", text: "もっと……もっと深く……わたし、悠太くんのが大好きなの。……ねえ、もっと奥まで……" },
    { id: "b138", r18: true, name: "", text: "夢中で腰を振る美咲さん。膣壁がうねるように絡みつき、結合部からは愛液が溢れて太ももを伝う。俺は乳房を揉みながら、下から突き上げた。" },
    { id: "b139", r18: true, name: "美咲", text: "中に出して……ねえ、悠太くん……わたしのお腹に、注いで……この子にも、届くくらい……パパの愛で、いっぱいにして……！" },
    { id: "b140", r18: true, name: "", text: "最奥深くで射精。美咲さんは子宮で受け止めるように腰を寄せ、注がれる熱に幸福そうに震えた。" },
    { id: "b141", r18: true, name: "美咲", text: "あぁ……温かい……ねえ悠太くん、わたし、絶対に幸せになる。……悠太くんと、この子と、三人で。" },
    { id: "b142", r18: true, name: "", text: "抱き合ったまま、美咲さんは俺の胸で穏やかな寝息を立て始めた。――真夜中のコンビニから始まった恋は、もうすぐ三人の家族になる。", jump: "b163" },
    { id: "b143", bg: "store", name: "", text: "――連絡先を交換し終えた頃、夜勤は明け方を迎えていた。窓の外では、雨上がりの朝日が静かに街を染め始めている。" },
    { id: "b144", name: "美咲", text: "ねえ悠太くん。……夜勤明けって、お腹空かない？　……わたし、朝ごはん作るの、得意なんだ。……食べていかない？" },
    { id: "b145", name: "悠太", text: "美咲さん、朝ごはん……いいんですか。……俺、コンビニのおにぎりで済ませるつもりでした。" },
    { id: "b146", name: "", text: "美咲さんは笑いながら、店のイートインコーナーに俺を座らせた。レジの奥から、温かいお弁当箱を取り出してくる。" },
    { id: "b147", face: "smile", name: "美咲", text: "はい、卵焼きと鮭の焼き魚。……夜勤の合間に作っておいたの。……ふふ、悠太くんのため、ってわけじゃないよ？　……たまたま、ね。" },
    { id: "b148", name: "", text: "弁当箱を開けると、湯気がふわりと立ちのぼった。卵焼きは綺麗な黄色で、鮭はこんがりと焼けている。……めちゃくちゃ、美味しそうだ。" },
    { id: "b149", name: "悠太", text: "……うまい。本当にうまいです、美咲さん。……夜勤明けに、こんな朝ごはんが食べられるなんて。" },
    { id: "b150", name: "美咲", text: "でしょ？　……わたしね、いつか自分の小さな食堂をやりたいの。……夜勤の人たちが、ほっとできる場所を。" },
    { id: "b151", name: "", text: "美咲さんは窓の外を見ながら、少しだけ遠い目をした。雨上がりの街に、朝の光が少しずつ広がっていく。" },
    { id: "b152", face: "smile", name: "美咲", text: "ねえ悠太くん。……わたしの夢、笑わない？　……コンビニで働きながら、いつか自分の店を持つなんて、無謀だよね。" },
    { id: "b153", name: "悠太", text: "笑いませんよ。……美咲さんの料理、こんなに美味しいんですから。……絶対、繁盛しますよ。……俺、常連になります。" },
    { id: "b154", name: "", text: "美咲さんは頬を染め、嬉しそうに微笑んだ。イートインの窓から差し込む朝日が、彼女の横顔を柔らかく照らしている。" },
    { id: "b155", face: "serious", name: "美咲", text: "……ありがとう、悠太くん。……ねえ、約束して？　……わたしの店ができたら、一番最初のお客さんになって。" },
    { id: "b156", name: "悠太", text: "もちろんです。……一番乗りで、行きますよ。……そのときは、卵焼きを大盛りでお願いします。" },
    { id: "b157", face: "smile", name: "美咲", text: "ふふ、了解。……じゃあ、わたしも約束する。……悠太くんの分は、いつも特別盛りにするからね。" },
    { id: "b158", name: "", text: "朝ごはんを食べ終え、二人で店の外に出た。雨上がりのアスファルトが、朝日を反射してキラキラと光っている。" },
    { id: "b159", name: "美咲", text: "ねえ、今日はこのまま帰るの、もったいないね。……よかったら、近くの公園まで歩かない？　……朝の空気、気持ちいいよ。" },
    { id: "b160", name: "悠太", text: "いいですね。……美咲さんと歩く朝の街、なんだか特別な気がします。……ほら、桜の木の下、ベンチが空いてますよ。" },
    { id: "b161", name: "", text: "公園のベンチに並んで座り、しばらく何も言わずに朝の街を眺めた。美咲さんの肩が、そっと俺の肩に触れる。" },
    { id: "b162", name: "美咲", text: "……ねえ悠太くん。……今日の朝ごはん、美味しかった？　……うん、よかった。……また作るからね、次も。", jump: "b81" },
    { id: "b163", bg: "room", r18: true, name: "", text: "――ベビー用品を揃えた夜。美咲さんは小さな肌着を広げ、俺の部屋で嬉しそうに笑った。窓の外では、真夜中のコンビニの灯りが静かに瞬いている。" },
    { id: "b164", face: "smile", r18: true, name: "美咲", text: "悠太くん、見て……こんなに小さいの。……ねえ、この子、こんな小さな服を着るのよ。……ふふ、可愛いでしょう？" },
    { id: "b165", r18: true, name: "悠太", text: "ほんとに小さいですね……美咲さん、もうすっかりお母さんの顔ですよ。……俺、ますます楽しみになってきました。" },
    { id: "b166", r18: true, name: "", text: "美咲さんは肌着をそっと畳み、俺の胸に頬を寄せた。鼓動が、少しだけ早い。" },
    { id: "b167", r18: true, name: "美咲", text: "ねえ、悠太くん……今日は、記念にしよう？　……ベビー用品、全部揃った夜だから。……ねえ、抱いて……？" },
    { id: "b168", r18: true, name: "", text: "頷くと、美咲さんは俺の首に腕を回し、そっと唇を重ねてきた。新しい肌着の柔らかい綿の匂いと、少しの緊張。" },
    { id: "b169", face: "pleasure", r18: true, name: "美咲", text: "んっ……悠太くん……優しい……ねえ、もっと……わたしを、抱きしめて？" },
    { id: "b170", r18: true, name: "", text: "ベッドに横たわり、美咲さんは自ら俺の服を脱がせていく。大きな乳房が、月明かりに白く浮かぶ。" },
    { id: "b171", r18: true, name: "美咲", text: "ねえ、見て……わたしのお腹、少し大きくなったでしょう？　……ここに、悠太くんの赤ちゃんがいるの。……ねえ、触って……確かめて？" },
    { id: "b172", r18: true, name: "", text: "お腹にそっと手を当てると、美咲さんは俺の手の上に自分の手を重ねた。二人分の温もりの下で、小さな命が静かに育っている。" },
    { id: "b173", face: "pleasure", r18: true, name: "美咲", text: "あぁっ……悠太くん……奥、気持ちいい……ねえ、入れて……名前の候補、考えるはずが……わたし、もうとろとろなの……" },
    { id: "b174", r18: true, name: "", text: "濡れそぼった秘部に、ゆっくりと腰を沈める。美咲さんは畳んだ肌着を枕元に、小さく息を呑んで俺の腕にしがみついた。" },
    { id: "b175", face: "love", r18: true, name: "美咲", text: "もっと……もっと奥まで……この子に付ける名前、パパの口から聞く日が……待ち遠しいの……" },
    { id: "b176", r18: true, name: "", text: "美咲さんは腰をくねらせ、熱くうねる内壁が俺を締めつけた。結合部から溢れた愛液が太ももを伝い、俺は乳房を揉みながら、優しく突き上げた。" },
    { id: "b177", r18: true, name: "美咲", text: "中に出して……ねえ、悠太くん……わたしのお腹に、注いで……この子はね、もう名前の候補があるの。……生まれたら、最初に呼んであげて……パパの声で。" },
    { id: "b178", r18: true, name: "", text: "最奥深くで射精。美咲さんはお腹を守るようにそっと丸くなり、注がれる熱に幸福そうに震えた。" },
    { id: "b179", r18: true, name: "美咲", text: "あぁ……温かい……ねえ悠太くん、この子が生まれたら、わたしの食堂で育てるの。……三人で、温かいごはんを食べるの。" },
    { id: "b180", r18: true, name: "", text: "美咲さんは俺の胸に顔を埋めたまま、穏やかな寝息を立て始めた。小さな肌着が、月明かりにそっと白く浮かんでいた。", jump: "b201" },
    { id: "b181", bg: "store", name: "", text: "――翌朝。美咲さんはエプロン姿のまま、コンビニのバックヤードで朝ごはんの準備をしていた。" },
    { id: "b182", face: "smile", name: "美咲", text: "おはよう、悠太くん。……ふふ、昨日の夜のこと、忘れてないよね？　わたしは、もう忘れられないよ。" },
    { id: "b183", name: "悠太", text: "忘れるわけないですよ。……美咲さん、朝から元気ですね。" },
    { id: "b184", name: "美咲", text: "当たり前よ。だって今日から、悠太くんはわたしの彼氏なんだから。……ほら、朝ごはん、食べてって。" },
    { id: "b185", name: "", text: "出されたのは、おにぎりと味噌汁と、美咲さん手作りの卵焼き。コンビニの片隅で食べる朝ごはんが、妙に温かかった。" },
    { id: "b186", name: "美咲", text: "ねえ、悠太くん。……あの朝、わたしの夢、笑わないで聞いてくれたよね。あれが嬉しくて、ずっと考えてたの。……小さくて、温かい食堂。いつか絶対、開きたいな。" },
    { id: "b187", name: "悠太", text: "覚えてますよ。……美咲さんなら、きっと素敵な店になりますよ。" },
    { id: "b188", face: "smile", name: "美咲", text: "ふふ、ありがとう。……その食堂でね、朝ごはんを出すの。昨日の夜勤明けの人にも、温かいごはんを食べてもらいたいの。" },
    { id: "b189", name: "", text: "卵焼きを一口。甘めの味付けは、美咲さんの優しさそのものだった。" },
    { id: "b190", name: "悠太", text: "美味しいです。……美咲さん、料理上手いんですね。将来の食堂、楽しみだな。" },
    { id: "b191", name: "美咲", text: "でしょ？　……じゃあ、悠太くんは常連第一号ね。毎朝、ここで朝ごはんを食べるのよ。" },
    { id: "b192", name: "悠太", text: "毎朝ですか。……それ、もう同棲みたいなものじゃないですか。" },
    { id: "b193", face: "smile", name: "美咲", text: "あら、バレた？　……ふふ、冗談よ。でもね、いつか本当に、そうなれたらいいなって思ってる。" },
    { id: "b194", name: "", text: "美咲さんは少しだけ頬を染めて、コーヒーを注いだ。湯気が、朝の光に白く揺れる。" },
    { id: "b195", name: "美咲", text: "ねえ悠太くん、今日は休みでしょ？　……よかったら、昼から一緒に買い物に行かない？　食堂の夢の、第一歩として。" },
    { id: "b196", name: "悠太", text: "いいですね。……じゃあ、食器の片付け、手伝いますよ。" },
    { id: "b197", face: "smile", name: "美咲", text: "ありがとう。……ふふ、彼氏がいると、朝ごはんの片付けまで楽しいのね。" },
    { id: "b198", name: "", text: "片付けを終え、二人で店を出る。朝の光の中、美咲さんは俺の腕にそっと寄り添った。" },
    { id: "b199", name: "美咲", text: "今日はいい日になりそう。……ねえ悠太くん、わたしの夢、叶えようね。二人で。" },
    { id: "b200", name: "", text: "――朝の街を歩く二人の影は、もうすっかり恋人同士のものだった。", jump: "b63" },
    { id: "b201", bg: "room", r18: true, name: "", text: "――食堂の名前を考えた夜。美咲さんはノートに候補を並べ、俺の部屋で嬉しそうに笑った。窓の外では、真夜中のコンビニの灯りが静かに瞬いている。" },
    { id: "b202", r18: true, name: "美咲", text: "悠太くん、見て……「食堂みさき」「朝ごはんの店」「温かい台所」……ねえ、どれがいいと思う？" },
    { id: "b203", r18: true, name: "悠太", text: "どれも美咲さんらしいですね……俺は「朝ごはんの店」が好きですよ。……美咲さんの朝ごはん、誰だって食べたくなるから。" },
    { id: "b204", r18: true, name: "", text: "美咲さんはノートをそっと閉じ、俺の胸に頬を寄せた。鼓動が、少しだけ早い。" },
    { id: "b205", r18: true, name: "美咲", text: "ねえ、悠太くん……今日は、記念にしよう？　……食堂の名前が、決まった夜だから。……ねえ、抱いて……？" },
    { id: "b206", r18: true, name: "", text: "頷くと、美咲さんは俺の首に腕を回し、そっと唇を重ねてきた。書きかけの看板の、木とペンキの匂いと、少しの緊張。" },
    { id: "b207", face: "pleasure", r18: true, name: "美咲", text: "んっ……悠太くん……ふふ、看板の字、明日また練習する……ねえ、もっと抱きしめて？" },
    { id: "b208", r18: true, name: "", text: "ベッドに横たわり、美咲さんは俺のシャツのボタンをゆっくり外していく。窓際の書きかけの看板が、月明かりに白く浮かぶ。" },
    { id: "b209", r18: true, name: "美咲", text: "ねえ、見て……わたしのお腹、もっと大きくなったでしょう？　……ここに、悠太くんの赤ちゃんがいるの。……ねえ、触って……確かめて？" },
    { id: "b210", r18: true, name: "", text: "お腹にそっと手を当てると、美咲さんは嬉しそうに微笑み、「決めた名前、この子にも聞かせたいな」と囁いた。" },
    { id: "b211", face: "pleasure", r18: true, name: "美咲", text: "あぁっ……悠太くん……奥……ねえ、入れて……店の名前、決まった夜なのに……わたし、もうとろとろ……" },
    { id: "b212", r18: true, name: "", text: "ゆっくりと腰を沈めると、美咲さんは枕元のノートを置き、俺の首に腕を回して歓喜の声を上げた。" },
    { id: "b213", face: "love", r18: true, name: "美咲", text: "もっと……もっと深く……決めた名前に負けないくらい……わたしを、温かくして……" },
    { id: "b214", r18: true, name: "", text: "夢中で腰を振る美咲さん。熱い内壁が絡みつき、結合部からは愛液が溢れてシーツに染みた。俺は彼女の背中を撫でながら、下から突き上げた。" },
    { id: "b215", r18: true, name: "美咲", text: "中に出して……ねえ、悠太くん……わたしのお腹に、注いで……この子が生まれたら、食堂で一緒に育てるの……！" },
    { id: "b216", r18: true, name: "", text: "最奥深くで射精。美咲さんは腰を寄せて受け止め、注がれる熱に幸福そうに震えた。指先が、枕元のノートにそっと触れる。" },
    { id: "b217", r18: true, name: "美咲", text: "あぁ……温かい……ねえ悠太くん、この子が生まれたら、食堂の看板を出すの。……「朝ごはんの店」ってね。" },
    { id: "b218", r18: true, name: "", text: "美咲さんは俺の腕に頬を寄せたまま、穏やかな寝息を立て始めた。ノートに書かれた食堂の名前が、月明かりにそっと白く浮かんでいた。", jump: "b239" },
    { id: "b219", bg: "store", name: "", text: "――休憩の缶コーヒーは、美咲さんの奢りだった。彼女は袖をまくり、少しだけ疲れた笑顔で、ポケットのノートを取り出す。" },
    { id: "b220", name: "美咲", text: "はい、悠太くん。……今日は雨の日で、お客さん少なかったね。……こういう夜は、ゆっくりできるから、わたしは好きだな。" },
    { id: "b221", name: "悠太", text: "ありがとうございます。……美咲さん、夜勤明けはどうするんですか？　……まっすぐ帰って、寝るんですか。" },
    { id: "b222", name: "", text: "美咲さんは缶コーヒーを一口飲み、少しだけ遠い目をした。バックヤードの蛍光灯が、静かに瞬いている。" },
    { id: "b223", name: "美咲", text: "うーん、今日はね。……帰ったら、食堂のメニューを考えるの。……朝ごはん定食の、新しい献立。" },
    { id: "b224", name: "悠太", text: "食堂のメニュー……ですか。……美咲さん、もう決めてるんですか？　……どんな店にするか。" },
    { id: "b225", name: "", text: "美咲さんはポケットから小さなノートを取り出した。ページには、献立の案がびっしりと書かれている。" },
    { id: "b226", name: "美咲", text: "見て、悠太くん。……焼き魚定食に、卵焼き、味噌汁、それと季節の小鉢。……ねえ、どう思う？　……朝から、ほっとする味でしょ？" },
    { id: "b227", name: "悠太", text: "すごい……もう、こんなに考えてたんですね。……美咲さんの朝ごはん、絶対に人気が出ますよ。……俺、毎日通います。" },
    { id: "b228", name: "", text: "美咲さんは嬉しそうに微笑み、ノートに新しい献立を書き加えた。ペンの音だけが、静かなバックヤードに響く。" },
    { id: "b229", name: "美咲", text: "……ねえ悠太くん。……食堂の名前、まだ決まらないの。候補はいくつかあるんだけど……どれも、ピンとこなくて。……悠太くんなら、なんて名前がいいと思う？" },
    { id: "b230", name: "悠太", text: "いい名前ですね。……美咲さんの字、温かくて好きです。……看板、きっと素敵になりますよ。" },
    { id: "b231", name: "", text: "美咲さんは缶コーヒーを置き、俺の肩にそっと頭を預けた。雨音が、店の外で静かに響いている。" },
    { id: "b232", name: "美咲", text: "……ねえ、悠太くん。……食堂ができたらさ、朝ごはんは二人で作るの。……悠太くんは卵焼き担当ね。……わたしの、弟子一号。" },
    { id: "b233", name: "悠太", text: "弟子一号、ですか。……光栄です。……でも俺、卵焼き、まだ美咲さんみたいに綺麗に焼けないですよ。" },
    { id: "b234", face: "smile", name: "美咲", text: "ふふ、大丈夫。……わたしが教えてあげる。……ねえ、悠太くんの卵焼き、甘めの味付けでしょ？　……わたし、知ってるんだから。" },
    { id: "b235", name: "", text: "美咲さんは笑いながら、ノートをそっと閉じた。夢の話をする彼女の横顔は、少しだけ誇らしげだった。" },
    { id: "b236", face: "smile", name: "美咲", text: "……よし、休憩おしまい。……閉店作業、残りを片付けよう。……ねえ悠太くん、今日もありがとうね。" },
    { id: "b237", name: "悠太", text: "こちらこそ。……美咲さん、食堂の話、また聞かせてくださいね。……俺、楽しみにしてますから。" },
    { id: "b238", name: "", text: "――バックヤードの休憩は終わった。缶コーヒーの空き缶と、食堂の夢のノートだけが、二人の秘密の時間の跡だった。", jump: "b39" },
    { id: "b239", bg: "room", r18: true, name: "", text: "――食堂の開店前夜。美咲さんはエプロンを着けて、明日の朝ごはんの仕込みをしていた。俺の部屋の小さな台所に、味噌汁の湯気がゆっくりと立ちのぼる。" },
    { id: "b240", r18: true, name: "美咲", text: "悠太くん、見て……明日の献立、決まったの。……焼き魚定食に、卵焼き、味噌汁、それと季節の小鉢。……ねえ、どう思う？" },
    { id: "b241", r18: true, name: "悠太", text: "すごい……もう、こんなに準備してたんですね。……美咲さんの朝ごはん、絶対に人気が出ますよ。……俺、明日、一番乗りします。" },
    { id: "b242", r18: true, name: "", text: "美咲さんはエプロンをそっと脱ぎ、俺の胸に頬を寄せた。鼓動が、少しだけ早い。" },
    { id: "b243", r18: true, name: "美咲", text: "ねえ、悠太くん……今日は、記念にしよう？　……食堂の開店前夜だから。……ねえ、抱いて……？" },
    { id: "b244", r18: true, name: "", text: "頷くと、美咲さんは俺の首に腕を回し、そっと唇を重ねてきた。味噌汁の香りと、少しの緊張。" },
    { id: "b245", face: "pleasure", r18: true, name: "美咲", text: "んっ……悠太くん……今夜は、ゆっくりでいいの……ねえ、朝までそばにいて……？" },
    { id: "b246", r18: true, name: "", text: "ベッドに横たわり、美咲さんは静かに俺の手を取った。大きくなったお腹の向こうで、月明かりが部屋を静かに満たしていた。" },
    { id: "b247", r18: true, name: "美咲", text: "ねえ、見て……わたしのお腹、こんなに大きくなったでしょう？　……もうすぐ、この子に会えるの。……ねえ、触って……二人で、確かめて？" },
    { id: "b248", r18: true, name: "", text: "お腹にそっと手を当てると、中から小さく蹴る感触があった。美咲さんは穏やかに微笑み、「会いたがってるね」と囁いた。" },
    { id: "b249", face: "pleasure", r18: true, name: "美咲", text: "あぁっ……悠太くん……ねえ、ゆっくり入れて……明日からの毎日を思うと……わたし、胸がいっぱいなの……" },
    { id: "b250", r18: true, name: "", text: "ゆっくりと腰を沈めると、美咲さんは俺の手を強く握り返し、深く息を吐いた。開店を待つ朝の前の、静かな夜だった。" },
    { id: "b251", face: "love", r18: true, name: "美咲", text: "もっと……ううん、焦らなくていい……この時間が、ずっと続けばいいのに……ねえ、悠太くん……" },
    { id: "b252", r18: true, name: "", text: "静かに腰を重ねるたび、熱い内側が締めつけ、愛液が静かに溢れた。俺は大きなお腹に負担をかけないよう、彼女を支えながらゆっくり突き上げた。" },
    { id: "b253", r18: true, name: "美咲", text: "中に出して……ねえ、悠太くん……今夜の愛を、全部ちょうだい……明日から、店と、この子と……わたし、全部頑張れるから……！" },
    { id: "b254", r18: true, name: "", text: "最奥深くで射精。美咲さんは静かに腰を寄せ、注がれる熱に安堵したように息を吐き、小さく震えた。" },
    { id: "b255", r18: true, name: "美咲", text: "あぁ……温かい……ねえ悠太くん、明日は、食堂の開店よ。……朝ごはんの店、みんなに食べてもらうの。" },
    { id: "b256", r18: true, name: "", text: "美咲さんは俺の腕の中で、やがて穏やかな寝息を立て始めた。エプロンが、月明かりにそっと白く浮かんでいた。", jump: "b80" }
  ]
},
{
  id: "rin",
  title: "研究室の最終電車",
  heroine: "凛（23歳）",
  desc: "大学院の研究室で徹夜する凛と、学部生の俺。最終電車を逃した夜、二人の距離が静かに近づく。",
  cover: "assets/rin_cover.webp",
  r18: true,
  images: { lab: "assets/rin_lab.svg", campus: "assets/rin_campus.svg", room: "assets/rin_room.svg", char: "assets/rin_char.webp" },
  scenes: [
    { id: "c01", bg: "lab", name: "", text: "夜11時の研究室。モニタの光と、サーバーのファンの音。\n学会発表を明日に控え、大学院生の凛さんはまだデータと睨めっこしていた。" },
    { id: "c02", face: "smile", char: true, name: "凛", text: "悠太、まだいたの。学部生は早く帰りなさい。……と言いたいけど、正直、いてくれると助かる。最後の集計、手伝ってくれる？" },
    { id: "c03", name: "悠太", text: "もちろんです。凛さんには卒論で世話になりましたから。……はい、差し入れの栄養ドリンクとおにぎり。" },
    { id: "c04", face: "smile", name: "凛", text: "……気が利くじゃない。ありがとう。じゃあ遠慮なく。あと2時間で終わらせるわよ、二人で。" },
    { id: "c05", name: "", text: "二人で黙々と作業する時間は、不思議と心地よかった。凛さんの横顔は真剣で、少しだけ疲れが見えた。", jump: "c42" },
    { id: "c06", face: "surprise", char: true, name: "凛", text: "……終わった。やっと終わったわ。悠太のおかげ。ねえ、時計見て。……最終電車、もう出た後よ。" },
    { id: "c07", choice: [
      { text: "「俺の部屋、近いので泊まっていいですよ」", jump: "c08", set: { love: 1 } },
      { text: "「研究室で仮眠しましょう」", jump: "c09", set: { love: 0 } }
    ] },
    { id: "c08", face: "shy", name: "凛", text: "……学部生の部屋に泊まる大学院生。噂になったらどうするの。……でも、背に腹は代えられないわね。お言葉に甘えるわ。", jump: "c10" },
    { id: "c09", name: "凛", text: "そうね、それが無難ね。……ソファは私がもらうわ。悠太は椅子で我慢して。", jump: "c16" },
    { id: "c10", bg: "room", name: "", text: "俺のワンルーム。凛さんはシャワーを借り、俺の大きめのTシャツを着て現れた。いつもの白衣姿とのギャップに、心臓が跳ねる。" },
    { id: "c11", face: "smile", char: true, name: "凛", text: "……何よ、じろじろ見て。似合わない？　……ふふ、冗談。ありがとう、悠太。今日は本当に助かった。" },
    { id: "c12", name: "悠太", text: "凛さん、明日の発表、絶対うまくいきますよ。俺、凛さんの研究が一番すごいと思ってますから。" },
    { id: "c13", face: "surprise", name: "凛", text: "……あなたって、本当に真っ直ぐよね。そういうところ、昔から……いえ、なんでもない。今夜はもう寝ましょう。" },
    { id: "c14", name: "", text: "布団を譲り、俺が床で丸くなろうとすると、凛さんが小さな声で呼び止めた。" },
    { id: "c15", face: "serious", name: "凛", text: "悠太。……こっち、来なさい。言いたいことがあるの。わたし、あなたのこと――" },
    { id: "c16", branch: { flag: "love", min: 1, then: "c17", else: "c21" } },
    { id: "c17", choice: [
      { text: "「俺も凛さんが好きです」と先に言う", jump: "c18", set: { love: 2, said: 1 } },
      { text: "言葉を待つ", jump: "c19", set: { love: 2, said: 0 } }
    ] },
    { id: "c18", face: "smile", name: "凛", text: "……先に言われた。悔しいけど、嬉しい。わたしもよ、悠太。ずっと、あなたが好きだった。", jump: "c20" },
    { id: "c19", face: "shy", name: "凛", text: "わたし、あなたが好き。院生と学部生なんて関係ない。……返事、聞かせて？", jump: "c20" },
    { id: "c20", name: "悠太", text: "……ありがとう、凛さん。……いえ、凛。俺と付き合ってください。", jump: "c257" },
    { id: "c21", bgm: "calm", face: "smile", bg: "campus", char: true, name: "凛", text: "昨夜はありがとう。発表、頑張ってくるわ。……また研究室でね、悠太。\n【NORMAL END ― 朝のキャンパス】", end: true },
    { id: "c22", face: "shy", r18: true, name: "凛", text: "……じゃあ今夜は、研究の話はおしまい。女としてのわたしを、ちゃんと見て。悠太。" },
    { id: "c23", r18: true, name: "", text: "凛は自分から眼鏡を外し、俺の首に腕を回した。いつも理知的な彼女の、熱っぽい吐息と潤んだ瞳。借りたTシャツ一枚の下の体の熱に、理性が溶けていく。" },
    { id: "c24", face: "pleasure", r18: true, name: "凛", text: "んっ……悠太、悠太……。わたし、初めてなの。優しく……いえ、あなたの好きにしていい。全部、悠太にあげる。" },
    { id: "c25x", r18: true, name: "", text: "Tシャツを脱がせると、下着姿の凛が現れた。整った体つきに、意外なほど豊かな乳房。ブラを外して揉みほぐすと、凛は耳まで赤くして身を任せた。乳首は既に固く勃ち上がっている。" },
    { id: "c26x", face: "pleasure", r18: true, name: "凛", text: "あっ……んんっ、悠太、そんなに強く……あぁ、だめ、声が出ちゃう……。研究室じゃ、こんな顔、誰にも見せたことないのに……" },
    { id: "c27x", r18: true, name: "", text: "下着を脱がせ、脚の間へ顔を埋める。秘部は既に愛液で濡れ光り、舌で舐め上げると凛の体が大きく震えた。クリトリスを吸い、舌先で転がすたび、理知的な彼女の口から甘い嬌声が止まらなくなる。" },
    { id: "c28x", face: "pleasure", r18: true, name: "凛", text: "あぁっ、あああっ……！　悠太、そこ、そこぉ……！　イグ、わたし、もう……あああっ……！！" },
    { id: "c29x", r18: true, name: "", text: "凛は一度大きく絶頂し、荒い息を吐いた。それでも俺を求める手は止まらない。潤み切った入り口に先端を当てがうと、彼女は自分から腰を寄せてきた。" },
    { id: "c30x", r18: true, name: "凛", text: "来て、悠太……わたしの中、あなたで満たして。初めては、あなたに全部壊してほしいの……ゆっくり、奥まで、入れて……" },
    { id: "c31x", r18: true, name: "", text: "狭い膣を割り開きながら、ゆっくりと沈めていく。処女膜を破る感触と共に、凛は痛みに顔を歪めながらも、俺の背にしがみついて離れなかった。最奥まで収まると、二人同時に息を吐く。" },
    { id: "c32x", r18: true, name: "凛", text: "うっ……あぁ、入った……悠太のが、わたしの中に……。熱い、大きい……わたしの体が、あなたの形になっていくみたい……" },
    { id: "c33x", r18: true, name: "", text: "痛みが引くのを待ち、少しずつ腰を動かす。やがて凛の表情から苦痛が消え、快感に目を細め始めた。内壁は抽送のたびに蠢き、絡みつくように締まってくる。" },
    { id: "c34x", face: "pleasure", r18: true, name: "凛", text: "あんっ、あんっ、あぁ……！　悠太、気持ちいい……！　頭が真っ白になる……もっと、もっと突いて、私をあなたのものにして……！" },
    { id: "c35x", r18: true, name: "", text: "激しく腰を打ち付け、豊かな乳房を揺らす。凛は枕に顔を埋めて喘ぎ、やがて耐えきれず大きな声を上げた。膣が痙攣し、絶頂が彼女を貫く。" },
    { id: "c36x", face: "ecstasy", r18: true, name: "凛", text: "イッてる、またイッちゃう……！　悠太、悠太ぁ……！　好き、大好き……もうあなたなしじゃ、生きていけない……！" },
    { id: "c37x", r18: true, name: "", text: "絶頂の連続に震える凛を抱き、俺も限界を迎えた。凛は俺の顔を引き寄せ、唇を重ねながら囁く。" },
    { id: "c38x", r18: true, name: "凛", text: "中に出して、悠太……！　あなたの子が欲しいの。わたしのお腹で、あなたの赤ちゃんを育てたい……だから、中で、いっぱい出して……！" },
    { id: "c39x", r18: true, name: "", text: "最奥深くで射精する。凛は子宮で受け止めるように腰を押し付け、注がれる熱に歓喜の涙を浮かべた。結合部からは、入りきらなかった白濁が僅かに溢れる。" },
    { id: "c40x", face: "love", r18: true, name: "凛", text: "あぁ……熱い……いっぱい、出してくれたね……。ふふ、わたし、あなたの彼女で、将来の奥さん。……ねえ悠太、今夜はまだ終わらせない。もう一度、最初からして？", jump: "c53" },
    { id: "c41x", r18: true, name: "", text: "夜が明けるまで、二人は何度も愛を確かめ合った。翌日の学会発表で、凛はいつも以上に輝いていたという。\n――俺だけが知る、あの夜の素顔を胸に秘めて。" },
    { id: "c28", face: "smile", bg: "room", name: "凛", text: "おはよう、悠太。……ふふ、その寝癖。今日からわたしは、あなたの彼女。研究室でも、よろしくね。", jump: "c181" },
    { id: "c42", bg: "lab", name: "", text: "作業の手を止め、凛さんは小さく伸びをした。肩に手を置くと、思ったより細く、温かい。研究室の蛍光灯の下で、二人だけの時間が流れていく。", jump: "c219" },
    { id: "c43", face: "serious", char: true, name: "凛", text: "……悠太、少し聞いて。わたし、来年で卒業なの。就職は、他県の研究所に決まりそうで。……だから、この研究室にいられる時間は、もう長くないのよ。" },
    { id: "c44", name: "悠太", text: "……知らなかった。凛さんがいなくなるなんて、考えたこともなかったです。" },
    { id: "c45", face: "sad", name: "凛", text: "寂しいのは、わたしも同じ。あなたみたいな後輩、もうできないでしょうね。真面目で、優しくて……つい頼ってしまうの、自分でも困ってるくらい。" },
    { id: "c46", name: "", text: "凛さんは自嘲気味に笑い、栄養ドリンクを開けた。少しだけ、目元が潤んでいた気がした。俺は、かける言葉を探して黙り込んでしまう。", jump: "c143" },
    { id: "c47", face: "sad", name: "凛", text: "……ごめんなさい、発表前夜に湿っぽくなって。さ、ラストスパートよ。終わったら、ちゃんとお礼をさせて。", jump: "c06" },
    { id: "c53", r18: true, name: "", text: "凛の誘いに、二度目の夜が始まる。今度は凛が主導権を握ろうと、俺をベッドに押し倒し、馬乗りになってきた。眼鏡の奥の瞳が、挑発的に細められる。" },
    { id: "c54", r18: true, name: "凛", text: "今度はわたしが上。悠太は寝てて。……さっきの仕返し、たっぷりしてあげる。わたしの体、もう全部あなたの形を覚えちゃったみたい……" },
    { id: "c55", r18: true, name: "", text: "凛は自ら秘部を擦り付け、濡れた入り口で先端を弄ぶ。焦らすような動きに限界が近づくと、彼女は微笑んでゆっくりと腰を沈めていった。" },
    { id: "c56", r18: true, name: "凛", text: "あぁっ……入って、る……わたしの中、あなたでいっぱい……。悠太、見て。あなたの上で乱れてる、彼女の姿。全部、頭に焼き付けて……？" },
    { id: "c57", r18: true, name: "", text: "凛は大きな乳房を揺らしながら腰を振る。膣壁は一回目より素直に絡みつき、抽送のたびに濡れた音を立てた。乳首を摘まむと、彼女の動きが激しくなる。" },
    { id: "c58", face: "pleasure", r18: true, name: "凛", text: "あんっ、あんっ、あぁ……！　悠太、気持ちいい……！　わたし、自分からこんなに腰振るなんて……あなたのせいで、淫らな女になっちゃった……" },
    { id: "c59", r18: true, name: "", text: "体位を変え、向かい合って脚を絡める密着位。凛は耳元で甘く囁きながら、深く腰を落としてきた。互いの吐息と鼓動が重なる。" },
    { id: "c60", face: "love", r18: true, name: "凛", text: "もっと近くにいて……悠太の匂い、声、心臓の音、全部感じたい。……好き、大好き……もう離れたくないの……" },
    { id: "c61", r18: true, name: "", text: "激しく求め合い、凛は何度目かの絶頂で大きく痙攣した。俺も限界を迎え、彼女の名を呼ぶ。" },
    { id: "c62", r18: true, name: "凛", text: "中、また中に出して……！　二回目も、わたしのお腹にちょうだい……あなたの赤ちゃんが、本当に欲しいの……だから、遠慮しないで……！" },
    { id: "c63", r18: true, name: "", text: "最奥深くで二度目の射精。凛は子宮で受け止めるように腰を押し付け、注がれる熱に潤んだ目で微笑んだ。結合部から白濁が溢れ、シーツを汚していく。" },
    { id: "c64", r18: true, name: "凛", text: "あぁ……いっぱい……二回も……。わたし、もう悠太のものだね。体も、心も、将来も。……明日の発表、絶対成功させて、あなたに報告するから。", jump: "c41x" },
    { id: "c65", bg: "campus", name: "", text: "――数週間後。凛の学会発表は大成功に終わり、就職も第一志望の研究所に内定した。ただし勤務地は隣県。引っ越しまで、あと2か月。", jump: "c105" },
    { id: "c66", face: "serious", char: true, name: "凛", text: "悠太。話があるの。……わたし、内定は受ける。でも、あなたと離れたくない。だから考えたの。あなたも、卒業したらこっちに来ない？　研究所の近くに、二人で住むの。" },
    { id: "c67", name: "悠太", text: "……行きます。凛のそばにいたい。就活、そっちで本気でやります。" },
    { id: "c68", face: "smile", name: "凛", text: "……！　本当に？　……ありがとう、悠太。わたし、幸せすぎて怖いくらい。じゃあ今夜は、お祝いと、約束の夜にしましょう。" },
    { id: "c69", bg: "room", name: "", text: "俺の部屋でささやかな祝杯。ワインの酔いも手伝って、凛は普段よりずっと甘えた様子で寄りかかってきた。" },
    { id: "c70", face: "love", r18: true, name: "凛", text: "悠太……わたし、最近体がおかしいの。胸が張って、眠くて……もしかしたら、あの夜のことが。……ねえ、今夜も中に頂戴。確信に変えたいの。" },
    { id: "c71", r18: true, name: "", text: "凛は自ら服を脱ぎ、眼鏡を外して俺を押し倒した。豊かな乳房を押し付け、舌を絡めるキスは熱く、積極的だった。" },
    { id: "c72", face: "pleasure", r18: true, name: "凛", text: "んっ、んんっ……悠太、今日はわたしが全部してあげる。……ほら、あなたのもの、もうこんなに。わたしの口で、気持ちよくしてあげる。" },
    { id: "c73", r18: true, name: "", text: "凛の口での奉仕は研究熱心そのものだった。舌先で弱点を探り、吸い上げ、喉奥まで咥え込む。限界寸前で解放されると、彼女は濡れた秘部を擦り付けてきた。" },
    { id: "c74", r18: true, name: "凛", text: "もう我慢しなくていいよ。……わたしの中に来て。今日は特別な日。あなたの子を授かる準備、わたしの体はもうできてるの……" },
    { id: "c75", r18: true, name: "", text: "凛が自ら腰を沈め、一気に根元まで飲み込む。慣れた膣は熱く蠢き、彼女は大きな乳房を揺らしながら夢中で腰を振った。" },
    { id: "c76", face: "pleasure", r18: true, name: "凛", text: "あぁっ、あんっ……！　悠太、すごい、奥まで届いてる……！　わたし、あなたの彼女で、将来の妻で……そして、あなたのお子のお母さんになるの……！" },
    { id: "c77", r18: true, name: "", text: "抱き合う体位、後ろからの体位と変えながら、何度も絶頂を繰り返す凛。射精の時を、彼女は自ら最奥で迎えに来た。" },
    { id: "c78", face: "ecstasy", r18: true, name: "凛", text: "出して、悠太……！　中に出して、わたしを孕ませて……！　あぁっ、イク、わたしもイッちゃう……悠太と一緒に……！！" },
    { id: "c79", r18: true, name: "", text: "最奥深くで射精。凛は絶頂と共に子宮で受け止め、注がれる熱に潤んだ目で微笑んだ。溢れた白濁が、彼女の腿を伝って落ちる。" },
    { id: "c80", face: "love", r18: true, name: "凛", text: "あぁ……熱い……いっぱい出してくれた……。ねえ悠太、実はもう検査したの。陽性。……わたし、あなたの赤ちゃんを妊娠してる。同棲の話、本気で進めましょう？　家族になるんだから。", jump: "c87" },
    { id: "c81", bgm: "love", bg: "room", name: "", text: "――数か月後。子供部屋の星柄の壁紙の下で、凛は眠る我が子を見つめていた。窓の外を、最終電車が静かに通り過ぎていく。\n「……ねえ悠太。あの夜、最終電車を逃してよかった。……逃してなかったら、学会の日の最前列のあなたにも、この子にも、会えなかった」\n最前列で見上げた発表の日の背中が、今は母親の背中になって、俺の隣で小さな寝息に耳を澄ましている。研究室の最終電車から始まった物語は、三人の朝の光の中へ――静かに続いていく。\n【GOOD END ― 研究室の最終電車】", end: true },
    { id: "c82", bg: "campus", name: "", text: "――回想：発表資料の買い出しに出た夕方。文具店の帰り道、凛さんは珍しく他愛ない話をした。" },
    { id: "c83", char: true, name: "凛", text: "わたしが研究者を目指した理由、聞きたい？　高校の時、恩師の先生に言われたの。『君の疑問は、誰かの答えになる』って。それが嬉しくて、今も頑張れてる。" },
    { id: "c84", name: "悠太", text: "素敵な先生ですね。凛さんの研究も、誰かの答えになってるはずです。俺の卒論みたいに。" },
    { id: "c85", face: "smile", name: "凛", text: "……ふふ、あなたは本当に、わたしの背中を押すのが上手い。……ねえ悠太、明日の発表、終わったら二人で打ち上げしましょう。約束よ。" },
    { id: "c86", name: "", text: "夕日のキャンパスを、二人で並んで歩いた。この人の隣にいられる時間を、もっと大事にしたいと思った。", jump: "c47" },
    { id: "c87", bg: "room", r18: true, name: "悠太", text: "……もちろん、凛。俺は凛と、赤ちゃんと、三人で暮らす。研究所の近くに、二人で住むって約束、今日から本気で進めよう。" },
    { id: "c88", face: "love", r18: true, name: "凛", text: "……！　悠太……ありがとう。ふふ、わたし、幸せすぎて怖いくらい。……ねえ今夜は、お祝いと誓いの夜。わたしを、朝まで愛して？" },
    { id: "c89", r18: true, name: "", text: "凛は眼鏡を外し、俺の首に腕を回した。研究室の彼女とは違う、蕩けた瞳。ワインの酔いも手伝って、彼女は普段よりずっと甘えていた。" },
    { id: "c90", face: "smile", r18: true, name: "凛", text: "ねえ悠太。引っ越し先、もう目星つけてあるの。研究所の近く、駅前のマンション。……子供部屋も、ちゃんとあるのよ。ふふ、気が早い？" },
    { id: "c91", r18: true, name: "", text: "凛の計画的な一面に、思わず笑ってしまう。彼女は頬を染めながら、俺のシャツのボタンに手をかけた。――今夜の凛は、研究者じゃない。一人の女だ。" },
    { id: "c92", r18: true, name: "凛", text: "悠太……わたし、あなたの子を宿した体で、あなたに愛されるの。……ねえ、触って。胸、張ってるでしょ？　あなたの赤ちゃんのせいだよ。" },
    { id: "c93", r18: true, name: "", text: "乳房を掌で包み、乳首を指先で転がす。凛は甘い吐息を漏らしながら、俺の頭を抱き寄せた。眼鏡のない顔は、いつもよりずっと無防備だ。" },
    { id: "c94", face: "pleasure", r18: true, name: "凛", text: "あっ……んんっ、悠太、そんなに丁寧に……あぁ、だめ、声が出ちゃう……。研究室じゃ、こんな顔、誰にも見せたことないのに……" },
    { id: "c95", r18: true, name: "", text: "秘部へ手を伸ばすと、愛液で濡れ光る入り口が、指を誘うように開いた。ゆっくりと沈め、内側を掻くように動かすと、凛の体が大きく震えた。" },
    { id: "c96", face: "ecstasy", r18: true, name: "凛", text: "あぁっ……！　悠太、もう、だめ……イッちゃった……。ねえ、早く……早くあなたを感じたい。わたしの中に、来て。" },
    { id: "c97", r18: true, name: "", text: "凛は俺の手を取ると、そっと自分のお腹に当てた。まだ平らな、けれど確かな命を宿した場所。彼女の指先が、微かに震えていた。" },
    { id: "c98", face: "serious", r18: true, name: "凛", text: "……ここに、いるのよ。わたしたちの子が。……ねえ悠太、わたし、研究も、この子も、どっちも諦めたくないの。……欲張り、かな。" },
    { id: "c99", r18: true, name: "", text: "抱き合う体位、後ろからの体位と変えながら、何度も絶頂を繰り返す凛。射精の時を、彼女は自ら最奥で迎えに来た。" },
    { id: "c100", face: "love", r18: true, name: "凛", text: "だから今夜は、もっと愛して。……この子を宿したわたしを、ちゃんと女として見て。……お願い、悠太。" },
    { id: "c101", r18: true, name: "", text: "最奥深くで射精。凛は絶頂と共に子宮で受け止め、注がれる熱に潤んだ目で微笑んだ。溢れた白濁が、彼女の腿を伝って落ちる。" },
    { id: "c102", r18: true, name: "凛", text: "あぁ……熱い……いっぱい出してくれた……。ねえ悠太、明日から同棲の準備、本気で始めるわよ。……わたしたち、もう家族なんだから。" },
    { id: "c103", r18: true, name: "", text: "凛は俺の胸に頬を寄せ、静かな寝息を立て始めた。眼鏡を外した寝顔は、研究室では見せない、無防備なものだった。" },
    { id: "c104", r18: true, name: "", text: "抱き合ったまま眠りに落ちる。――凛の寝息を聞きながら、俺は新しい街での暮らしを、そっと想像した。", jump: "c125" },
    { id: "c105", bg: "campus", name: "", text: "――その週末。引っ越し先の下見も兼ねて、二人で隣県の街へ出かけた。凛は地図を片手に、研究者の顔で街を歩く。" },
    { id: "c106", char: true, name: "凛", text: "ねえ悠太。見て、この街。研究所から駅まで徒歩10分。スーパーが二軒、図書館も近い。……住むには、悪くないわね。" },
    { id: "c107", name: "悠太", text: "……凛さん、もうすっかり引っ越しモードですね。……でも、俺も楽しみです。……凛さんと暮らす街、早く見たくて。" },
    { id: "c108", face: "smile", name: "凛", text: "……ふふ、そうね。……わたしも、楽しみ。……ねえ、あそこの不動産屋、覗いていかない？　……間取り、見てみたいの。" },
    { id: "c109", name: "", text: "不動産屋の前で、凛は真剣に物件情報を眺めた。2LDK、日当たり良好、家賃は少し高い。……二人の未来が、そこにあった。" },
    { id: "c110", name: "凛", text: "……ねえ悠太、この部屋。ベランダが広いの。……洗濯物も干せるし、植物も置ける。……わたし、ここ、気に入ったわ。" },
    { id: "c111", name: "悠太", text: "……いいですね。……って、凛さん、もう決めちゃうんですか？　……まだ内見もしてないのに。" },
    { id: "c112", face: "smile", name: "凛", text: "……あら、わたしは研究者よ。データが揃えば、結論は早いの。……ふふ、冗談。……でも、ここは候補ね。……覚えておいて。" },
    { id: "c113", name: "", text: "物件を後にして、駅前のカフェで一休み。凛はノートを開き、引っ越しの段取りを書き始めた。" },
    { id: "c114", name: "凛", text: "……ねえ悠太。引っ越しの荷物、わたしの本が一番多いの。……段ボール、何箱になると思う？　……当ててみて。" },
    { id: "c115", name: "悠太", text: "……うーん、20箱？　……いや、凛さんの本棚を見てると、30箱は超えそうです。" },
    { id: "c116", face: "smile", name: "凛", text: "……ふふ、正解は40箱よ。……重いから、運ぶのは悠太の仕事ね。……ふふ、冗談。……半分は、わたしが持つわ。" },
    { id: "c117", name: "", text: "カフェを出て、川沿いの遊歩道を歩く。夕日が川面に揺れ、凛の眼鏡が金色に光った。" },
    { id: "c118", face: "sad", name: "凛", text: "……ねえ悠太。……この街で、わたしと暮らすの、怖くない？　……就職も、引っ越しも、全部初めてのことばかりで。" },
    { id: "c119", name: "悠太", text: "……怖くないです。……凛さんとなら、どこでも大丈夫です。……俺、凛さんのそばにいたい。それだけです。" },
    { id: "c120", face: "smile", name: "凛", text: "……！　悠太……。……ありがとう。……ふふ、わたし、幸せすぎて怖いくらい。……ねえ、手、繋いでいい？" },
    { id: "c121", name: "", text: "夕日の遊歩道。凛の手は少し冷たくて、でも温かかった。……二人の影が、並んで伸びていく。" },
    { id: "c122", name: "凛", text: "……ねえ悠太。……今日、引っ越し先の下見、楽しかった。……ねえ、帰ったら、ワインで祝杯しましょう？　……内定と、新しい街の門出に。" },
    { id: "c123", name: "悠太", text: "……いいですね。……俺の部屋で、ささやかな祝杯。……凛さん、ワイン、買いましょうか。……駅前の酒屋、まだ開いてます。" },
    { id: "c124", face: "smile", name: "凛", text: "……ふふ、そうしましょう。……ねえ悠太、今日はありがとう。……わたし、あなたと一緒なら、どこでも幸せ。", jump: "c66" },
    { id: "c125", bg: "room", r18: true, name: "", text: "――引っ越し先の鍵を受け取った夜。凛は鍵を握りしめ、俺の部屋に来た。眼鏡の奥の瞳が、少しだけ潤んでいる。" },
    { id: "c126", face: "smile", r18: true, name: "凛", text: "ねえ悠太……これが、私たちの部屋の鍵よ。……ふふ、なんだか、夢みたい。" },
    { id: "c127", r18: true, name: "悠太", text: "凛さん……ついに、ですね。……俺たちの、新しい生活の始まりですね。" },
    { id: "c128", r18: true, name: "", text: "凛は鍵をそっとテーブルに置き、俺の胸に頬を寄せた。鼓動が、少しだけ早い。" },
    { id: "c129", r18: true, name: "凛", text: "ねえ、今日は祝杯の代わりに……わたしを、抱いて？　……新しい部屋の、最初の夜の予行演習よ。" },
    { id: "c130", r18: true, name: "", text: "頷くと、凛は俺の首に腕を回し、そっと唇を重ねてきた。ポケットの中の新しい鍵の冷たい感触と、少しの緊張。" },
    { id: "c131", face: "pleasure", r18: true, name: "凛", text: "んっ……悠太……眼鏡、外して……今夜は、研究者じゃないの。……あなたの恋人よ。" },
    { id: "c132", r18: true, name: "", text: "ベッドに横たわり、凛は自ら俺の服を脱がせていく。大きな乳房が、月明かりに白く浮かぶ。" },
    { id: "c133", r18: true, name: "凛", text: "ねえ、見て……わたしの体、もう……あなたのものよ。……ほら、ここ、熱くなってる。……ねえ悠太、触って……確かめて？" },
    { id: "c134", r18: true, name: "", text: "乳房を包むように揉むと、凛は甘い声を漏らした。先端はすっかり硬くなり、彼女の吐息が熱い。" },
    { id: "c135", r18: true, name: "凛", text: "あぁっ……悠太……深い……奥まで、届いてる……ねえ、もう……もっと……" },
    { id: "c136", r18: true, name: "", text: "濡れそぼった秘部に、ゆっくりと腰を沈める。凛は俺の背中にしがみつき、歓喜の声を上げた。" },
    { id: "c137", r18: true, name: "凛", text: "もっと……もっと激しく……わたし、悠太の前では、素直になれるの。……ねえ、もっと奥まで……" },
    { id: "c138", r18: true, name: "", text: "夢中で腰を振る凛。膣壁がうねるように絡みつき、結合部からは愛液が溢れて太ももを伝う。俺は乳房を揉みながら、下から突き上げた。" },
    { id: "c139", r18: true, name: "凛", text: "中に出して……ねえ、悠太……わたしの中に、あなたの愛をちょうだい……この子にも届くくらい……三人で、家族になるの……！" },
    { id: "c140", r18: true, name: "", text: "最奥深くで射精。凛は子宮で受け止めるように腰を寄せ、注がれる熱に幸福そうに震えた。" },
    { id: "c141", r18: true, name: "凛", text: "あぁ……いっぱい……ねえ悠太、わたしね、もう決めたの。……新しい部屋には、子供部屋も作るの。" },
    { id: "c142", r18: true, name: "", text: "凛は俺の胸に頬を寄せ、静かな寝息を立て始めた。眼鏡を外した寝顔は、研究室では見せない、恋人の顔だった。", jump: "c163" },
    { id: "c143", bg: "lab", name: "", text: "――研究室の深夜。学会発表の資料作りは、ようやく山場を越えようとしていた。凛さんは栄養ドリンクを開け、少しだけ目元を潤ませている。" },
    { id: "c144", name: "凛", text: "ねえ悠太……ちょっと、休憩しない？　……さっきは悠太が淹れてくれたから、今度はわたしの番。わたし、コーヒーを淹れるのが得意なの。……研究室のコーヒー、飲んでみる？" },
    { id: "c145", name: "悠太", text: "凛さん、コーヒー……いいんですか。……俺、てっきり栄養ドリンク派かと思ってました。" },
    { id: "c146", name: "", text: "凛さんは笑いながら、研究室の隅の小さなコーヒーメーカーに水を注いだ。豆を挽く音が、静かな深夜の研究室に響く。" },
    { id: "c147", face: "smile", name: "凛", text: "ふふ、研究者だって、たまには美味しいものが飲みたいの。……これはね、学会の帰りに買った豆。……ちょっと、高いのよ。" },
    { id: "c148", name: "", text: "コーヒーの香りが、研究室いっぱいに広がった。凛さんはマグカップを二つ並べ、丁寧に注いでいく。その横顔は、研究のときとは違う、柔らかい表情だった。" },
    { id: "c149", name: "悠太", text: "……うまい。……本当に、美味しいです、凛さん。……研究室でこんなコーヒーが飲めるなんて。" },
    { id: "c150", name: "凛", text: "でしょ？　……わたしね、研究が煮詰まったときは、いつもこうしてコーヒーを淹れるの。……香りで、頭をリセットするのよ。" },
    { id: "c151", name: "", text: "凛さんは窓の外を見ながら、少しだけ遠い目をした。深夜のキャンパスに、街灯の光がぽつりぽつりと灯っている。" },
    { id: "c152", face: "smile", name: "凛", text: "ねえ悠太……わたしの研究、笑わない？　……地味で、誰にも注目されないテーマだけど、わたしには大事なの。" },
    { id: "c153", name: "悠太", text: "笑いませんよ。……凛さんの研究、すごいと思います。……誰かの役に立つ研究って、こういう地道な積み重ねなんですよね。" },
    { id: "c154", name: "", text: "凛さんは眼鏡の奥で、少しだけ目を潤ませた。深夜の研究室に、二人分のコーヒーの湯気がゆっくりと立ちのぼる。" },
    { id: "c155", face: "serious", name: "凛", text: "……ありがとう、悠太。……ねえ、約束して？　……わたしの学会発表の日、見に来て。……緊張して、逃げ出しそうになるから。" },
    { id: "c156", name: "悠太", text: "もちろんです。……最前列で、見てますよ。……凛さんの発表、絶対に成功します。……俺が、保証します。" },
    { id: "c157", face: "smile", name: "凛", text: "ふふ、頼もしいわね。……じゃあ、わたしも約束する。……発表が終わったら、美味しいコーヒー、奢るからね。" },
    { id: "c158", name: "", text: "コーヒーを飲み終え、二人で研究室の窓を開けた。深夜の冷たい空気が、眠気を少しだけ吹き飛ばしていく。" },
    { id: "c159", name: "凛", text: "ねえ、今日はこのまま帰るの、もったいないわね。……よかったら、キャンパスを少し歩かない？　……夜の大学、静かで好きなの。" },
    { id: "c160", name: "悠太", text: "いいですね。……凛さんと歩く深夜のキャンパス、なんだか特別な気がします。……ほら、図書館の前、街灯が綺麗ですよ。" },
    { id: "c161", name: "", text: "並んで歩くキャンパスの並木道。凛さんの肩が、そっと俺の肩に触れる。研究の話も、学会の話も、全部、少しだけ温かく感じられた。" },
    { id: "c162", name: "凛", text: "……ねえ悠太。……今日のコーヒー、美味しかった？　……うん、よかった。……また淹れるからね、次も。", jump: "c82" },
    { id: "c163", bg: "room", r18: true, name: "", text: "――引っ越し前夜。凛の部屋は段ボールに囲まれ、床には本と実験器具が並んでいた。眼鏡の奥の瞳が、少しだけ潤んでいる。" },
    { id: "c164", face: "sad", r18: true, name: "凛", text: "ねえ悠太……明日から、私たちは新しい部屋よ。……ふふ、なんだか、寂しいような、嬉しいような。" },
    { id: "c165", r18: true, name: "悠太", text: "凛……この部屋とも、お別れですね。……でも、新しい部屋で、もっといい思い出を作りましょう。" },
    { id: "c166", r18: true, name: "", text: "凛は荷造りの手を止め、俺の胸に頬を寄せた。段ボールと本の匂いの中で、彼女の鼓動が少しだけ速かった。" },
    { id: "c167", r18: true, name: "凛", text: "ねえ、今日は……この部屋での、最後の夜よ。……ほら、段ボールの一番上。あなたの卒論の草稿、ずっと取ってあったの。……わたしを、抱いて？　この部屋の思い出ごと、新しい部屋に連れて行って。" },
    { id: "c168", r18: true, name: "", text: "頷くと、凛は俺の首に腕を回し、そっと唇を重ねてきた。段ボールと本の紙の匂いと、少しの緊張。" },
    { id: "c169", face: "pleasure", r18: true, name: "凛", text: "んっ……悠太……眼鏡、外して……この部屋で眠るの、今夜が最後よ。……今夜は、あなたの恋人でいたいの。" },
    { id: "c170", r18: true, name: "", text: "段ボールに囲まれたベッドに横たわり、凛は自ら俺の服を脱がせていく。荷物の隙間から、月明かりが細く差し込んでいた。" },
    { id: "c171", r18: true, name: "凛", text: "ねえ、見て……わたしの体、もう……あなたのものよ。……この部屋で初めて抱かれた夜から、ずっと。……ほら、熱いでしょう。……触って、確かめて？" },
    { id: "c172", r18: true, name: "", text: "乳房を掌で包むと、凛は小さく身を震わせた。硬く尖った先端と、指の腹に伝わる早い鼓動。彼女の吐息が熱い。" },
    { id: "c173", r18: true, name: "凛", text: "あぁっ……悠太……深い……奥まで、届いてる……最後の夜なのに、もっとあなたが欲しい……" },
    { id: "c174", r18: true, name: "", text: "濡れそぼった秘部に、ゆっくりと腰を沈める。凛は俺の背中にしがみつき、思い出を惜しむように小さく声を上げた。" },
    { id: "c175", r18: true, name: "凛", text: "もっと……もっと激しく……この部屋の思い出ごと、わたしを連れて行って……ねえ、もっと奥まで……" },
    { id: "c176", r18: true, name: "", text: "凛は夢中で腰を振り続けた。膣壁がうねるように絡みつき、結合部から溢れた愛液が太ももを伝う。俺は彼女の腰を掴み、下から深く突き上げた。" },
    { id: "c177", r18: true, name: "凛", text: "中に出して……ねえ、悠太……あなたの愛を、もっとちょうだい……お腹のこの子と、三人で……家族の愛で、いっぱいにして……！" },
    { id: "c178", r18: true, name: "", text: "最奥深くで射精。凛は受け止めるように腰を寄せ、注がれる熱に、名残惜しそうに小さく震えた。" },
    { id: "c179", r18: true, name: "凛", text: "あぁ……いっぱい……ねえ悠太、新しい部屋では、子供部屋も作るの。……壁紙は、明るい色がいいわね。……この子と暮らす日が、待ち遠しいの。" },
    { id: "c180", r18: true, name: "", text: "凛は俺の腕の中で、やがて小さな寝息を立て始めた。段ボールの隙間から、月明かりがそっと差し込んでいた。", jump: "c201" },
    { id: "c181", bg: "lab", name: "", text: "――翌朝。凛さんは研究室の隅で、コーヒーを淹れていた。眼鏡の奥の瞳が、朝の光に少しだけ潤んでいる。" },
    { id: "c182", face: "smile", name: "凛", text: "おはよう、悠太。……ふふ、昨日の夜は、よく眠れた？　わたしは、なんだか全然眠れなくて。" },
    { id: "c183", name: "悠太", text: "凛さんこそ、目の下にクマが……。……でも、なんだか嬉しそうですね。" },
    { id: "c184", name: "凛", text: "バレた？　……まあね。今日から、わたしはあなたの彼女。……研究室でも、堂々としていいのよ。" },
    { id: "c185", name: "", text: "差し出されたコーヒーは、少しだけ苦め。凛さんの淹れ方は、いつも計算通りで、でも少しだけ優しい。" },
    { id: "c186", name: "凛", text: "ねえ悠太、今日の午後、学会の打ち合わせがあるの。……よかったら、付き合ってくれない？　資料の整理、手伝ってほしいの。" },
    { id: "c187", name: "悠太", text: "もちろんです。……凛さんの発表、絶対に成功させましょう。" },
    { id: "c188", face: "smile", name: "凛", text: "ありがとう。……ふふ、彼氏ができると、学会の準備まで楽しくなるのね。" },
    { id: "c189", name: "", text: "モニタの前で並んで座る。凛さんの肩が、時折俺の肩に触れて、そのたびに彼女は少しだけ微笑んだ。" },
    { id: "c190", name: "凛", text: "ねえ悠太、わたしの夢、知ってる？　……いつか、自分の研究室を持つの。そこで、悠太と一緒に研究するのよ。" },
    { id: "c191", name: "悠太", text: "凛さんの研究室ですか。……それ、素敵ですね。俺も、凛さんの隣で働きたいです。" },
    { id: "c192", face: "smile", name: "凛", text: "ふふ、じゃあ約束ね。……その日まで、わたしは頑張るわ。悠太も、ね。" },
    { id: "c193", name: "", text: "コーヒーをおかわりして、二人でデータを眺める。数字の羅列の中に、未来の設計図が見える気がした。" },
    { id: "c194", name: "凛", text: "ねえ悠太、昼になったら学食に行こう。……今日は、わたしのおごり。恋人になった記念よ。" },
    { id: "c195", name: "悠太", text: "いいんですか？　……じゃあ、遠慮なくいただきます。" },
    { id: "c196", face: "smile", name: "凛", text: "ふふ、いいのよ。……あ、そうだ。今日の夜も、研究室に残る？　……一緒にいたいの。" },
    { id: "c197", name: "悠太", text: "もちろんです。……凛さんと一緒なら、深夜の研究室も悪くないです。" },
    { id: "c198", name: "", text: "凛さんは眼鏡を直し、少しだけ照れたように笑った。朝の研究室に、穏やかな時間が流れていた。" },
    { id: "c199", name: "凛", text: "さ、仕事に戻りましょう。……でもね悠太、今日から、わたしの隣はあなたの席よ。" },
    { id: "c200", name: "", text: "――研究室の朝。二人の新しい日常が、静かに始まっていた。", jump: "c65" },
    { id: "c201", bg: "room", r18: true, name: "", text: "――新居に引っ越した、最初の夜。凛はまだ段ボールだらけの部屋で、俺の腕に頬を寄せた。眼鏡の奥の瞳が、少しだけ潤んでいる。" },
    { id: "c202", face: "smile", r18: true, name: "凛", text: "ねえ悠太……ついに、ここが私たちの部屋よ。……ふふ、まだ散らかってるけど……でも、ほんとに、私たちの部屋。" },
    { id: "c203", r18: true, name: "悠太", text: "凛さん……ついに、ですね。……ここから、俺たちの新しい生活が始まるんですね。" },
    { id: "c204", r18: true, name: "", text: "凛は段ボールの山を眺め、俺の胸に頬を寄せた。新しい部屋の静けさの中、二人の鼓動が重なった。" },
    { id: "c205", r18: true, name: "凛", text: "ねえ、今日は……この部屋での、最初の夜よ。……わたしを、抱いて？　……新しい部屋の、最初の思い出にしたいの。" },
    { id: "c206", r18: true, name: "", text: "頷くと、凛は俺の首に腕を回し、そっと唇を重ねてきた。新しい家具の木の匂いと、少しの緊張。" },
    { id: "c207", face: "pleasure", r18: true, name: "凛", text: "んっ……悠太……ここが、私たちの部屋よ……ねえ、眼鏡、外して……今夜は、新しいベッドで、あなたの恋人よ。" },
    { id: "c208", r18: true, name: "", text: "組み立てたばかりのベッドに横たわり、凛は自ら俺の服を脱がせていく。新しいシーツの、糊の利いた匂いがした。" },
    { id: "c209", r18: true, name: "凛", text: "ねえ、見て……新しい部屋でも、わたしの体はあなたに正直なの。……ほら、ここ、もう熱くなってる。……ねえ悠太、触って……確かめて？" },
    { id: "c210", r18: true, name: "", text: "掌で乳房をすくい上げると、凛は甘く高い声を漏らした。指先に吸い付くように尖った先端と、熱い吐息。" },
    { id: "c211", r18: true, name: "凛", text: "あぁっ……悠太……深い……新しい部屋でも、奥まで届くのね……ねえ、もう……もっと……" },
    { id: "c212", r18: true, name: "", text: "潤みに満ちた秘部へ、ゆっくりと腰を進める。凛は新しいシーツを握りしめ、歓喜の声を上げた。" },
    { id: "c213", r18: true, name: "凛", text: "もっと……もっと激しく……新しい生活の最初の夜なの。……あなたに、全部刻んでほしいの……ねえ、もっと奥まで……" },
    { id: "c214", r18: true, name: "", text: "腰を振る凛の動きに、新しいベッドが小さく軋んだ。膣壁がうねるように絡みつき、溢れた愛液が太ももを伝う。俺は彼女の腰を掴み、下から突き上げた。" },
    { id: "c215", r18: true, name: "凛", text: "中に出して……ねえ、悠太……わたしの中に、あなたの愛をちょうだい……この部屋で、三人の暮らしを始めるの……！" },
    { id: "c216", r18: true, name: "", text: "深く、深くで射精。凛は受け止めるように腰を沈め、注がれる熱に幸福そうに震えた。" },
    { id: "c217", r18: true, name: "凛", text: "あぁ……いっぱい……ねえ悠太、子供部屋は窓のそばにするの。……わたしの書斎も決めたわ。研究も、この子も諦めないって、この部屋で証明するの。" },
    { id: "c218", r18: true, name: "", text: "凛は俺の胸に顔を埋め、やがて静かな寝息を立て始めた。開梱途中の段ボールの隙間から差し込む月明かりが、新しい部屋をそっと照らしていた。", jump: "c239" },
    { id: "c219", bg: "lab", name: "", text: "――研究室の深夜。作業の手を止め、凛さんは小さく伸びをした。肩に手を置くと、思ったより細く、温かい。研究室の蛍光灯の下、モニタの光が静かに揺れる。" },
    { id: "c220", name: "凛", text: "ふぅ……ねえ悠太、ちょっと休憩。……学会発表のスライド、もう一度だけ、見てくれない？　……練習、付き合って。" },
    { id: "c221", name: "悠太", text: "もちろんです。……凛さん、今日はもう何時間もぶっ通しですよ。……肩、凝ってませんか？" },
    { id: "c222", name: "", text: "凛さんは眼鏡を外し、目頭を軽く押さえた。深夜の研究室に、サーバーのファンの音だけが響いている。" },
    { id: "c223", name: "凛", text: "……うん、少しだけね。……でも、発表は明日なの。……あと少しだけ、頑張るわ。" },
    { id: "c224", name: "悠太", text: "分かりました。……じゃあ、練習の前にコーヒーを淹れますね。……凛さん、少しだけ目を閉じててください。" },
    { id: "c225", name: "", text: "凛さんは笑いながら、研究室の隅の小さなコーヒーメーカーに目をやった。豆を挽く音が、静かな深夜に響く。" },
    { id: "c226", face: "smile", name: "凛", text: "……ありがとう。……ねえ悠太、コーヒーができたら、スライドの最終チェックよ。……誤字がないか、見てちょうだい。" },
    { id: "c227", name: "悠太", text: "了解です。……スライド、開きますね。……うん、図は綺麗です。……あ、ここ、単位の表記が少しだけ違いますよ。" },
    { id: "c228", name: "", text: "凛さんは身を乗り出し、モニタを覗き込んだ。眼鏡の奥の瞳が、真剣に光っている。" },
    { id: "c229", face: "smile", name: "凛", text: "……ほんとだ。……よく気づいたわね、悠太。……さすが、わたしの助手。……ふふ、直すわ。" },
    { id: "c230", name: "悠太", text: "助手、ですか。……光栄です。……凛さん、発表の練習、始めますか？　……俺、聴衆役をやりますよ。" },
    { id: "c231", name: "", text: "凛さんは深呼吸をして、スライドの一枚目を開いた。声は少しだけ震えているけれど、芯は通っている。" },
    { id: "c232", name: "凛", text: "……皆さん、おはようございます。……本日は、私たちの研究について発表します。……ねえ、どう？　……声、震えてない？" },
    { id: "c233", name: "悠太", text: "大丈夫です。……すごく、いい声ですよ。……凛さんの研究への情熱、ちゃんと伝わってきます。" },
    { id: "c234", name: "", text: "凛さんは照れたように笑い、スライドを進めた。練習を重ねるたび、声は少しずつ力強くなっていく。" },
    { id: "c235", face: "smile", name: "凛", text: "……ありがとう、悠太。……ねえ、学会が終わったらさ。……二人で、どこかへ旅行に行かない？　……温泉とか。" },
    { id: "c236", name: "悠太", text: "旅行、ですか。……いいですね。……凛さん、学会が終わったら、ゆっくり休んでくださいね。" },
    { id: "c237", name: "", text: "凛さんはコーヒーを一口飲み、モニタの前で小さく頷いた。深夜の研究室に、二人分の湯気がゆっくりと立ちのぼる。" },
    { id: "c238", name: "", text: "――練習は、もう少しだけ続いた。学会の朝が来るまで、凛さんの隣には、ずっと俺がいた。", jump: "c43" },
    { id: "c239", bg: "room", r18: true, name: "", text: "――子供部屋の壁紙を貼った夜。凛は脚立に乗り、星柄の壁紙を丁寧に貼っていた。新居の小さな部屋に、糊の匂いと、二人の笑い声が広がる。" },
    { id: "c240", face: "smile", r18: true, name: "凛", text: "ねえ悠太……見て。……星柄の壁紙、貼れたわよ。……この子が生まれたら、この部屋で眠るの。……ほら、星が、きらきらしてる。" },
    { id: "c241", r18: true, name: "悠太", text: "凛さん……ほんとに、綺麗ですね。……星柄の壁紙、この子、きっと気に入りますよ。……俺も、手伝いますよ。" },
    { id: "c242", r18: true, name: "", text: "凛は脚立からそっと降り、俺の胸に頬を寄せた。お腹の子と三人でいるような、静かな鼓動だった。" },
    { id: "c243", r18: true, name: "凛", text: "ねえ、今日は……この部屋での、最初の夜よ。……わたしを、抱いて？　……子供部屋が、できた記念にしたいの。" },
    { id: "c244", r18: true, name: "", text: "頷くと、凛は俺の首に腕を回し、そっと唇を重ねてきた。星柄の壁紙と、新しいカーテンの匂いと、少しの緊張。" },
    { id: "c245", face: "pleasure", r18: true, name: "凛", text: "んっ……悠太……眼鏡、外して……今夜は、そっとね。……この子も、お腹で聞いてるかもしれないから。" },
    { id: "c246", r18: true, name: "", text: "ベッドに横たわり、凛は大きくなったお腹を撫でてから、俺の服を脱がせていく。星柄の壁紙が月明かりに浮かんでいた。" },
    { id: "c247", r18: true, name: "凛", text: "ねえ、見て……こんなにお腹が大きくなっても、わたしは、あなたのものよ。……ほら、ここ、熱くなってる。……母になるわたしも、女として確かめて？" },
    { id: "c248", r18: true, name: "", text: "張りつめた乳房にそっと掌を添えると、凛は甘い声を漏らした。先端は敏感に尖り、彼女の吐息が熱い。" },
    { id: "c249", r18: true, name: "凛", text: "あぁ……んっ……悠太……深い……この子にも、あなたのあたたかさ、届いてるかしら……もっと、そっと深く……" },
    { id: "c250", r18: true, name: "", text: "潤んだ秘部へ、お腹を庇うようにゆっくりと腰を進める。凛は俺の手に自分の手を重ね、静かに声を上げた。" },
    { id: "c251", r18: true, name: "凛", text: "もっと……もっと、あなたを感じたい……怖くないの、あなたとなら。……ねえ、奥まで……三人で、繋がっていたいの……" },
    { id: "c252", r18: true, name: "", text: "凛はゆっくりと、確かめるように腰を揺らした。膣壁が優しく絡みつき、溢れた愛液が太ももを伝う。俺は彼女の腰を支え、下から静かに突き上げた。" },
    { id: "c253", r18: true, name: "凛", text: "中に出して……ねえ、悠太……あなたの愛を、全部ちょうだい……もうすぐ会えるこの子に、パパとママの愛を届けて……！" },
    { id: "c254", r18: true, name: "", text: "最奥で射精。凛はお腹を庇いながら腰を寄せ、注がれる熱に、安堵するように身を震わせた。" },
    { id: "c255", r18: true, name: "凛", text: "あぁ……いっぱい……ねえ悠太、星柄の壁紙、よかったわね。……もうすぐ、この部屋に小さな寝息が増えるの。……わたし、ちゃんと母になれるかしら。" },
    { id: "c256", r18: true, name: "", text: "凛は俺の腕の中で、やがて穏やかな寝息を立て始めた。星柄の壁紙が、月明かりにそっと白く浮かんでいた。", jump: "c81" },
    { id: "c257", branch: { flag: "said", min: 1, then: "c258", else: "c22" } },
    { id: "c258", face: "shy", name: "凛", text: "……ねえ、悠太。あなたが先に言ってくれて、本当によかった。……わたし一人じゃ、あの言葉、最後まで言えなかったかもしれないから。", jump: "c22" }
  ]
},
{
  id: "yuna",
  title: "閉館後の図書室",
  heroine: "優奈（25歳）",
  desc: "市立図書館の司書・優奈と、閉館後の静かな書庫で過ごす時間。雨宿りの夜、二人の秘密が始まる。",
  cover: "assets/yuna_cover.webp",
  r18: true,
  images: { library: "assets/yuna_library.svg", stacks: "assets/yuna_stacks.svg", room: "assets/yuna_room.svg", char: "assets/yuna_char.webp" },
  scenes: [
    { id: "d01", bg: "library", name: "", text: "市立図書館、閉館30分前。返却本の山を片付けながら、俺はカウンターの優奈さんをちらりと見た。\n週3で通う理由は、半分が本で、半分が彼女だった。" },
    { id: "d02", face: "smile", char: true, name: "優奈", text: "悠太さん、今日も遅くまでお疲れさま。……あら、その本、背表紙が傷んでるわね。よかったら、閉館後に修理を手伝ってくれない？" },
    { id: "d03", name: "悠太", text: "もちろんです。本のことなら何でも手伝います。……優奈さんと残れるなら、なおさら。" },
    { id: "d04", face: "smile", name: "優奈", text: "ふふ、口が上手いのね。じゃあお願いしようかしら。書庫の奥、行ってみましょう。" },
    { id: "d05", bg: "stacks", name: "", text: "閉館後の書庫は、二人だけの世界だった。本の匂いと静寂。優奈さんの手際のよさに習って、古い本の背を直していく。", jump: "d39" },
    { id: "d06", face: "smile", char: true, name: "優奈", text: "本ってね、大事に直せば何十年でも生きるの。人も、きっと同じよね。……悠太さんは、直したいもの、ある？" },
    { id: "d07", choice: [
      { text: "「優奈さんとの距離を、縮めたいです」", jump: "d08", set: { love: 1 } },
      { text: "「特にないです」と無難に答える", jump: "d09", set: { love: 0 } }
    ] },
    { id: "d08", face: "smile", name: "優奈", text: "……あら。ふふ、勇気があるのね。……わたしもね、最近、あなたの来る日が待ち遠しいの。", jump: "d10" },
    { id: "d09", name: "優奈", text: "そう。……じゃあ、今日はここまでにしましょう。雨、降ってきちゃったみたいだけど、大丈夫？", jump: "d15" },
    { id: "d10", name: "", text: "修理を終えた頃、外は激しい雨。優奈さんは窓を見て、小さく溜め息をついた。" },
    { id: "d11", face: "shy", char: true, name: "優奈", text: "困ったわ、傘が一本だけなの。……ねえ悠太さん。今日はわたしの家に寄っていかない？　駅の反対側で遠回りだけど、夕飯も作るわ。" },
    { id: "d12", choice: [
      { text: "「行きます、ぜひ」と答える", jump: "d13", set: { love: 2 } },
      { text: "「申し訳ないので」と辞退する", jump: "d15", set: { love: 0 } }
    ] },
    { id: "d13", bg: "room", name: "", text: "優奈さんの部屋は、本と植物に囲まれた穏やかな空間だった。手料理のパスタを二人で食べ、雨音を聞きながら他愛ない話に笑い合う。" },
    { id: "d14", face: "shy", char: true, name: "優奈", text: "ねえ悠太さん。……わたしのこと、どう思ってるの？　年上の司書なんて、退屈じゃない？" },
    { id: "d15", branch: { flag: "love", min: 2, then: "d16", else: "d20" } },
    { id: "d16", name: "悠太", text: "退屈なんてとんでもない。優奈さんの声も、仕草も、本を選ぶところも、全部好きです。――俺と、付き合ってください。" },
    { id: "d17", face: "smile", name: "優奈", text: "……！　悠太さん……。わたしでいいの？　……ふふ、ありがとう。わたしも、ずっとあなたが気になっていたの。" },
    { id: "d18", name: "", text: "優奈さんは少し照れたように笑い、俺の手を両手で包んだ。その温かさに、長く通った図書館の日々が報われた気がした。" },
    { id: "d19", jump: "d21" },
    { id: "d20", bgm: "calm", face: "smile", bg: "library", char: true, name: "優奈", text: "今日は手伝ってくれてありがとう。……また本を借りに来てね、悠太さん。\n【NORMAL END ― 閉館後の図書室】", end: true },
    { id: "d21", face: "love", r18: true, name: "優奈", text: "じゃあ、今夜は帰さないわ。……わたしの本当の顔、悠太さんだけに教えてあげる。" },
    { id: "d22", r18: true, name: "", text: "優奈さんは髪を解き、いつもの凛とした司書の顔から、甘く蕩けた表情へと変わっていく。誘うように手が伸び、俺を引き寄せた。重ねた唇は深く、舌を絡め合うたびに吐息が熱くなる。" },
    { id: "d23", face: "pleasure", r18: true, name: "優奈", text: "んっ……悠太さん、熱い……。わたし、年上なのに、こんなにドキドキしてる。……全部、脱がせて。あなたの手で、わたしをほどいて。" },
    { id: "d24x", r18: true, name: "", text: "ワンピースのファスナーを下ろすと、レースの下着に包まれた豊かな体が現れた。大きな乳房を掌で揉み、乳首を舌で転がすと、優奈さんは喉を反らせて甘い声を零す。" },
    { id: "d25x", r18: true, name: "優奈", text: "あぁん……悠太さん、上手……。図書館では、こんな声、出せないのに……あなたにだけは、全部聞かせてあげる。" },
    { id: "d26x", r18: true, name: "", text: "下着を脱がせ、秘部に指を這わせる。愛液でとろとろに濡れた陰唇を割り開き、中を掻くように指を動かすと、優奈さんの腰が淫らに揺れた。クリトリスを摘まむたび、大きな体が小刻みに震える。" },
    { id: "d27x", face: "ecstasy", r18: true, name: "優奈", text: "あっ、あぁっ……！　だめ、そこ弱いの……！　悠太さん、わたし、もう……イッちゃう、イッ……あああっ……！！" },
    { id: "d28x", r18: true, name: "", text: "絶頂に震える優奈さんを抱き寄せ、今度は俺のものを彼女の手に握らせる。優奈さんは蕩けた瞳のまま、奉仕するように口に含んできた。舌の絡む感触と、吸い付くような口内の熱に、思わず声が漏れる。" },
    { id: "d29x", face: "pleasure", r18: true, name: "優奈", text: "んっ、んんっ……悠太さんの、熱くて大きい……。ふふ、どう？　わたしの口、気持ちいい？　……もう限界って顔してる。ねえ、早くわたしの中に来て。" },
    { id: "d30x", r18: true, name: "", text: "ベッドに押し倒し、脚を抱え上げて一気に挿入する。熟れた膣は待ちかねたように締め付け、優奈さんは背を反らせて嬌声を上げた。深く腰を落とすたび、接合部から濡れた音が響く。" },
    { id: "d31x", face: "pleasure", r18: true, name: "優奈", text: "あぁん、あぁっ……！　悠太さん、深い、すごい……！　わたしの中、全部あなたでいっぱい……気持ちいい、気持ちよすぎるぅ……" },
    { id: "d32x", r18: true, name: "", text: "大きな乳房を掴んで揉みながら、激しく腰を打ち付ける。優奈さんは枕を掴み、何度も絶頂を迎えながら乱れた。体位を変え、騎乗位で自ら腰を振る姿は、いつもの司書からは想像もできないほど淫らだった。" },
    { id: "d33x", face: "pleasure", r18: true, name: "優奈", text: "あんっ、あんっ……！　見て、悠太さん……わたし、自分から腰振ってる……あなたの彼女は、こんなにえっちなんですよ……！" },
    { id: "d34x", r18: true, name: "", text: "再び正常位に戻り、最奥を突き続ける。優奈さんは脚を俺の背に絡め、耳元で甘く囁いた。" },
    { id: "d35x", r18: true, name: "優奈", text: "悠太さん……中に出して、ください……わたし、あなたの赤ちゃんが欲しいの。年上彼女からの、一生のお願い……わたしのお腹、いっぱいにして……！" },
    { id: "d36x", r18: true, name: "", text: "最奥深く腰を沈め、熱い精液を注ぎ込む。優奈さんは歓喜に目を潤ませ、注がれるたび体を震わせながら、全てを子宮で受け止めるように腰を寄せ続けた。" },
    { id: "d37x", face: "smile", r18: true, name: "優奈", text: "あぁ……出てる、いっぱい出てる……わたしの中が、悠太さんで満ちていく……。ふふ、幸せ。……ねえ、今夜は何度でも付き合うわ。彼女を満足させるのは、彼氏の役目でしょ？", jump: "d50" },
    { id: "d38x", r18: true, name: "", text: "夜が更けるまで、二人は幾度も愛を囁き合った。翌朝、図書館のカウンターで交わす視線は、昨日までとは少しだけ違っていた。" },
    { id: "d27", face: "smile", bg: "room", name: "優奈", text: "おはよう、悠太さん。……ふふ、これからは図書館でも家でも、わたしの特等席はあなたのそばね。", jump: "d179" },
    { id: "d39", bg: "stacks", name: "", text: "書庫の最奥、普段は立ち入り禁止の貴重書棚。優奈さんは指で背表紙をなぞり、静かに微笑んだ。", jump: "d217" },
    { id: "d40", char: true, name: "優奈", text: "ここにあるのはね、百年以上前の本たち。触れるだけで、前の持ち主の人生に触れる気がするの。……悠太さんにも、そういう宝物、ある？" },
    { id: "d41", name: "悠太", text: "……あります。この図書館で過ごした時間、ですかね。受験も、就活も、ここで乗り越えてきたので。" },
    { id: "d42", face: "smile", name: "優奈", text: "ふふ、嬉しいこと言うのね。……実はわたし、あなたの貸出カードの記録、覚えてるの。最初は漫画ばかりだったのに、だんだん難しい本に挑戦するようになって。成長を見てるみたいで、楽しかった。" },
    { id: "d43", name: "", text: "優奈さんの言葉に、胸が温かくなる。見守られていたのだ、ずっと。カウンター越しのあの微笑みは、本物だった。", jump: "d142" },
    { id: "d44", name: "優奈", text: "さ、修理に戻りましょう。……手、貸して。糊の付け方、教えてあげる。", jump: "d06" },
    { id: "d50", r18: true, name: "", text: "優奈さんの言葉通り、夜はまだ続く。シャワーから戻った彼女は、タオル一枚の姿で俺をベッドに誘った。年上彼女の余裕のある微笑みに、再び体が熱くなる。" },
    { id: "d51", face: "love", r18: true, name: "優奈", text: "今度は、わたしのお気に入りの体勢でしよっか。……悠太さん、座って。わたしが、後ろから抱きしめてあげる。" },
    { id: "d52", r18: true, name: "", text: "背後から回された腕が、胸板を撫で、やがて下へと降りていく。耳元で囁かれる甘い声と、柔らかな乳房の感触が背中に押し付けられた。" },
    { id: "d53", face: "pleasure", r18: true, name: "優奈", text: "ふふ、もう硬くなってる。……わたしの手、気持ちいい？　今夜はたっぷり可愛がってあげる。……ねえ、後ろから入れて。わたしの奥、あなたでいっぱいにして。" },
    { id: "d54", r18: true, name: "", text: "向きを変え、後ろから深く貫く。優奈さんは枕に顔を埋め、大きな尻を自ら寄せてきた。熟れた膣は吸い付くように締まり、抽送のたびに水音が響く。" },
    { id: "d55", r18: true, name: "優奈", text: "あぁん、あぁっ……！　悠太さん、深い、すごい……！　後ろからだと、奥の奥まで届く……わたし、もうとろけちゃう……" },
    { id: "d56", r18: true, name: "", text: "乳房を後ろから揉み、乳首を弄びながら突き上げると、優奈さんは何度も絶頂した。抱き合う正常位に移り、脚を肩に担がせて最奥を攻める。" },
    { id: "d57", face: "pleasure", r18: true, name: "優奈", text: "あんっ、あんっ、あぁ……！　悠太さん、見て……わたし、こんな顔してる……司書の顔じゃない、あなたの彼女の顔……もっと、めちゃくちゃにしてぇ……" },
    { id: "d58", r18: true, name: "", text: "優奈さんは蕩けた表情で俺を求め、膣壁は痙攣するように締め付けてくる。限界が近づくと、彼女は両脚で俺の腰を固くロックした。" },
    { id: "d59", r18: true, name: "優奈", text: "中よ、また中で出して……！　二回目も、わたしのお腹いっぱいに……あなたの赤ちゃん、本当に欲しいの……だから、逃がさない……！" },
    { id: "d60", r18: true, name: "", text: "最奥で二度目の射精。優奈さんは子宮で受け止めるように腰を落とし、注がれる熱に潤んだ瞳で微笑んだ。溢れた白濁がシーツに地図を描く。" },
    { id: "d61", face: "smile", r18: true, name: "優奈", text: "あぁ……いっぱい……二回も、ありがとう。わたし、もう悠太さんなしの夜は眠れないかも。……これからも、閉館後の秘密、続けましょうね。", jump: "d38x" },
    { id: "d62", bg: "library", name: "", text: "――数週間後。閉館後の書庫は、二人だけの逢瀬の場所になった。ある夜、優奈さんが真剣な顔で切り出す。", jump: "d104" },
    { id: "d63", face: "serious", char: true, name: "優奈", text: "悠太さん。……わたし、最近、生理が遅れてて。体も、なんだか熱っぽいの。心当たりが、ありすぎるわよね。" },
    { id: "d64", name: "悠太", text: "……！　優奈さん、それって……。俺、責任取ります。いえ、取らせてください。優奈さんと、家族になりたい。" },
    { id: "d65", face: "smile", name: "優奈", text: "……ふふ、ありがとう。まだ検査はしてないの。今夜、最後の確認をしてから、明日一緒に病院に行きましょう。……だから今夜は、特別な夜にしましょうね。" },
    { id: "d66", bg: "room", name: "", text: "優奈さんの部屋。手料理の後、二人は自然にベッドへ。年上彼女の穏やかで深い愛情が、夜を満たしていく。" },
    { id: "d67", face: "love", r18: true, name: "優奈", text: "悠太さん。今夜は、わたしのお腹に、本当に新しい命が宿る夜かもしれない。……だから、たっぷり愛して。あなたの愛で、わたしを満たして。" },
    { id: "d68", r18: true, name: "", text: "深いキスを交わし、優奈さんの大きな乳房を揉みほぐす。乳首を舌で転がすと、彼女は甘く喘ぎながら俺の頭を抱き寄せた。" },
    { id: "d69", r18: true, name: "優奈", text: "あぁん……悠太さん、優しい……。わたしの体、全部あなたに開かれてる。下も、触って。もう、とろとろに溶けてるから……" },
    { id: "d70", r18: true, name: "", text: "秘部へ指を沈めると、熱い内壁が吸い付く。クリトリスを撫で、内側を掻くように動かすと、優奈さんは大きな体を震わせて絶頂を迎えた。" },
    { id: "d71", face: "ecstasy", r18: true, name: "優奈", text: "あぁっ……！　悠太さん、もう、だめ……イッちゃった……。ねえ、早く……早くあなたを感じたい。わたしの中に、来て。" },
    { id: "d72", r18: true, name: "", text: "脚を抱え上げ、深く挿入する。熟れた膣は待ちかねたように締め付け、優奈さんは背を反らせて嬌声を上げた。密着したまま、ゆっくりと、しかし深く腰を落としていく。" },
    { id: "d73", face: "pleasure", r18: true, name: "優奈", text: "あぁん、あぁっ……！　悠太さん、深い……！　わたしの奥、あなたでいっぱい……気持ちいい、幸せすぎて涙が出ちゃう……" },
    { id: "d74", r18: true, name: "", text: "体位を変え、優奈さんが跨って腰を振る。大きな乳房が目の前で揺れ、膣壁は強く締め付けてくる。何度も絶頂を繰り返しながら、彼女は俺を求め続けた。" },
    { id: "d75", face: "pleasure", r18: true, name: "優奈", text: "あんっ、あんっ……！　見て、悠太さん……わたし、年上なのにこんなに乱れて……あなたの彼女は、あなたに夢中なの……もっと、もっとぉ……！" },
    { id: "d76", r18: true, name: "", text: "限界が近づくと、優奈さんは両脚で俺の腰をロックし、子宮を最奥へ寄せてきた。潤んだ瞳が、真っ直ぐに俺を見つめる。" },
    { id: "d77", face: "ecstasy", r18: true, name: "優奈", text: "中に出して、悠太さん……！　わたしのお腹に、あなたの赤ちゃんを授けて……！　あぁっ、イク、わたしも……一緒にイキたい……！！" },
    { id: "d78", r18: true, name: "", text: "最奥深くで射精。優奈さんは絶頂と共に受け止め、注がれる熱に幸福そうに微笑んだ。溢れる白濁がシーツに広がり、二人は額を寄せ合う。" },
    { id: "d79", face: "smile", r18: true, name: "優奈", text: "あぁ……いっぱい……きっと今夜、決まったわね。……悠太さん、わたしを選んでくれてありがとう。これからは、閉館後の図書室は、家族の思い出の場所ね。", jump: "d86" },
    { id: "d80", bgm: "love", bg: "library", name: "", text: "――翌年の春。閉館後の図書室で、優奈さんは小さな栞を膝に抱き、百年ものの絵本を開いた。色褪せた表紙の、金色の文字が夕日の名残にきらめく。\n「……『物語は、誰かの心に住むの』。……ねえ栞、聞こえる？　この絵本はね、ママが子供の頃に読んで、パパと出会うきっかけになった本なの」\n最前列の特等席で、俺は二人の声に耳を澄ました。約束通りの一番最初のお客さんは、いつの間にか一人増えていた。閉館後の図書室に、新しい物語のページが、静かにめくれていく。\n【GOOD END ― 閉館後の図書室】", end: true },
    { id: "d81", bg: "library", name: "", text: "――回想：読み聞かせボランティアの日。子供たちに囲まれ、優奈さんは生き生きと絵本を読んでいた。" },
    { id: "d82", face: "smile", char: true, name: "優奈", text: "みんな、今日のお話はどうだった？　……ふふ、ありがとう。また来週、続きを読もうね。……あら悠太くん、来てくれてたの。手伝ってくれる？" },
    { id: "d83", name: "悠太", text: "もちろんです。本の片付け、任せてください。……優奈さん、子供に大人気ですね。" },
    { id: "d84", face: "smile", name: "優奈", text: "子供の笑顔が、この仕事の一番のご褒美なの。……わたしもいつか、自分の子に読んであげたいな。……あ、独り言。忘れて。" },
    { id: "d85", name: "", text: "少し頬を染めて微笑む優奈さん。その願いが叶う日が、きっと来る――そんな予感がした。", jump: "d44" },
    { id: "d86", face: "smile", bg: "room", r18: true, name: "優奈", text: "……ふふ、ありがとう。わたしを選んでくれて。……ねえ悠太さん、今夜は『最後の確認』の夜。明日、病院で答えが出る前に、もう一度だけ愛し合って？" },
    { id: "d87", r18: true, name: "", text: "優奈さんの部屋。本と植物に囲まれた穏やかな空間に、二人分の温もりが満ちていく。彼女は髪を解き、いつもの凛とした司書の顔から、甘く蕩けた表情へと変わった。" },
    { id: "d88", face: "sad", r18: true, name: "優奈", text: "悠太さん。……わたし、実はね、少し怖いの。もし陽性じゃなかったら……なんて、考えちゃう。……でも、あなたが隣にいてくれるなら、どっちでも幸せ。" },
    { id: "d89", r18: true, name: "悠太", text: "……大丈夫です。結果がどうあれ、俺は優奈さんのそばにいます。……今夜は、そんな不安ごと、全部溶かしてあげます。" },
    { id: "d90", face: "love", r18: true, name: "優奈", text: "……ねえ、悠太さん。今夜は、激しくしなくていい。……このまま、抱きしめて。……あなたの鼓動を聞いていると、怖い気持ちが、少しずつ溶けていくの。" },
    { id: "d91", r18: true, name: "", text: "ワンピースのファスナーを下ろし、レースの下着を脱がせていく。露わになった豊かな体に、優奈さんは恥ずかしそうに目を伏せた。でも、逃げようとはしない。" },
    { id: "d92", r18: true, name: "優奈", text: "あぁん……悠太さん、見ないで……なんて、嘘。……見て。わたしの全部、あなたのものなの。……ねえ、胸、触って。もう、張ってるの。" },
    { id: "d93", r18: true, name: "", text: "大きな乳房を掌で包み、乳首を舌先で転がす。優奈さんは喉を反らせ、甘い声を零した。やがて彼女の手が、俺の服のボタンに伸びてくる。" },
    { id: "d94", face: "smile", r18: true, name: "優奈", text: "悠太さんも、脱いで。……ふふ、もうこんなに。わたしのせいだね。……ねえ、わたしの口で、気持ちよくしてあげる。じっとしてて？" },
    { id: "d95", r18: true, name: "", text: "優奈さんは蕩けた瞳のまま、俺のものを口に含んだ。舌の絡む感触と、吸い付くような口内の熱。司書の顔からは想像できない、淫らな奉仕だった。" },
    { id: "d96", face: "pleasure", r18: true, name: "優奈", text: "んっ、んんっ……どう？　わたしの口、気持ちいい？　……もう限界って顔してる。ねえ、早くわたしの中に来て。わたし、もう待ちきれないの。" },
    { id: "d97", r18: true, name: "", text: "ベッドに押し倒し、脚を抱え上げて深く挿入する。熟れた膣は待ちかねたように締め付け、優奈さんは背を反らせて嬌声を上げた。密着したまま、ゆっくりと、しかし深く腰を落としていく。" },
    { id: "d98", face: "pleasure", r18: true, name: "優奈", text: "あぁん、あぁっ……！　悠太さん、深い……！　わたしの中、全部あなたでいっぱい……気持ちいい、幸せすぎて涙が出ちゃう……" },
    { id: "d99", r18: true, name: "", text: "大きな乳房を掴んで揉みながら、激しく腰を打ち付ける。優奈さんは枕を掴み、何度も絶頂を迎えながら乱れた。体位を変え、騎乗位で自ら腰を振る。" },
    { id: "d100", face: "love", r18: true, name: "優奈", text: "……ありがとう、悠太さん。……結果がどうでも、わたしは平気よ。……だって、わたしたちは、もう家族だもの。……ねえ、明日の病院、ずっと手を握っててね。" },
    { id: "d101", r18: true, name: "", text: "再び正常位に戻り、最奥を突き続ける。優奈さんは脚を俺の背に絡め、耳元で甘く囁いた。限界が近づくと、彼女は両脚で俺の腰を固くロックした。" },
    { id: "d102", r18: true, name: "優奈", text: "悠太さん……中に出して、ください……わたし、あなたの赤ちゃんが欲しいの。年上彼女からの、一生のお願い……わたしのお腹、いっぱいにして……！" },
    { id: "d103", r18: true, name: "", text: "最奥深く腰を沈め、熱い精液を注ぎ込む。優奈さんは歓喜に目を潤ませ、注がれるたび体を震わせながら、全てを子宮で受け止めた。――抱き合ったまま、二人は静かに眠りに落ちた。", jump: "d124" },
    { id: "d104", bg: "library", name: "", text: "「……その前に、ね」――優奈さんは、真剣な顔をほぐして、ふっと微笑んだ。「話す前に、今日の出来事を聞いてほしいの。……休日の古本市、行ってきたのよ。」" },
    { id: "d105", name: "優奈", text: "古本市ってね、本好きの天国なの。……段ボールいっぱいの本が、ずらっと並んでいて。……わたし、朝から夕方まで、ずっといたの。" },
    { id: "d106", name: "悠太", text: "……一日中ですか。……優奈さんらしいですね。……で、何か掘り出し物、ありましたか？" },
    { id: "d107", face: "smile", char: true, name: "優奈", text: "ふふ、あったわ。……見て。……百年くらい前の、絵本の初版本。……状態は悪いけど、わたしの宝物よ。" },
    { id: "d108", name: "", text: "優奈さんは、布に包んだ小さな絵本を取り出した。色褪せた表紙には、金色の文字がかすかに残っている。" },
    { id: "d109", name: "優奈", text: "……ねえ悠太さん。この絵本、昔の持ち主の名前が書いてあるの。……『ミチコ』って。……その子も、きっとこの絵本が好きだったのね。" },
    { id: "d110", name: "悠太", text: "……優奈さん、本の持ち主のことまで考えるんですね。……優しいなあ。……本って、そういうふうに生き続けるんですね。" },
    { id: "d111", face: "smile", name: "優奈", text: "……ふふ、そうよ。本ってね、大事に直せば何十年でも生きるの。……人も、きっと同じ。……だからわたし、司書になったの。" },
    { id: "d112", name: "", text: "優奈さんは、絵本をそっと撫でた。書庫の静寂の中で、彼女の声だけが、やわらかく響く。" },
    { id: "d113", name: "優奈", text: "……ねえ悠太さん。……実はね、この絵本、修理したら、読み聞かせボランティアで使いたいの。……子供たちに、百年分の物語を届けたいの。" },
    { id: "d114", name: "悠太", text: "……素敵ですね。……優奈さんなら、きっとできますよ。……俺も手伝います。……修理も、読み聞かせも。" },
    { id: "d115", face: "smile", name: "優奈", text: "……っ！　ありがとう、悠太さん。……ふふ、あなたって、本当に優しいのね。……ねえ、修理、教えてくれる？　……糊の付け方、まだ下手なの。" },
    { id: "d116", name: "", text: "書庫の片隅で、優奈さんは絵本の修理を始めた。糊を塗る手つきは、少しだけ不器用で、でも丁寧だった。" },
    { id: "d117", name: "優奈", text: "……ねえ悠太さん。……今日、古本市でね、もうひとつ、いいことがあったの。……子供がね、わたしの読み聞かせを覚えててくれたの。" },
    { id: "d118", name: "悠太", text: "……すごいじゃないですか。……優奈さんの読み聞かせ、子供たちに大人気ですもんね。……俺も、いつか聞いてみたいです。" },
    { id: "d119", face: "smile", name: "優奈", text: "……ふふ、じゃあ今度、悠太さんのためだけに読んであげる。……ねえ、約束よ。……その代わり、あなたも、わたしの話を聞いてね。" },
    { id: "d120", name: "", text: "優奈さんは、絵本をそっと閉じた。書庫の灯りの下、彼女の横顔は、穏やかで、少しだけ切なかった。" },
    { id: "d121", face: "serious", name: "優奈", text: "……ねえ悠太さん。……今日の話は、ここまで。……ねえ、実はね、あなたに話したいことがあるの。……真剣な話よ。" },
    { id: "d122", name: "悠太", text: "……はい。……優奈さん、どうしたんですか。……俺、ちゃんと聞きますよ。" },
    { id: "d123", face: "smile", name: "優奈", text: "……ふふ、ありがとう。……ねえ、わたしの手を、握っててくれる？　……そう、こうして。……じゃあ、話すわね。", jump: "d63" },
    { id: "d124", bg: "room", r18: true, name: "", text: "――検査の結果が出た夜。優奈さんからの電話は、震える声だった。『悠太さん……陽性、だったわ……』" },
    { id: "d125", face: "love", r18: true, name: "優奈", text: "ねえ、悠太さん……わたし、ほんとに……お母さんになるのね。……ふふ、怖いくらい、幸せ。" },
    { id: "d126", r18: true, name: "悠太", text: "優奈さん……俺、父親になります。……優奈さんと、この子を、絶対に守ります。" },
    { id: "d127", r18: true, name: "", text: "優奈さんは電話越しに、そっと笑った。受話器の向こうで、彼女の涙が、静かに零れている。" },
    { id: "d128", face: "love", r18: true, name: "優奈", text: "ねえ、悠太さん……今夜は、わたしのそばにいて？　……ねえ、抱いて……嬉しさを、確かめたいの。" },
    { id: "d129", r18: true, name: "", text: "頷くと、優奈さんは俺の首に腕を回し、そっと唇を重ねてきた。洗いたての髪のほのかな香りと、少しの緊張。" },
    { id: "d130", face: "pleasure", r18: true, name: "優奈", text: "んっ……悠太さん……優しい……ねえ、もっと、近くに来て……" },
    { id: "d131", r18: true, name: "", text: "ベッドに横たわり、優奈さんは自ら俺の服を脱がせていく。大きな乳房が、月明かりに白く浮かぶ。" },
    { id: "d132", r18: true, name: "優奈", text: "ねえ、見て……わたしの胸、少し張ってきたの。……お腹はまだ平らだけど、ここに、確かにこの子がいるのよ。……ねえ、悠太さん、触って……確かめて？" },
    { id: "d133", r18: true, name: "", text: "乳房を包むように揉むと、優奈さんは甘い声を漏らした。先端はすっかり硬くなり、彼女の吐息が熱い。" },
    { id: "d134", face: "pleasure", r18: true, name: "優奈", text: "あぁっ……悠太さん……気持ちいい……奥、痺れる……ねえ、もう……入れて……" },
    { id: "d135", r18: true, name: "", text: "濡れそぼった秘部に、ゆっくりと腰を沈める。優奈さんは俺の背中にしがみつき、歓喜の声を上げた。" },
    { id: "d136", r18: true, name: "優奈", text: "もっと……もっと深く……わたし、悠太さんのものよ……ねえ、もっと奥まで……" },
    { id: "d137", r18: true, name: "", text: "夢中で腰を振る優奈さん。膣壁がうねるように絡みつき、結合部からは愛液が溢れて太ももを伝う。俺は乳房を揉みながら、下から突き上げた。" },
    { id: "d138", r18: true, name: "優奈", text: "中に出して……ねえ、悠太さん……もう宿っている命に、あなたの愛を重ねて……わたしのお腹、いっぱいの愛で満たして……！" },
    { id: "d139", r18: true, name: "", text: "最奥深く腰を沈め、熱い精液を注ぎ込む。優奈さんは歓喜に目を潤ませ、注がれるたび体を震わせながら、全てを子宮で受け止めた。" },
    { id: "d140", r18: true, name: "優奈", text: "あぁ……温かい……ねえ悠太さん、わたし、絶対に幸せになる。……あなたと、この子と、三人で。" },
    { id: "d141", r18: true, name: "", text: "抱き合ったまま、二人は静かに眠りに落ちた。――閉館後の静かな図書館で始まった恋は、新しい命の物語へとページを進めていく。", jump: "d161" },
    { id: "d142", bg: "stacks", name: "", text: "――閉館後の書庫。優奈さんは古い棚の奥から、一冊の絵本を取り出した。表紙は色褪せ、角が少しだけ擦れている。" },
    { id: "d143", face: "smile", name: "優奈", text: "ねえ悠太さん……これ、見つけたの。……百年くらい前の絵本らしいわ。……誰にも読まれずに、ずっとここに眠ってたの。" },
    { id: "d144", name: "悠太", text: "優奈さん、百年ものの絵本……すごいですね。……俺、こんな古い本、初めて見ました。" },
    { id: "d145", name: "", text: "優奈さんは絵本をそっと開いた。ページをめくるたび、かすかな紙の匂いが立ちのぼる。挿絵は手描きで、どこか温かみがあった。" },
    { id: "d146", face: "smile", name: "優奈", text: "ふふ、ねえ、読んでみる？　……わたし、読み聞かせが得意なの。……子供の頃、図書館でよく読んでたから。" },
    { id: "d147", name: "", text: "優奈さんの声は、書庫の静寂にゆっくりと溶けていった。絵本の物語は、森の奥に住む小さな司書の話だった。" },
    { id: "d148", name: "悠太", text: "……すごい。……優奈さんの読み聞かせ、まるで物語の中にいるみたいです。……声が、すごく綺麗で。" },
    { id: "d149", name: "優奈", text: "でしょ？　……わたしね、いつか自分の読み聞かせの会を開きたいの。……子供たちに、本の楽しさを伝えたいの。" },
    { id: "d150", name: "", text: "優奈さんは絵本を閉じ、少しだけ遠い目をした。閉館後の書庫に、本の匂いと静寂がゆっくりと広がっている。" },
    { id: "d151", face: "smile", name: "優奈", text: "ねえ悠太さん……わたしの夢、笑わない？　……図書館で働きながら、いつか自分の読み聞かせの会を持つなんて、無謀かしら。" },
    { id: "d152", name: "悠太", text: "笑いませんよ。……優奈さんの読み聞かせ、こんなに素敵なんですから。……絶対、子供たちに喜ばれますよ。……俺、見に行きます。" },
    { id: "d153", name: "", text: "優奈さんは頬を染め、嬉しそうに微笑んだ。書庫の薄明かりが、彼女の横顔を柔らかく照らしている。" },
    { id: "d154", face: "serious", name: "優奈", text: "……ありがとう、悠太さん。……ねえ、約束して？　……わたしの読み聞かせの会ができたら、一番最初のお客さんになって。" },
    { id: "d155", name: "悠太", text: "もちろんです。……一番前の席で、聞きますよ。……そのときは、今日の絵本も読んでくださいね。" },
    { id: "d156", face: "smile", name: "優奈", text: "ふふ、了解。……じゃあ、わたしも約束する。……悠太さんの分は、いつも特別な席を用意するからね。" },
    { id: "d157", name: "", text: "絵本を棚に戻し、二人で書庫を出た。閉館後の図書館は静かで、足音だけが、ゆっくりと廊下に響く。" },
    { id: "d158", name: "優奈", text: "ねえ、今日はこのまま帰るの、もったいないわね。……よかったら、カウンターでお茶でも飲まない？　……夜の図書館、静かで好きなの。" },
    { id: "d159", name: "悠太", text: "いいですね。……優奈さんと過ごす閉館後の時間、なんだか特別な気がします。……ほら、窓の外、月が綺麗ですよ。" },
    { id: "d160", name: "", text: "カウンターに並んで座り、しばらく何も言わずに月の光を眺めた。優奈さんの肩が、そっと俺の肩に触れる。……本の匂いと、静かな夜。", jump: "d81" },
    { id: "d161", bg: "room", r18: true, name: "", text: "――妊婦健診の帰りの夜。優奈さんはエコー写真を広げ、俺の部屋で嬉しそうに笑った。写真の中の小さな影が、もう家族の中心だった。" },
    { id: "d162", face: "smile", r18: true, name: "優奈", text: "ねえ、悠太さん……見て。……ここに、この子がいるの。……小さな手が、ちゃんと見えるでしょう？" },
    { id: "d163", r18: true, name: "悠太", text: "ほんとだ……優奈さん、すごいですね。……この子、優奈さんに似て、きっと本が好きになりますよ。" },
    { id: "d164", r18: true, name: "", text: "優奈さんはエコー写真をそっと胸に抱き、俺の肩に頬を寄せた。健診で聞いた小さな心音が、まだ耳の奥に残っている気がした。" },
    { id: "d165", r18: true, name: "優奈", text: "ねえ、悠太さん……今夜は、わたしのそばにいて？　……ねえ、抱いて……この子の鼓動を、確かめたいの。" },
    { id: "d166", r18: true, name: "", text: "頷くと、優奈さんは俺の首に腕を回し、そっと唇を重ねてきた。ほのかな石鹸の香りと、少しの緊張。" },
    { id: "d167", face: "pleasure", r18: true, name: "優奈", text: "んっ……悠太さん……今日の健診でね、この子の心音、聞いたでしょう……？　……あの音みたいに、わたしの鼓動も……速いの……" },
    { id: "d168", r18: true, name: "", text: "ベッドに横たわり、優奈さんは俺のシャツのボタンを一つずつ外していく。枕元に置いたエコー写真が、月明かりにそっと白く浮かんでいた。" },
    { id: "d169", r18: true, name: "優奈", text: "ねえ、見て……お腹、少しだけ膨らんできたの。……写真の中の影が、ここで、ちゃんと育ってるのよ。……ねえ、悠太さん、手を当てて……この子の存在、確かめて？" },
    { id: "d170", r18: true, name: "", text: "膨らみ始めたお腹にそっと手を置くと、優奈さんはくすぐったそうに身をよじり、やがて甘い吐息を漏らした。掌の下の温もりが、確かな命を伝えていた。" },
    { id: "d171", face: "pleasure", r18: true, name: "優奈", text: "あぁっ……悠太さん……気持ちいい……ねえ、この子に聞かれちゃうくらい、わたし、幸せで……もう……入れて……" },
    { id: "d172", r18: true, name: "", text: "優奈さんは俺の手を引いて、自らの秘部へと導いた。指先が触れるなり、彼女の体が小さく震える。――静かに、けれど確かに、腰を沈めていく。" },
    { id: "d173", r18: true, name: "優奈", text: "もっと……もっと深く……この子のいちばん近くまで……ねえ、悠太さん……わたしたち、もう三人家族なのよ……" },
    { id: "d174", r18: true, name: "", text: "優奈さんは両腕を俺の首に回し、額を寄せてきた。穏やかな律動の中で、結合部から愛液が溢れ、シーツに小さな染みを広げていく。" },
    { id: "d175", r18: true, name: "優奈", text: "中に出して……ねえ、悠太さん……もう宿っている命に、あなたの愛を重ねて……この子と、わたしを、いっぱいの愛で満たして……！" },
    { id: "d176", r18: true, name: "", text: "最奥深く腰を沈め、熱い精液を注ぎ込む。優奈さんは目を潤ませながら、注がれるたび小さく頷くように体を震わせ、全てを受け止めた。――その手は、ずっとお腹を守るように添えられていた。" },
    { id: "d177", r18: true, name: "優奈", text: "あぁ……温かい……ねえ悠太さん、この子が生まれたら、百年ものの絵本を読んであげるの。……わたしと、あなたと、この子で。" },
    { id: "d178", r18: true, name: "", text: "抱き合ったまま、二人は静かに眠りに落ちた。エコー写真が、月明かりにそっと白く浮かんでいた。", jump: "d199" },
    { id: "d179", bg: "library", name: "", text: "――翌朝。優奈さんは図書館のカウンターで、朝の本の仕分けをしていた。窓からの光が、彼女の横顔を優しく照らす。" },
    { id: "d180", face: "smile", name: "優奈", text: "おはよう、悠太さん。……ふふ、昨日の夜のこと、覚えてる？　わたしは、もう一生忘れないわ。" },
    { id: "d181", name: "悠太", text: "もちろんです。……優奈さん、朝から本の山ですね。手伝いますよ。" },
    { id: "d182", face: "smile", name: "優奈", text: "ありがとう。……でもね、今日から悠太さんは、わたしの恋人なの。手伝わせるのは、少しだけ申し訳ないわ。" },
    { id: "d183", name: "悠太", text: "恋人だからこそ、手伝いたいんです。……それに、優奈さんのそばにいられるなら、なんでもしますよ。" },
    { id: "d184", face: "smile", name: "優奈", text: "ふふ、口が上手いのね。……じゃあ、この絵本を書庫に戻してちょうだい。百年ものの、大事な一冊よ。" },
    { id: "d185", name: "", text: "受け取った絵本は、表紙が少しだけ色褪せていた。でも、ページをめくると、色鮮やかな絵が広がっている。" },
    { id: "d186", name: "優奈", text: "ねえ悠太さん、この絵本、知ってる？　……わたしが子供の頃、母が読んでくれたの。" },
    { id: "d187", name: "悠太", text: "いえ、初めて見ます。……でも、優奈さんの大事な本だってことは、分かります。" },
    { id: "d188", name: "優奈", text: "そう。……いつかね、この絵本を、わたしの子供にも読んであげたいの。……悠太さんと、一緒に。" },
    { id: "d189", name: "", text: "優奈さんは少しだけ頬を染めて、本をそっと胸に抱いた。朝の図書館に、静かな温もりが広がる。" },
    { id: "d190", name: "悠太", text: "……その日が来るのを、俺も楽しみにしてます。" },
    { id: "d191", face: "smile", name: "優奈", text: "ふふ、ありがとう。……じゃあ、今日の昼休み、一緒にお弁当を食べましょう。わたしが作ってきたの。" },
    { id: "d192", name: "悠太", text: "優奈さんの手作り弁当ですか。……楽しみです。" },
    { id: "d193", name: "優奈", text: "ええ。……それとね、今夜も、閉館後に書庫で会いましょう。……昨日の続き、ね。" },
    { id: "d194", name: "悠太", text: "もちろんです。……優奈さんと一緒なら、書庫の奥も怖くないです。" },
    { id: "d195", face: "smile", name: "優奈", text: "ふふ、怖いわけないでしょう。……ほら、仕分けが終わったわ。開館の時間よ。" },
    { id: "d196", name: "", text: "カウンターに並んで座り、二人で開館の準備をする。優奈さんの指先が、時折俺の手に触れた。" },
    { id: "d197", name: "優奈", text: "ねえ悠太さん、今日から、わたしの特等席はあなたのそば。……図書館でも、家でもね。" },
    { id: "d198", name: "", text: "――朝の図書館。二人の新しい日常が、本の香りと共に始まっていた。", jump: "d62" },
    { id: "d199", bg: "room", r18: true, name: "", text: "――赤ちゃんの名前を決めた夜。優奈さんは名前の本を広げ、俺の部屋で嬉しそうに笑った。開かれたページには、候補の名前がいくつも並んでいる。" },
    { id: "d200", face: "smile", r18: true, name: "優奈", text: "ねえ、悠太さん……見て。……「栞」「陽葵」「結」……ねえ、どれがいいと思う？　……わたしは、栞がいいなって思ってるの。" },
    { id: "d201", r18: true, name: "悠太", text: "栞……いい名前ですね。……本の栞みたいに、この子の人生の、大事なページを挟んであげたいですね。" },
    { id: "d202", r18: true, name: "", text: "優奈さんは名前の本をそっと閉じ、俺の肩に頬を寄せた。――栞。その名を口の中で転がすたび、二人の胸に小さな灯りがともるようだった。" },
    { id: "d203", r18: true, name: "優奈", text: "ねえ、悠太さん……今夜は、わたしのそばにいて？　……ねえ、抱いて……この子の名前が、決まった記念に。" },
    { id: "d204", r18: true, name: "", text: "頷くと、優奈さんは俺の首に腕を回し、そっと唇を重ねてきた。名前の本の紙の匂いと、少しの緊張。" },
    { id: "d205", face: "pleasure", r18: true, name: "優奈", text: "んっ……悠太さん……『栞』って、呼んでみて……？　……この子に名前がついた夜よ……わたし、嬉しくて、体が熱いの……" },
    { id: "d206", r18: true, name: "", text: "ベッドに横たわり、優奈さんは俺の服を脱がせながら、ときどきお腹に手をやって微笑んだ。開いたままの名前の本が、ベッドの端で静かにページを休めていた。" },
    { id: "d207", r18: true, name: "優奈", text: "ねえ、見て……お腹の中で、栞が育ってるの。……『栞』はね、本のページに挟むもの。……この子のページを、わたしたちでめくっていくのよ。……触って……パパの手、教えてあげて？" },
    { id: "d208", r18: true, name: "", text: "丸みを帯びたお腹を撫でると、優奈さんは目を細めて甘い声を漏らした。やがて乳房へ手を移すと、先端はすっかり硬くなり、彼女の吐息が熱を帯びていく。" },
    { id: "d209", face: "pleasure", r18: true, name: "優奈", text: "あぁっ……悠太さん……気持ちいい……栞の名前が決まった夜に、こんなに愛されたら……ねえ、もう……入れて……" },
    { id: "d210", r18: true, name: "", text: "濡れそぼった秘部に、ゆっくりと腰を沈める。優奈さんは俺の背中にしがみつき、『栞……聞いてる？』とお腹に囁いてから、歓喜の声を上げた。" },
    { id: "d211", r18: true, name: "優奈", text: "もっと……もっと深く……ねえ、栞のパパ……わたしを、栞のママにして……もっと奥まで……" },
    { id: "d212", r18: true, name: "", text: "優奈さんは俺の手を取って、自分のお腹の上に重ねたまま腰を揺らした。二人の手の下で、新しい命の物語の最初のページが、静かにめくれていくようだった。" },
    { id: "d213", r18: true, name: "優奈", text: "中に出して……ねえ、悠太さん……栞への、命名の夜の贈りもの……わたしのお腹いっぱいに、パパの愛を注いで……！" },
    { id: "d214", r18: true, name: "", text: "最奥深く腰を沈め、熱い精液を注ぎ込む。優奈さんは歓喜に目を潤ませ、『栞、良かったね』とお腹に囁きながら、全てを子宮で受け止めた。" },
    { id: "d215", r18: true, name: "優奈", text: "あぁ……温かい……ねえ悠太さん、栞が生まれたら、百年ものの絵本を読んであげるの。……わたしと、あなたと、栞で。" },
    { id: "d216", r18: true, name: "", text: "抱き合ったまま、二人は静かに眠りに落ちた。名前の本が、月明かりにそっと白く浮かんでいた。", jump: "d237" },
    { id: "d217", bg: "stacks", name: "", text: "――書庫の最奥、普段は立ち入り禁止の貴重書棚。優奈さんは指で背表紙をなぞり、静かに微笑んだ。閉館後の図書館は、紙の匂いと静寂に満ちている。" },
    { id: "d218", name: "優奈", text: "ねえ、悠太さん……見て。……この絵本、百年以上前のものなの。……表紙は色褪せてるけど、ページは、まだ綺麗なの。" },
    { id: "d219", name: "悠太", text: "百年以上……ですか。……すごいですね。……どんなお話なんですか？　……この絵本。" },
    { id: "d220", name: "", text: "優奈さんは布に包んだ絵本を、そっと取り出した。色褪せた表紙には、金色の文字がかすかに残っている。" },
    { id: "d221", name: "優奈", text: "……森の奥に住む、小さな司書のお話。……本をなくした動物たちに、司書が新しい物語を届けるの。……わたし、子供の頃に読んだの。" },
    { id: "d222", name: "悠太", text: "優奈さんが子供の頃に……ですか。……優奈さん、昔から本が好きだったんですね。" },
    { id: "d223", name: "", text: "優奈さんは絵本をそっと開いた。ページをめくるたび、かすかな紙の匂いが立ちのぼる。挿絵は手描きで、少しだけ色褪せている。" },
    { id: "d224", name: "優奈", text: "……うん。……わたし、小さい頃は、あまり友達がいなくて。……でも、本の中には、いつも誰かがいたの。……だから、司書になったの。" },
    { id: "d225", name: "", text: "優奈さんの声は、書庫の静寂にゆっくりと溶けていった。絵本の物語は、森の奥に住む小さな司書の、優しい日々の記録だった。" },
    { id: "d226", name: "優奈", text: "……ねえ、悠太さん。……この絵本の最後、知ってる？　……司書はね、動物たちに言ったの。「物語は、誰かの心に住むの」って。" },
    { id: "d227", name: "悠太", text: "「物語は、誰かの心に住む」……ですか。……いい言葉ですね。……優奈さんらしい、温かい言葉です。" },
    { id: "d228", name: "", text: "優奈さんは頬を染め、嬉しそうに微笑んだ。書庫の薄明かりが、彼女の横顔を柔らかく照らしている。" },
    { id: "d229", name: "優奈", text: "……ねえ、悠太さん。……この絵本、いつか大勢の子供たちに読んであげたいの。……百年、眠っていた物語を、起こしてあげたいな。" },
    { id: "d230", name: "悠太", text: "きっと喜びますよ。……優奈さんの声で読んでもらえたら、この絵本も、もう一度生き返りますね。" },
    { id: "d231", name: "", text: "優奈さんは絵本をそっと閉じ、布に包み直した。手つきは丁寧で、まるで宝物を扱うように優しい。" },
    { id: "d232", face: "smile", name: "優奈", text: "……ありがとう、悠太さん。……ねえ、もう閉館の時間ね。……書庫の片付け、手伝ってくれる？" },
    { id: "d233", name: "悠太", text: "もちろんです。……優奈さん、絵本、元の棚に戻しますね。……百年ものの絵本、大切にしないと。" },
    { id: "d234", name: "", text: "優奈さんは頷き、貴重書棚の鍵をそっと回した。カチリ、という小さな音が、静かな書庫に響いた。" },
    { id: "d235", name: "", text: "絵本を棚に戻し、二人で書庫を出た。閉館後の図書館は静かで、足音だけが、ゆっくりと廊下に響く。" },
    { id: "d236", name: "", text: "――貴重書棚の絵本は、また百年を眠る。優奈さんの物語は、まだ始まったばかりだった。", jump: "d40" },
    { id: "d237", bg: "room", r18: true, name: "", text: "――産休に入った、初日の夜。優奈さんは図書館の制服を脱ぎ、俺の部屋でほっと息をついた。窓の外では、静かな夜の図書館の灯りが瞬いている。" },
    { id: "d238", face: "smile", r18: true, name: "優奈", text: "ねえ、悠太さん……今日で、産休に入ったの。……図書館のみんなが、花束をくれたの。……ねえ、見て……栞の花束よ。" },
    { id: "d239", r18: true, name: "悠太", text: "栞の花束……綺麗ですね。……優奈さん、図書館のみんなに愛されてますね。……産休、ゆっくり休んでくださいね。" },
    { id: "d240", r18: true, name: "", text: "優奈さんは花束をそっと置き、大きく膨らんだお腹を支えるようにして、俺の肩に頬を寄せた。出産が近い静けさが、二人の間に満ちていた。" },
    { id: "d241", r18: true, name: "優奈", text: "ねえ、悠太さん……今夜は、わたしのそばにいて？　……ねえ、抱いて……産休の初日の、記念に。" },
    { id: "d242", r18: true, name: "", text: "頷くと、優奈さんは俺の首に腕を回し、そっと唇を重ねてきた。窓の外の夜の静けさと、少しの緊張。" },
    { id: "d243", face: "pleasure", r18: true, name: "優奈", text: "んっ……悠太さん……産休に入って、やっと落ち着いたの……ねえ、今夜は急がずに……ゆっくり、愛して……？" },
    { id: "d244", r18: true, name: "", text: "ベッドに横たわり、優奈さんは大きなお腹を庇いながら、そっと俺を引き寄せた。部屋の隅に立てかけた栞の花束が、月明かりに淡く色づいていた。" },
    { id: "d245", r18: true, name: "優奈", text: "ねえ、見て……お腹、こんなに大きくなったの。……栞はもう、いつ生まれてもおかしくないんですって。……ねえ、悠太さん、そっと触って……『もうすぐ会えるね』って、言ってあげて？" },
    { id: "d246", r18: true, name: "", text: "大きなお腹に掌を当てると、中から小さな蹴りが返ってきた。優奈さんは驚いて笑い、やがて目を潤ませて甘い吐息を漏らした。" },
    { id: "d247", face: "pleasure", r18: true, name: "優奈", text: "あぁっ……悠太さん……大丈夫、ゆっくりなら……この子も、パパとママの愛を感じてるの……ねえ、そっと……入れて……" },
    { id: "d248", r18: true, name: "", text: "お腹を庇うように体勢を整え、ゆっくりと腰を沈める。優奈さんは俺の腕にすがり、安堵と歓喜の混じった声を漏らした。" },
    { id: "d249", r18: true, name: "優奈", text: "もっと……ううん、欲張らないで、ゆっくり……ねえ、悠太さん……あと少しで、三人で会えるのよ……その日まで、こうして愛して……" },
    { id: "d250", r18: true, name: "", text: "優奈さんは俺の胸に頬を寄せたまま、小さく腰を揺らした。穏やかで、けれど芯のある動き。お腹の栞も静かに眠っているようだった。" },
    { id: "d251", r18: true, name: "優奈", text: "中に出して……ねえ、悠太さん……出産前、最後の夜かもしれないの……わたしのお腹いっぱいに、あなたの愛を残して……栞への、最初の贈りものに……" },
    { id: "d252", r18: true, name: "", text: "最奥深く腰を沈め、熱い精液を注ぎ込む。優奈さんは穏やかに微笑みながら体を震わせ、全てを受け止めた。――生まれてくる命を、二人の愛で包むように。" },
    { id: "d253", r18: true, name: "優奈", text: "あぁ……温かい……ねえ悠太さん、栞が生まれたら、まず、この部屋で三人で眠るの。……それから、図書室にも連れて行ってあげたいな。" },
    { id: "d254", r18: true, name: "", text: "抱き合ったまま、二人は静かに眠りに落ちた。栞の花束が、月明かりにそっと白く浮かんでいた。", jump: "d80" }
  ]
},
{
  id: "serena",
  title: "セレナの館",
  heroine: "セレナ（26歳）",
  desc: "山間の洋館に暮らす令嬢セレナと、家庭教師として雇われた俺。舞踏会の夜、身分差を超える想いが動き出す。",
  cover: "assets/serena_cover.webp",
  r18: true,
  images: { mansion: "assets/serena_mansion.svg", garden: "assets/serena_garden.svg", room: "assets/serena_room.svg", char: "assets/serena_char.webp" },
  scenes: [
    { id: "e01", bg: "mansion", name: "", text: "山間の洋館、ヴェルディア邸。亡き恩師の紹介で、俺は令嬢の語学の家庭教師として雇われた。\n――相手は、セレナ・ヴェルディア。26歳。気品と、どこか寂しげな瞳を持つ人だった。" },
    { id: "e02", face: "smile", char: true, name: "セレナ", text: "ようこそ、悠太先生。今日からよろしくお願いしますね。……ふふ、そんなに緊張なさらないで。わたしは、あなたの授業を楽しみにしていたのですから。" },
    { id: "e03", name: "悠太", text: "こちらこそ、よろしくお願いします。セレナさんに満足してもらえるよう、全力を尽くします。" },
    { id: "e04", name: "", text: "授業の日々は穏やかに過ぎた。セレナは聡明で、時折見せる少女のような笑顔に、俺はいつしか惹かれていった。", jump: "e39" },
    { id: "e05", face: "smile", bg: "garden", char: true, name: "セレナ", text: "今夜、館で小さな舞踏会を開きます。先生も、ぜひご参加を。……わたしの、最初のダンスの相手になってくださいますか？" },
    { id: "e06", choice: [
      { text: "「光栄です」と手を取る約束をする", jump: "e07", set: { love: 1 } },
      { text: "「身分が違います」と身を引く", jump: "e08", set: { love: 0 } }
    ] },
    { id: "e07", face: "smile", name: "セレナ", text: "……！　本当ですか。ありがとうございます、先生。……今夜が、待ち遠しいです。", jump: "e09" },
    { id: "e08", face: "sad", name: "セレナ", text: "……そう、ですよね。失礼いたしました。先生は、いつも礼儀正しい方ですから。", jump: "e13" },
    { id: "e09", bg: "mansion", name: "", text: "舞踏会の夜。ドレスに身を包んだセレナは、目が眩むほど美しかった。二人で踊るワルツ。彼女の手の温かさが、手袋越しに伝わってくる。" },
    { id: "e10", face: "shy", char: true, name: "セレナ", text: "先生……わたし、この館でずっと一人でした。でもあなたが来てから、毎日が色づいたの。……ねえ先生、今夜は『先生』と呼ぶのを、やめてもいいですか？" },
    { id: "e11", name: "悠太", text: "セレナ。俺も同じ気持ちです。身分なんて関係ない。俺はあなたが好きだ。" },
    { id: "e12", face: "love", name: "セレナ", text: "悠太……！　……嬉しい。わたしも、あなたを愛しています。ずっと、ずっと言いたかった……" },
    { id: "e13", branch: { flag: "love", min: 1, then: "e14", else: "e18" } },
    { id: "e14", bg: "garden", name: "", text: "舞踏会を抜け出し、二人で月下の庭園へ。セレナは俺の腕に寄り添い、離れようとしなかった。" },
    { id: "e15", choice: [
      { text: "「今夜、あなたの部屋へ行ってもいいですか」", jump: "e16", set: { love: 2 } },
      { text: "「おやすみなさい」と紳士的に帰る", jump: "e18", set: { love: 0 } }
    ] },
    { id: "e16", face: "love", name: "セレナ", text: "……はい。わたしの部屋で、もっとあなたとお話ししたい。……いえ、本当は、話だけじゃ終わらせたくないの。", jump: "e19" },
    { id: "e18", bgm: "calm", face: "sleepy", bg: "garden", char: true, name: "セレナ", text: "今夜は素敵な舞踏会でした。……おやすみなさい、先生。また明日の授業で。\n【NORMAL END ― 月下の庭園】", end: true },
    { id: "e19", face: "shy", r18: true, name: "セレナ", text: "悠太……今夜は、わたしをあなたのものにしてください。令嬢としてではなく、一人の女として、全部さらけ出します。わたし、初めてなの……あなたの手で、女にしてください。" },
    { id: "e20", r18: true, name: "", text: "ドレスの紐を解くと、白い肌が月明かりに浮かび上がった。下着姿のセレナは恥じらいに身を震わせながらも、自分から俺の胸に倒れ込んでくる。唇を重ね、舌を絡めると、甘い吐息が漏れた。" },
    { id: "e21", face: "pleasure", r18: true, name: "セレナ", text: "んっ、んんっ……悠太……わたしの胸、触って。あなたのためだけに、こんなに張っているの……全部、あなたのものです。" },
    { id: "e22x", r18: true, name: "", text: "ブラを外し、形のいい大きな乳房を掌で揉みほぐす。乳首は固く尖り、指で転がすたびセレナは小さく喘いだ。舌で舐め、吸い付くと、令嬢の口から我慢できないような甘い声が零れる。" },
    { id: "e23x", r18: true, name: "セレナ", text: "あぁん……悠太、そこ……わたし、体が熱くてたまらないの。……下も、触ってください。わたしがどれだけあなたを欲しがっているか、確かめて……" },
    { id: "e24x", r18: true, name: "", text: "下着の中へ手を滑らせると、秘部は既に愛液で溢れていた。陰唇を割り開き、クリトリスを撫でると、セレナの腰が跳ねる。指を膣内へ沈めると、処女の内壁が固く、熱く、吸い付いてきた。" },
    { id: "e25x", face: "pleasure", r18: true, name: "セレナ", text: "あっ、あぁっ……！　悠太、悠太ぁ……！　わたし、もう……イッてしまいます……あああっ……！！" },
    { id: "e26x", r18: true, name: "", text: "指だけで絶頂を迎え、セレナは荒い息を吐いた。それでも俺を求める瞳は潤んだまま。ベッドに横たわらせ、脚をそっと開くと、彼女は両手で顔を覆いながらも拒まなかった。" },
    { id: "e27x", r18: true, name: "セレナ", text: "来てください、悠太……わたしの初めてを、あなたに捧げます。……優しく、でも全部、わたしの中に入れて。わたしを、あなたの妻にしてください……" },
    { id: "e28x", r18: true, name: "", text: "先端を割り当て、ゆっくりと腰を進める。狭い膣を押し広げ、処女の証を破る感触。セレナは痛みに涙を浮かべながらも、俺の背に腕を回して受け入れ続けた。最奥まで収まった瞬間、二人は深く息を吐く。" },
    { id: "e29x", r18: true, name: "セレナ", text: "うっ……あぁ、繋がった……悠太とわたしが、一つになったのですね……。熱い……わたしの中、全部あなたでいっぱいです……" },
    { id: "e30x", r18: true, name: "", text: "痛みが引くのを待ち、緩やかに抽送を始める。次第にセレナの表情は快感に染まり、内壁は絡みつくように締まってきた。大きな乳房が揺れ、令嬢らしからぬ甘い嬌声が部屋に響く。" },
    { id: "e31x", face: "pleasure", r18: true, name: "セレナ", text: "あんっ、あんっ、あぁ……！　悠太、気持ちいい、気持ちいいです……！　もっと、もっと激しく……わたしを、あなたの色に染めてください……！" },
    { id: "e32x", r18: true, name: "", text: "腰の速度を上げ、深く突き上げる。セレナはシーツを握りしめ、涙目で喘ぎながら何度も絶頂を迎えた。その淫らで美しい姿は、俺だけの特権だった。" },
    { id: "e33x", face: "love", r18: true, name: "セレナ", text: "イグ、またイッてしまいます……！　悠太、愛しています……！　あぁっ、もう、わたしはあなたのものです、一生……！" },
    { id: "e34x", r18: true, name: "", text: "限界を迎えた俺に、セレナは脚を絡めて囁く。月明かりに照らされた顔は、幸福と快感に蕩けていた。" },
    { id: "e35x", r18: true, name: "セレナ", text: "中に出してください、悠太……！　わたしのお腹に、あなたの子を授けてください。ヴェルディアの跡継ぎは、あなたとの子がいいの……だから、中で、いっぱい……！" },
    { id: "e36x", r18: true, name: "", text: "最奥深く腰を押し付け、熱い精液を解き放つ。セレナは子宮で受け止めるように腰を寄せ、注がれる感触に歓喜の涙を零した。溢れた白濁が、結合部から太ももへと伝う。" },
    { id: "e37x", face: "love", r18: true, name: "セレナ", text: "あぁ……熱い……いっぱい、注いでくれましたね……。わたしのお腹、あなたの愛で満ちています。……ねえ悠太、今夜はまだ、終わりにしたくありません。もう一度、わたしを愛してください。", jump: "e50" },
    { id: "e38x", r18: true, name: "", text: "夜明け前まで、二人は幾度も愛し合った。腕の中で眠るセレナの寝顔を見ながら、俺は誓った。この人を、一生守っていこうと。" },
    { id: "e25", face: "smile", bg: "room", name: "セレナ", text: "おはようございます、悠太。……ふふ、もう『先生』じゃないのですね。これからは二人で、この館に幸せを灯していきましょう。", jump: "e180" },
    { id: "e39", bg: "garden", name: "", text: "ある日の授業後、セレナに誘われて庭園を歩いた。バラのアーチの下、彼女は少し寂しそうに微笑む。", jump: "e218" },
    { id: "e40", face: "sad", char: true, name: "セレナ", text: "この庭は、亡き母が愛した場所なんです。母が逝ってから、わたしはずっとこの館で一人でした。……でも、あなたが来てくれて、景色が変わって見えるの。" },
    { id: "e41", name: "悠太", text: "セレナさん。俺はただの家庭教師ですけど……話なら、いくらでも聞きます。あなたの孤独を、少しでも分けてもらえたら。" },
    { id: "e42", face: "smile", name: "セレナ", text: "……優しい方ですね、先生は。ふふ、危ないですよ。そんなことを言われたら、わたし、本気になってしまいます。" },
    { id: "e43", name: "", text: "セレナの瞳が、真っ直ぐに俺を見つめていた。夕日の庭園で、その横顔が忘れられないほど美しかった。", jump: "e142" },
    { id: "e50", r18: true, name: "", text: "セレナの望みに応え、二度目の愛の時間が始まる。今度は彼女のベッドルームで、月明かりだけを灯りに。セレナは自ら紐を解き、大胆に肌を晒した。" },
    { id: "e51", r18: true, name: "セレナ", text: "悠太……今度は、わたしがあなたを気持ちよくします。横になってください。……令嬢の奉仕、受け取ってくださいね。" },
    { id: "e52", r18: true, name: "", text: "セレナは胸を押し付けながら体を滑らせ、やがて俺のものを口に含んだ。初めての奉仕は熱心で、大きな乳房の谷間に挟み、舌を絡め、吸い付くたびに喉を鳴らす。" },
    { id: "e53", face: "pleasure", r18: true, name: "セレナ", text: "んっ、んんっ……悠太の、熱くて、大きい……。わたしの口と胸で、こんなに反応してくれて……嬉しい。……ねえ、もう限界でしょう？　わたしの中に、来てください。" },
    { id: "e54", r18: true, name: "", text: "セレナが自ら跨り、濡れそぼった秘部で先端を捉える。二度目となる膣は素直に開き、彼女は歓喜の声を上げながらゆっくりと腰を沈めていった。" },
    { id: "e55", r18: true, name: "セレナ", text: "あぁっ……入ってきました……わたし、自分から悠太を求めてる……淑女にあるまじき姿ですね。でも、止められないの……もっと、あなたを感じたい……" },
    { id: "e56", r18: true, name: "", text: "大きな乳房を揺らしながら、セレナは夢中で腰を振る。膣壁はうねるように絡みつき、二人の結合部からは愛液と白濁の混じった雫が伝った。" },
    { id: "e57", face: "pleasure", r18: true, name: "セレナ", text: "あんっ、あんっ、あぁ……！　悠太、気持ちいいです……！　わたしの体、あなたのものだと叫んでいます……もっと奥まで、ください……！" },
    { id: "e58", r18: true, name: "", text: "腰を掴んで下から突き上げると、セレナは大きく絶頂した。抱き合う正常位に移り、深く密着したまま求め合う。彼女は耳元で愛を囁き続けた。" },
    { id: "e59", face: "love", r18: true, name: "セレナ", text: "悠太、愛しています……一生、あなたのそばにいます。……ねえ、最期はまた、中にください。わたしのお腹、あなたの愛でいっぱいにして……" },
    { id: "e60", r18: true, name: "", text: "限界を迎え、最奥で二度目の射精。セレナは子宮で受け止めるように腰を寄せ、注がれる熱に幸福そうに目を細めた。白濁が溢れ、シーツに広がっていく。" },
    { id: "e61", face: "love", r18: true, name: "セレナ", text: "あぁ……二回も、いっぱい……わたしのお腹が、あなたの愛で満ちています。……悠太、約束してください。この館で、わたしと家庭を築いてくれるって。", jump: "e38x" },
    { id: "e62", bg: "mansion", name: "", text: "――数週間後。俺は家庭教師を辞め、正式にヴェルディア邸に住み込みで働き始めた。セレナとの関係は、使用人たちの間でも公然の秘密になりつつある。", jump: "e104" },
    { id: "e63", face: "serious", char: true, name: "セレナ", text: "悠太。今日は大切なお話があります。……わたし、あの夜以来、体の調子が変わったの。もしかしたら、ヴェルディアの跡継ぎを、もう宿しているかもしれません。" },
    { id: "e64", name: "悠太", text: "セレナ……本当か。俺と結婚してくれ。身分なんて関係ない。俺は一生、君とこの館を守る。" },
    { id: "e65", face: "love", name: "セレナ", text: "……！　悠太……はい、喜んで。わたしはあなたの妻になります。今夜は、その誓いの夜にしましょう。わたしの部屋で、朝まで愛し合ってください。" },
    { id: "e66", bg: "room", name: "", text: "セレナの寝室。キャンドルの灯りの中、彼女は自らドレスを脱ぎ、月の光に白い肌を晒した。令嬢の気品と、女の色香が同居する姿に息を呑む。" },
    { id: "e67", r18: true, name: "セレナ", text: "悠太……今夜は誓いの夜。わたしの体も心も、正式にあなたのものです。……たっぷりと、跡継ぎの種を注いでくださいね。" },
    { id: "e68", r18: true, name: "", text: "深く唇を重ね、大きな乳房を掌で揉む。セレナは甘い声を漏らしながら自ら脚を開き、濡れた秘部へ俺の手を導いた。" },
    { id: "e69", r18: true, name: "セレナ", text: "あぁん……悠太、わたし、もうこんなに濡れて……あなたの手が触れるだけで、体が疼くの。下も、奥も、全部あなたに開かれています……" },
    { id: "e70", r18: true, name: "", text: "指で解し、舌で舐め上げると、セレナはベッドシーツを掴んで絶頂を迎えた。蕩けた瞳で俺を見上げ、震える声で乞うてくる。" },
    { id: "e71", r18: true, name: "セレナ", text: "悠太……早く、わたしの中に来てください。今夜は特別なの。あなたの妻になる女の中に、愛の証を刻んで……" },
    { id: "e72", r18: true, name: "", text: "脚を抱え上げ、一気に最奥まで貫く。セレナは大きく背を反らせ、歓喜の嬌声を上げた。膣壁は強く締め付け、抽送のたびに愛液が溢れる。" },
    { id: "e73", face: "pleasure", r18: true, name: "セレナ", text: "あぁん、あぁっ……！　悠太、深い、すごい……！　わたしの中、全部あなたです……気持ちいい、幸せで壊れてしまいそう……！" },
    { id: "e74", r18: true, name: "", text: "体位を変え、セレナが跨って腰を振る。月明かりに大きな乳房が揺れ、令嬢らしからぬ淫らな姿で自ら深く沈み込ませた。何度も絶頂を繰り返し、彼女は俺を求め続ける。" },
    { id: "e75", face: "pleasure", r18: true, name: "セレナ", text: "あんっ、あんっ……！　悠太、見ていてください……あなたの妻が、あなたのために乱れる姿を……もっと、もっと愛してください……！" },
    { id: "e76", r18: true, name: "", text: "限界が近づくと、セレナは脚を絡め、子宮を最奥へと寄せてきた。涙で潤んだ瞳が、真っ直ぐに俺を射抜く。" },
    { id: "e77", r18: true, name: "セレナ", text: "中に出してください、悠太……！　わたしのお腹に、跡継ぎを授けて……！　あぁっ、イク、わたしもイッてしまいます……一緒に……！！" },
    { id: "e78", r18: true, name: "", text: "最奥深くで射精。セレナは絶頂と共に受け止め、注がれる熱に幸福の涙を零した。白濁が溢れ、二人の愛の証となってシーツに広がる。" },
    { id: "e79", face: "love", r18: true, name: "セレナ", text: "あぁ……いっぱい……今夜、きっと決まりましたね。……悠太、愛しています。わたしたちの子と一緒に、この館で幸せな家庭を築きましょう。", jump: "e86" },
    { id: "e80", bgm: "love", bg: "garden", name: "", text: "――結婚式の朝。庭園の白いバラのアーチの下で、セレナは母の形見の白いバラを胸に挿し、まっすぐに俺を見つめていた。\n「悠太。……わたくしは、今日からあなたの妻ですわ。……そして、この子のお母さんに、なるんですのね」\n誓いの言葉が、バラの香りに包まれて静かに響いた。やがてこの庭園に、小さな足音と笑い声が満ちるだろう。家庭教師と令嬢の恋は、白いバラのアーチの下で、家族の物語へと姿を変えた。\n【GOOD END ― セレナの館】", end: true },
    { id: "e81", bg: "garden", name: "", text: "――回想：ある日の午後。セレナは慣れない手つきでキッチンに立ち、手料理に挑戦していた。" },
    { id: "e82", char: true, name: "セレナ", text: "悠太、見ていてくださいまし。今日はわたくしが、故郷の郷土料理を作りますの。……あら、玉ねぎって、切ると目が痛くなるものですのね……。" },
    { id: "e83", name: "悠太", text: "セレナ、涙目じゃないか。大丈夫、俺も手伝うよ。二人で作れば、きっと美味しくなる。" },
    { id: "e84", face: "smile", name: "セレナ", text: "……ふふ、ありがとう。誰かとキッチンに立つのは、初めてですわ。……ねえ悠太、完成したら最初の一口は、あなたに。約束ですわよ。" },
    { id: "e85", name: "", text: "下手くそで、温かい夕食だった。この館に『二人で作る味』が生まれた日――きっと、忘れない。", jump: "e05" },
    { id: "e86", face: "love", bg: "room", r18: true, name: "セレナ", text: "……悠太、まだ眠らないで。誓いの夜は、まだ終わりじゃないの。……わたし、もう一度だけ。あなたの愛を、体で確かめさせて？" },
    { id: "e87", r18: true, name: "", text: "キャンドルの灯りの中、セレナは自らドレスを脱ぎ、月の光に白い肌を晒した。令嬢の気品と、女の色香が同居する姿に、改めて息を呑む。" },
    { id: "e88", face: "smile", r18: true, name: "セレナ", text: "ねえ悠太。結婚式のこと、考えてくれた？　わたし、庭園で挙げたいの。バラのアーチの下で、あなたと誓いを交わすの。……ふふ、気が早いかしら。" },
    { id: "e89", r18: true, name: "悠太", text: "……いいな。バラのアーチか。セレナに似合うよ。……その前に、まずは今夜だ。誓いの夜は、まだ終わってないだろ？" },
    { id: "e90", face: "pleasure", r18: true, name: "セレナ", text: "んっ……悠太、ずるい。そんな顔で言われたら、わたし……。ねえ、わたしの胸、触って。あなたのためだけに、こんなに張っているの……" },
    { id: "e91", r18: true, name: "", text: "ドレスの紐を解き、白い肌を月明かりに晒す。大きな乳房を掌で包み、乳首を指で転がすと、セレナは小さく喘ぎながら俺の胸に倒れ込んできた。" },
    { id: "e92", r18: true, name: "セレナ", text: "あぁん……悠太、そこ……わたし、体が熱くてたまらないの。……下も、触ってください。わたしがどれだけあなたを欲しがっているか、確かめて……" },
    { id: "e93", r18: true, name: "", text: "下着の中へ手を滑らせると、秘部は既に愛液で溢れていた。陰唇を割り開き、ゆっくりと指を沈める。熱い内壁が、吸い付くように絡んでくる。" },
    { id: "e94", face: "pleasure", r18: true, name: "セレナ", text: "あっ、あぁっ……！　悠太、悠太ぁ……！　わたし、もう……イッてしまいます……あああっ……！！" },
    { id: "e95", r18: true, name: "", text: "指だけで絶頂を迎え、セレナは荒い息を吐いた。それでも俺を求める瞳は潤んだまま。ベッドに横たわらせ、脚をそっと開くと、彼女は両手で顔を覆いながらも拒まなかった。" },
    { id: "e96", face: "love", r18: true, name: "セレナ", text: "来てください、悠太……わたしの全部を、あなたに捧げます。……今夜は、妻になる女を、たっぷり愛してください……" },
    { id: "e97", r18: true, name: "", text: "先端を割り当て、ゆっくりと腰を進める。二度目となる膣は素直に開き、セレナは歓喜の声を上げながら、自ら腰を寄せてきた。最奥まで収まった瞬間、二人は深く息を吐く。" },
    { id: "e98", face: "pleasure", r18: true, name: "セレナ", text: "あぁっ、あんっ……！　悠太、気持ちいい、気持ちいいです……！　もっと、もっと激しく……わたしを、あなたの色に染めてください……！" },
    { id: "e99", r18: true, name: "", text: "腰の速度を上げ、深く突き上げる。セレナはシーツを握りしめ、涙目で喘ぎながら何度も絶頂を迎えた。その淫らで美しい姿は、俺だけの特権だった。" },
    { id: "e100", face: "love", r18: true, name: "セレナ", text: "イグ、またイッてしまいます……！　悠太、愛しています……！　あぁっ、もう、わたしはあなたのものです、一生……！" },
    { id: "e101", r18: true, name: "", text: "限界を迎えた俺に、セレナは脚を絡めて囁く。月明かりに照らされた顔は、幸福と快感に蕩けていた。" },
    { id: "e102", r18: true, name: "セレナ", text: "中に出してください、悠太……！　わたしのお腹に、あなたの子を授けてください。ヴェルディアの跡継ぎは、あなたとの子がいいの……だから、中で、いっぱい……！" },
    { id: "e103", r18: true, name: "", text: "最奥深く腰を押し付け、熱い精液を解き放つ。セレナは子宮で受け止めるように腰を寄せ、注がれる感触に歓喜の涙を零した。――抱き合ったまま、二人は静かに眠りに落ちた。", jump: "e124" },
    { id: "e104", bg: "garden", name: "", text: "――その週末。セレナに誘われ、麓の町へ買い物に出かけた。令嬢の外出は珍しく、使用人のマルタが、こっそりと見送ってくれた。" },
    { id: "e105", char: true, name: "セレナ", text: "悠太、見てくださいまし。この町、わたし、久しぶりですの。……館を出るの、なんだか、わくわくしますわ。" },
    { id: "e106", name: "悠太", text: "……セレナ、そんなに楽しみなんですか。……ふふ、まるで初めての遠足みたいですね。……今日は、どこに行きたいですか？" },
    { id: "e107", face: "smile", name: "セレナ", text: "……ふふ、そうですね。……まずは、市場ですわ。……今夜の夕食の材料を、わたくしが選ぶのです。……ねえ、手伝ってくださいまし。" },
    { id: "e108", name: "", text: "市場では、セレナが野菜を手に取り、真剣に品定めをしていた。令嬢の買い物は、少しだけ不器用で、でも一生懸命だった。" },
    { id: "e109", face: "shy", name: "セレナ", text: "悠太、このトマト、どうです？　……赤くて、つやつやしてますわ。……ねえ、こっちの方が、甘そうかしら。" },
    { id: "e110", name: "悠太", text: "……どっちも美味しそうですよ。……セレナ、野菜の見分け方、詳しいんですね。……料理、また挑戦するんですか？" },
    { id: "e111", face: "smile", name: "セレナ", text: "……ふふ、ええ。……前回の手料理、失敗しちゃいましたけど、懲りてませんわ。……ねえ、今夜こそ、美味しい夕食を作りますの。" },
    { id: "e112", name: "", text: "買い物を終えて、町はずれの小さなカフェへ。セレナは、窓際の席で、紅茶をそっと口にした。" },
    { id: "e113", name: "セレナ", text: "……悠太。……ねえ、わたし、こんなふうに町を歩くの、久しぶりですの。……館の中だけだと、世界が小さく見えるの。" },
    { id: "e114", name: "悠太", text: "……セレナ。……今日は、たくさん歩きましょう。……町も、海も、山も。……セレナの見たいもの、全部見せますよ。" },
    { id: "e115", face: "smile", name: "セレナ", text: "……っ！　悠太……。……ふふ、ありがとうございます。……ねえ、わたし、あなたと出会えて、ほんとに幸せですわ。" },
    { id: "e116", name: "", text: "カフェを出て、セレナは小さな花屋の前で足を止めた。バラの花束を、そっと手に取る。" },
    { id: "e117", name: "セレナ", text: "……ねえ悠太。……このバラ、庭園のバラに似てますわ。……母が愛した花。……ねえ、買っていっても、いいかしら。" },
    { id: "e118", name: "悠太", text: "……もちろんです。……セレナ、バラの花束、似合いますよ。……ねえ、俺が買います。……今日の記念に。" },
    { id: "e119", face: "smile", name: "セレナ", text: "……っ！　悠太……。……ふふ、ありがとうございます。……ねえ、わたし、この花束、館の玄関に飾りますわ。……悠太からの、初めての贈り物ですもの。" },
    { id: "e120", name: "", text: "夕方、荷物を抱えて館へ戻る。セレナの手にはバラの花束。……令嬢の笑顔は、町で一番、輝いていた。" },
    { id: "e121", name: "セレナ", text: "……ねえ悠太。……今日、すごく楽しかったですわ。……ねえ、今夜の夕食、わたくしが作りますの。……見ていてくださいましね。" },
    { id: "e122", name: "悠太", text: "……はい、楽しみにしてます。……セレナの手料理、今度こそ、美味しくできますよ。……俺も、手伝います。" },
    { id: "e123", face: "smile", name: "セレナ", text: "……ふふ、ありがとうございます。……ねえ悠太、館に戻ったら、わたしの部屋に来てくださいまし。……大切なお話がありますの。", jump: "e63" },
    { id: "e124", bg: "room", r18: true, name: "", text: "――結婚式の日取りが決まった夜。セレナは教会のパンフレットを広げ、俺の部屋に来た。瞳が、少しだけ潤んでいる。" },
    { id: "e125", face: "smile", r18: true, name: "セレナ", text: "悠太、見てくださいまし。……春の結婚式ですの。……ねえ、わたし、綺麗な花嫁になれるかしら。" },
    { id: "e126", r18: true, name: "悠太", text: "セレナ……世界一、綺麗な花嫁になりますよ。……俺、セレナと結婚できるなんて、夢みたいです。" },
    { id: "e127", r18: true, name: "", text: "セレナはパンフレットをそっと閉じ、俺の胸に頬を寄せた。鼓動が、少しだけ早い。" },
    { id: "e128", r18: true, name: "セレナ", text: "ねえ、悠太……今夜は、特別な夜ですわ。……ねえ、わたくしを、抱いてくださいまし……花嫁になる、わたくしの全部を、あなたに確かめてほしいの。" },
    { id: "e129", r18: true, name: "", text: "頷くと、セレナは俺の首に腕を回し、そっと唇を重ねてきた。バラの香りと、少しの緊張。" },
    { id: "e130", face: "pleasure", r18: true, name: "セレナ", text: "んっ……悠太……優しい……ねえ、もっと、近くに来てくださいまし……" },
    { id: "e131", r18: true, name: "", text: "ベッドに横たわり、セレナは自ら俺の服を脱がせていく。大きな乳房が、月明かりに白く浮かぶ。" },
    { id: "e132", r18: true, name: "セレナ", text: "ねえ、見て……わたくしの体、もう……あなたのものよ。……ほら、ここ、熱くなってますわ。……ねえ悠太、触って……確かめて？" },
    { id: "e133", r18: true, name: "", text: "乳房を包むように揉むと、セレナは甘い声を漏らした。先端はすっかり硬くなり、彼女の吐息が熱い。" },
    { id: "e134", r18: true, name: "セレナ", text: "あぁっ……悠太……深い……奥まで、届いてますわ……ねえ、もう……もっと……" },
    { id: "e135", r18: true, name: "", text: "濡れそぼった秘部に、ゆっくりと腰を沈める。セレナは俺の背中にしがみつき、歓喜の声を上げた。" },
    { id: "e136", r18: true, name: "セレナ", text: "もっと……もっと激しく……わたくし、悠太の前では、素直になれますの。……ねえ、もっと奥まで……" },
    { id: "e137", r18: true, name: "", text: "夢中で腰を振るセレナ。膣壁がうねるように絡みつき、結合部からは愛液が溢れて太ももを伝う。俺は乳房を揉みながら、下から突き上げた。" },
    { id: "e138", r18: true, name: "セレナ", text: "中に出してくださいまし……ねえ、悠太……わたくしのお腹に、あなたの子を……もう一度、注いでくださいまし……" },
    { id: "e139", r18: true, name: "", text: "最奥深く腰を押し付け、熱い精液を解き放つ。セレナは子宮で受け止めるように腰を寄せ、注がれる感触に歓喜の涙を零した。" },
    { id: "e140", r18: true, name: "セレナ", text: "あぁ……いっぱい……ねえ悠太、わたくしね、もう決めましたの。……この子が生まれたら、庭園でお披露目するのですわ。" },
    { id: "e141", r18: true, name: "", text: "抱き合ったまま、二人は静かに眠りに落ちた。――山間の洋館に、やがて新しい命の泣き声が響く。家庭教師と令嬢の恋は、家族の物語へと姿を変えた。", jump: "e256" },
    { id: "e256", bg: "mansion", name: "", text: "――数日後、二人で麓の町の診療所を訪れた。診察室の白い光の中で、医師は穏やかに頷き、確かな言葉をくれた。\n「……本当、なんですのね。わたくしのお腹に、あなたの子が……」\n帰り道、セレナは俺の袖を離さなかった。洋館へ続く坂道は、いつもより静かで、明るかった。", jump: "e162" },
    { id: "e142", bg: "garden", name: "", text: "――夕日の庭園。セレナはバラの手入れを終え、俺を庭園のテーブルへと招いた。白いテーブルクロスの上に、ティーセットが並んでいる。" },
    { id: "e143", name: "セレナ", text: "悠太、見てくださいまし。……今日のバラ、綺麗に咲きましたわ。……ねえ、お茶でもいかが？　……わたくしが淹れますわ。" },
    { id: "e144", name: "悠太", text: "セレナ、バラ……綺麗ですね。……俺、庭園でお茶なんて、初めてです。" },
    { id: "e145", name: "", text: "セレナは笑いながら、ティーポットに湯を注いだ。紅茶の香りが、夕日の庭園にゆっくりと広がっていく。" },
    { id: "e146", face: "smile", name: "セレナ", text: "ふふ、わたくしね、幼い頃からこうして庭園でお茶を飲むのが好きでしたの。……一人で飲むより、誰かと飲む方が美味しいのですわ。" },
    { id: "e147", name: "", text: "紅茶の香りが、庭園いっぱいに広がった。セレナはカップを二つ並べ、丁寧に注いでいく。その横顔は、家庭教師のときとは違う、柔らかい表情だった。" },
    { id: "e148", name: "悠太", text: "……美味しい。……本当に、美味しいです、セレナ。……庭園で飲む紅茶って、こんなに特別なんですね。" },
    { id: "e149", name: "セレナ", text: "でしょ？　……わたくしね、庭園が煮詰まったときは、いつもこうして紅茶を淹れるのですわ。……香りで、心をリセットするのですわ。" },
    { id: "e150", name: "", text: "セレナはバラの花を見ながら、少しだけ遠い目をした。夕日の庭園に、バラの香りがゆっくりと広がっていく。" },
    { id: "e151", face: "smile", name: "セレナ", text: "ねえ悠太……わたくしの夢、笑いませんわよね？　……この庭園を、もっとたくさんの人に見てもらいたいの。……バラ園を開くなんて、無謀かしら。" },
    { id: "e152", name: "悠太", text: "笑いませんよ。……セレナのバラ、こんなに綺麗なんですから。……絶対、たくさんの人が来ますよ。……俺、最初のお客さんになります。" },
    { id: "e153", name: "", text: "セレナは瞳を潤ませ、嬉しそうに微笑んだ。夕日の庭園に、二人分の紅茶の湯気がゆっくりと立ちのぼる。" },
    { id: "e154", face: "serious", name: "セレナ", text: "……ありがとう、悠太。……ねえ、約束してくださいまし？　……わたくしのバラ園ができたら、一番最初のお客さんになって。" },
    { id: "e155", name: "悠太", text: "もちろんです。……一番乗りで、行きますよ。……そのときは、バラの花束を一つください。" },
    { id: "e156", face: "smile", name: "セレナ", text: "ふふ、了解ですわ。……じゃあ、わたくしも約束しますわ。……悠太の分は、いつも特別な花束を用意しますわ。" },
    { id: "e157", name: "", text: "紅茶を飲み終え、二人で庭園を歩いた。夕日の光が、バラの花びらを柔らかく照らしている。" },
    { id: "e158", name: "セレナ", text: "ねえ、今日はこのまま帰るの、もったいないですわね。……よかったら、温室まで歩きませんこと？　……夜の庭園、静かで好きですわ。" },
    { id: "e159", name: "悠太", text: "いいですね。……セレナと歩く夕日の庭園、なんだか特別な気がします。……ほら、温室の前、街灯が綺麗ですよ。" },
    { id: "e160", name: "", text: "並んで歩く庭園の小道。セレナの肩が、そっと俺の肩に触れる。紅茶の香りも、バラの香りも、全部、少しだけ温かく感じられた。" },
    { id: "e161", name: "セレナ", text: "……ねえ悠太。……今日の紅茶、美味しかった？　……うん、よかった。……また淹れますわね、次も。", jump: "e81" },
    { id: "e162", bg: "room", r18: true, name: "", text: "――マタニティドレスを試着した夜。セレナは鏡の前でドレスを広げ、俺の部屋で嬉しそうに笑った。バラの香りが、静かに漂っている。" },
    { id: "e163", face: "smile", r18: true, name: "セレナ", text: "悠太、見てくださいまし。……わたくし、マタニティドレスですの。……ねえ、わたくし、綺麗かしら。" },
    { id: "e164", r18: true, name: "悠太", text: "セレナ……とても、綺麗ですよ。……花嫁のドレスも、きっと世界一似合います。" },
    { id: "e165", r18: true, name: "", text: "セレナはドレスの裾をそっと撫で、俺の胸に頬を寄せた。お腹の子の分まで、胸が高鳴っている気がした。" },
    { id: "e166", r18: true, name: "セレナ", text: "ねえ、悠太……今夜は、特別な夜ですわ。……ねえ、わたくしを、抱いてくださいまし……この子のためにも、愛を確かめたいのですわ。" },
    { id: "e167", r18: true, name: "", text: "頷くと、セレナはマタニティドレスのレースを指先で辿りながら、そっと唇を重ねてきた。バラの香りと、新しい命を宿した体温。" },
    { id: "e168", face: "pleasure", r18: true, name: "セレナ", text: "んっ……悠太……ねえ、このドレスの下のわたくしも……ちゃんと、愛してくださいまし……" },
    { id: "e169", r18: true, name: "", text: "ベッドに横たわると、セレナはドレスを丁寧に畳んで椅子に掛け、それから俺の服を脱がせていく。膨らみを増した乳房が、月明かりに白く浮かぶ。" },
    { id: "e170", r18: true, name: "セレナ", text: "ねえ、見て……このお腹、少しずつ大きくなってますの。……ねえ悠太、ここに……この子の鼓動、触って……感じて？" },
    { id: "e171", r18: true, name: "", text: "ドレス越しでは分からなかった柔らかさを確かめるように乳房を包むと、セレナは甘い声を漏らした。母になる体は、どこか張りを増していた。" },
    { id: "e172", r18: true, name: "セレナ", text: "あぁっ……悠太……深い……この子の、すぐそばまで……届いてますわ……ねえ、優しく、もっと……" },
    { id: "e173", r18: true, name: "", text: "マタニティドレスを脱いだ体は、いつもより敏感だった。ゆっくりと腰を沈めると、セレナはお腹を庇うように俺の背中にしがみつき、歓喜の声を上げた。" },
    { id: "e174", r18: true, name: "セレナ", text: "もっと……もっと……この子のいる場所まで、愛して……わたくし、悠太の前では、お母さんの顔も忘れて、素直になれますの……" },
    { id: "e175", r18: true, name: "", text: "お腹の子を気遣ってか、セレナの動きは慎重で、それでも芯は熱かった。膣壁がうねるように絡みつき、俺は彼女の腰を支えながら、下からゆっくり突き上げた。" },
    { id: "e176", r18: true, name: "セレナ", text: "中に出してくださいまし……ねえ、悠太……もう宿っているこの子にも、届くくらい……あなたの愛で、いっぱいにしてくださいまし……" },
    { id: "e177", r18: true, name: "", text: "ドレスのレースが椅子の上で揺れる中、最奥深く腰を押し付け、熱い精液を解き放つ。セレナは両手でお腹を包み込むようにしながら腰を寄せ、静かに涙を零した。" },
    { id: "e178", r18: true, name: "セレナ", text: "あぁ……いっぱい……ねえ悠太、この子が生まれたら、庭園でお披露目するのですわ。……マタニティドレスも、もう一度着るのですわ。" },
    { id: "e179", r18: true, name: "", text: "抱き合ったまま、二人は静かに眠りに落ちた。マタニティドレスが、月明かりにそっと白く浮かんでいた。", jump: "e200" },
    { id: "e180", bg: "garden", name: "", text: "――翌朝。セレナは庭園のテーブルで、朝食の準備をしていた。バラの香りと、焼きたてのパンの匂いが漂う。" },
    { id: "e181", face: "smile", name: "セレナ", text: "おはようございます、悠太。……ふふ、昨日の夜のこと、覚えていらっしゃいますわね？　わたくしは、もう一生忘れませんわ。" },
    { id: "e182", name: "悠太", text: "もちろんです。……セレナ、朝から素敵ですね。庭園の朝食なんて、まるで夢みたいです。" },
    { id: "e183", face: "smile", name: "セレナ", text: "まあ、嬉しいことを。……さあ、座ってくださいまし。今日の朝食は、わたくしが用意しましたの。" },
    { id: "e184", name: "", text: "テーブルには、焼きたてのパンと、庭園のハーブティー。セレナは紅茶を注ぎながら、嬉しそうに微笑んだ。" },
    { id: "e185", name: "セレナ", text: "ねえ悠太、わたくしの夢、ご存知かしら。……この庭園を、もっとたくさんの人に開くの。バラ園としてね。" },
    { id: "e186", name: "悠太", text: "バラ園ですか。……セレナなら、きっと素敵な庭園になりますよ。" },
    { id: "e187", face: "smile", name: "セレナ", text: "ふふ、ありがとうございます。……その庭園でね、いつか、わたくしたちの結婚式を挙げるの。" },
    { id: "e188", name: "悠太", text: "結婚式……。……セレナ、もうそんな先のことまで考えてるんですね。" },
    { id: "e189", name: "セレナ", text: "ええ。だって、悠太はわたくしの、運命の人ですもの。……ねえ、バラの手入れ、手伝ってくださいます？" },
    { id: "e190", name: "", text: "食後、二人でバラの手入れを始める。セレナは剪定ばさみを手に、丁寧に枝を整えていった。" },
    { id: "e191", name: "セレナ", text: "このバラはね、わたくしが子供の頃に植えたの。……今では、庭園で一番大きな株ですわ。" },
    { id: "e192", name: "悠太", text: "すごいですね。……セレナの手で育ったバラなんですね。" },
    { id: "e193", name: "セレナ", text: "ええ。……このバラみたいに、わたくしたちの愛も、大きく育っていくのですわ。" },
    { id: "e194", name: "", text: "セレナはバラの花びらを一枚、俺の胸ポケットにそっと挿した。花びらは、朝の光にほのかに香る。" },
    { id: "e195", name: "セレナ", text: "ねえ悠太、今日の午後は、麓の町へ買い物に行きましょう。……結婚式の準備の、第一歩として。" },
    { id: "e196", name: "悠太", text: "いいですね。……じゃあ、庭園の手入れが終わったら、出かけましょう。" },
    { id: "e197", face: "smile", name: "セレナ", text: "まあ、楽しみですわ。……ふふ、恋人ができると、朝の庭園まで輝いて見えますわ。" },
    { id: "e198", name: "", text: "手入れを終え、二人で館へ戻る。セレナは俺の腕にそっと寄り添い、幸せそうに微笑んだ。" },
    { id: "e199", name: "", text: "――朝の庭園。二人の新しい日常が、バラの香りと共に始まっていた。", jump: "e62" },
    { id: "e200", bg: "room", r18: true, name: "", text: "――結婚式のリハーサルを終えた夜。セレナは教会のパンフレットを広げ、俺の部屋で嬉しそうに笑った。バラの香りが、静かに漂っている。" },
    { id: "e201", face: "smile", r18: true, name: "セレナ", text: "悠太、見てくださいまし。……今日のリハーサル、わたくし、ちゃんと歩けましたわ。……ねえ、わたくし、綺麗でしたかしら。" },
    { id: "e202", r18: true, name: "悠太", text: "セレナ……世界一、綺麗でしたよ。……本番の花嫁姿が、今から楽しみです。" },
    { id: "e203", r18: true, name: "", text: "セレナは腕を組んだまま、俺の胸に頬を寄せた。リハーサルで聞いた教会の鐘の音が、まだ耳の奥に残っている気がした。" },
    { id: "e204", r18: true, name: "セレナ", text: "ねえ、悠太……今夜は、特別な夜ですわ。……ねえ、わたくしを、抱いてくださいまし……リハーサルの、ご褒美ですわ。" },
    { id: "e205", r18: true, name: "", text: "頷くと、セレナは腕を組む仕草のまま――リハーサルで何度も繰り返したみたいに、そっと唇を重ねてきた。バラの香りと、確かな幸せ。" },
    { id: "e206", face: "pleasure", r18: true, name: "セレナ", text: "んっ……悠太……今日のわたくし、どうでしたかしら……この腕に、ずっと捕まっていてくださいまし……" },
    { id: "e207", r18: true, name: "", text: "ベッドに横たわり、セレナは自ら俺の服を脱がせていく。リハーサルのベールを外した髪が、月明かりに白く広がった。" },
    { id: "e208", r18: true, name: "セレナ", text: "ねえ、見て……今日、教会で歩いたわたくしと、同じ体ですわ。……ほら、ここ、熱くなってますわ。……ねえ悠太、今夜も、触って……確かめて？" },
    { id: "e209", r18: true, name: "", text: "乳房を包むように揉むと、セレナはリハーサルの優雅さを忘れたみたいに甘い声を漏らした。先端はすっかり硬くなり、彼女の吐息が熱い。" },
    { id: "e210", r18: true, name: "セレナ", text: "あぁっ……悠太……深い……バージンロードより、ずっと奥まで……届いてますわ……ねえ、もう……もっと……" },
    { id: "e211", r18: true, name: "", text: "濡れそぼった秘部に、ゆっくりと腰を沈める。セレナは腕を組んで歩いた昼間のままの確かさで俺の背中にしがみつき、歓喜の声を上げた。" },
    { id: "e212", r18: true, name: "セレナ", text: "もっと……もっと激しく……教会では凛々しく歩いたわたくしも、悠太の前では、こんなに素直になれますの。……ねえ、もっと奥まで……" },
    { id: "e213", r18: true, name: "", text: "夢中で腰を振るセレナ。リハーサルで覚えた歩幅なんか忘れて、膣壁がうねるように絡みついてくる。俺は乳房を揉みながら、下から突き上げた。" },
    { id: "e214", r18: true, name: "セレナ", text: "中に出してくださいまし……ねえ、悠太……結婚式の前に、もう一度……この子を宿したわたくしを、あなたの愛でいっぱいにしてくださいまし……" },
    { id: "e215", r18: true, name: "", text: "最奥深く腰を押し付け、熱い精液を解き放つ。セレナは今日歩いたバージンロードの先で待つ未来を思うみたいに腰を寄せ、注がれる感触に歓喜の涙を零した。" },
    { id: "e216", r18: true, name: "セレナ", text: "あぁ……いっぱい……ねえ悠太、この子が生まれたら、庭園でお披露目するのですわ。……結婚式の日に、みんなに紹介するのですわ。" },
    { id: "e217", r18: true, name: "", text: "抱き合ったまま、二人は静かに眠りに落ちた。――山間の洋館に、やがて新しい命の泣き声が響く。花嫁の物語は、家族の物語へと姿を変えた。", jump: "e238" },
    { id: "e218", bg: "garden", name: "", text: "――ある日の授業後、セレナに誘われて庭園を歩いた。バラのアーチの下、彼女は少し寂しそうに微笑む。夕日の光が、バラの花びらを柔らかく照らしている。" },
    { id: "e219", name: "セレナ", text: "悠太、見てくださいまし。……このバラ、今日、やっと咲いたのですわ。……わたくしが、手入れをしたバラですの。" },
    { id: "e220", name: "悠太", text: "ほんとに、綺麗に咲いてますね。……セレナの手入れのおかげですよ。……バラも、セレナに感謝してますよ。" },
    { id: "e221", name: "", text: "セレナはバラの花にそっと触れ、嬉しそうに微笑んだ。庭園には、バラの香りがゆっくりと広がっている。" },
    { id: "e222", face: "smile", name: "セレナ", text: "……ふふ、ありがとうございます。……ねえ悠太、バラの剪定って、難しいのですわ。……切りすぎると、咲かなくなっちゃうの。" },
    { id: "e223", name: "悠太", text: "そうなんですか。……セレナ、剪定も自分でやるんですね。……令嬢なのに、すごいですよ。" },
    { id: "e224", name: "", text: "セレナは剪定ばさみを手に取り、バラの枝を丁寧に整え始めた。手つきは少しだけ不器用で、でも真剣だった。" },
    { id: "e225", name: "セレナ", text: "……わたくしね、庭園のバラは、家族みたいなものなのですわ。……お母様が植えたバラも、ここにあるの。" },
    { id: "e226", name: "悠太", text: "お母様が……ですか。……セレナ、お母様のバラ、どれなんですか？" },
    { id: "e227", name: "", text: "セレナは少しだけ遠い目をして、庭園の奥のバラを指さした。白いバラが、夕日の光に静かに揺れている。" },
    { id: "e228", name: "セレナ", text: "……あれですわ。……白いバラ。……お母様は、白いバラがお好きでしたの。……わたくしも、ね。" },
    { id: "e229", name: "悠太", text: "白いバラ……綺麗ですね。……セレナ、お母様のバラ、俺も一緒に手入れさせてください。……二人で、守りましょう。" },
    { id: "e230", name: "", text: "セレナは瞳を潤ませ、嬉しそうに微笑んだ。夕日の庭園に、白いバラの香りがゆっくりと立ちのぼる。" },
    { id: "e231", face: "smile", name: "セレナ", text: "……ありがとうございます、悠太。……ねえ、バラの花言葉、知ってますかしら。……白いバラは、「純潔」ですの。" },
    { id: "e232", name: "悠太", text: "「純潔」……ですか。……セレナに、ぴったりの花ですね。……白いバラ、セレナみたいに綺麗です。" },
    { id: "e233", name: "", text: "セレナは頬を染め、バラの花びらを一枚、俺の胸ポケットにそっと挿した。花びらは、夕日の光にほのかに香る。" },
    { id: "e234", face: "love", name: "セレナ", text: "……ねえ悠太。……いつか、この庭園で、結婚式を挙げたいですわ。……白いバラのアーチの下で。……ねえ、いいかしら。" },
    { id: "e235", name: "悠太", text: "もちろんです。……セレナ、約束ですよ。……白いバラのアーチの下で、必ず。" },
    { id: "e236", name: "", text: "セレナは俺の腕にそっと寄り添い、幸せそうに微笑んだ。並んで歩く庭園の小道に、二人の影が寄り添うように伸びていく。" },
    { id: "e237", name: "", text: "――バラのアーチの下の散歩は、こうして終わった。白いバラの花びらが、夕日の光にそっと舞い落ちていた。", jump: "e40" },
    { id: "e238", bg: "room", r18: true, name: "", text: "――結婚式前夜。セレナはウェディングドレスを広げ、俺の部屋で嬉しそうに笑った。白いバラの香りが、静かに漂っている。" },
    { id: "e239", face: "smile", r18: true, name: "セレナ", text: "悠太、見てくださいまし。……明日、わたくし、このドレスを着るのですわ。……ねえ、わたくし、綺麗かしら。" },
    { id: "e240", r18: true, name: "悠太", text: "セレナ……世界一、綺麗ですよ。……明日の花嫁姿が、今から楽しみです。……俺の、世界一の花嫁です。" },
    { id: "e241", r18: true, name: "", text: "セレナはドレスをそっとハンガーに掛け直し、俺の胸に頬を寄せた。明日への緊張が、触れた頬から伝わってくる。" },
    { id: "e242", r18: true, name: "セレナ", text: "ねえ、悠太……今夜は、特別な夜ですわ。……ねえ、わたくしを、抱いてくださいまし……結婚式前夜の、ご褒美ですわ。" },
    { id: "e243", r18: true, name: "", text: "頷くと、セレナは明日着るドレスに一度だけ目をやってから、そっと唇を重ねてきた。白いバラの香りと、静かな決意。" },
    { id: "e244", face: "love", r18: true, name: "セレナ", text: "んっ……悠太……明日が来るのが、怖くて、嬉しいの……ねえ、今夜だけは、離さないでくださいまし……" },
    { id: "e245", r18: true, name: "", text: "窓の外では、明日の式の支度を終えた庭園が静まり返っている。セレナは自ら俺の服を脱がせていき、大きな乳房が月明かりに白く浮かんだ。" },
    { id: "e246", r18: true, name: "セレナ", text: "ねえ、見て……明日、花嫁になるわたくしの体、もう……あなたのものよ。……ねえ悠太、今夜のうちに、全部……触って、確かめて？" },
    { id: "e247", r18: true, name: "", text: "乳房を包むように揉むと、セレナは明日の花嫁とは思えないほど素直な甘い声を漏らした。その吐息は、前夜の緊張ごと熱かった。" },
    { id: "e248", r18: true, name: "セレナ", text: "あぁっ……悠太……深い……明日の朝には言えないこと、全部……奥まで、届いてますわ……ねえ、もっと……" },
    { id: "e249", r18: true, name: "", text: "濡れそぼった秘部に、ゆっくりと腰を沈める。セレナは明日の誓いの言葉を噛みしめるみたいに俺の背中にしがみつき、歓喜の声を上げた。" },
    { id: "e250", r18: true, name: "セレナ", text: "もっと……もっと激しく……明日、みんなの前では言えないわたくしを、今夜、全部見てくださいまし。……ねえ、もっと奥まで……" },
    { id: "e251", r18: true, name: "", text: "夢中で腰を振るセレナ。明日はドレスで隠す体が、今夜だけは月明かりの下で揺れている。結合部からは愛液が溢れて太ももを伝い、俺は下から突き上げた。" },
    { id: "e252", r18: true, name: "セレナ", text: "中に出してくださいまし……ねえ、悠太……明日の式を前に、もう一度……この子を宿したわたくしを、あなたの愛でいっぱいにしてくださいまし……" },
    { id: "e253", r18: true, name: "", text: "窓の外で明日の鐘が静まり返る中、最奥深く腰を押し付け、熱い精液を解き放つ。セレナは子宮で受け止めるように腰を寄せ、『明日、妻になりますわ』と涙ながらに囁いた。" },
    { id: "e254", r18: true, name: "セレナ", text: "あぁ……いっぱい……ねえ悠太、明日は母さまの形見のバラを挿して、白いバラのアーチの下で、あなたの妻になりますの。……この子も一緒ですわ、ね？" },
    { id: "e255", r18: true, name: "", text: "抱き合ったまま、二人は静かに眠りに落ちた。――白いバラのアーチの下、やがて花嫁の物語は、家族の物語へと姿を変えた。", jump: "e80" }
  ]
}
];
